#include <stdio.h>
#include <string.h>

char s[1000];
int palindrome_partitions[1000][1000];
int dp[1000][1000];
int n;

int isPalindrome(int i, int j){
    int k;
    for(k = 0; k <= (j - i); k++){
        if(s[i+k] != s[j-k]){
            return 0;
        }
    }
    return 1;
}

int partition(int i, int j){
    if(dp[i][j] != -1)
        return dp[i][j];

    if(i > j)
        return 0;

    if(isPalindrome(i, j) == 1)
        return dp[i][j] = 1;

    for(int k = i; k <= j; k++){
        if(isPalindrome(i, k) && partition(k+1, j) == 1){
            return dp[i][j] = 1;
        }
    }
    return dp[i][j] = 0;
}

int main(){
    scanf("%s", s);
    n = strlen(s);

    memset(dp, -1, sizeof(dp));
    if(partition(0, n-1) == 1){
        printf("The given string is palindrome-partitionable\n");
        printf("Partition(s):\n");
        int start = 0, end;
        for(int i = 0; i < n; i++){
            for(end = start; end < n; end++){
                if(partition(start, end) == 1){
                    printf("Substring %d-%d: %s\n", start, end, s+start);
                    start = end+1;
                    break;
                }
            }
        }
    }
    else{
        printf("The given string is not palindrome-partitionable\n");
    }
    return 0;
}

#include <stdio.h>

void merge(int arr[], int l, int m, int r) {
    int i, j, k;
    int n1 = m - l + 1;
    int n2 = r - m;

    int L[n1], R[n2];

    for (i = 0; i < n1; i++)
        L[i] = arr[l + i];
    for (j = 0; j < n2; j++)
        R[j] = arr[m + 1 + j];

    i = 0;
    j = 0;
    k = l;
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) {
            arr[k] = L[i];
            i++;
        }
        else {
            arr[k] = R[j];
            j++;
        }
        k++;
    }

    while (i < n1) {
        arr[k] = L[i];
        i++;
        k++;
    }

    while (j < n2) {
        arr[k] = R[j];
        j++;
        k++;
    }
}

void mergeSort(int arr[], int l, int r) {
    if (l < r) {
        int m = l + (r - l) / 2;

        mergeSort(arr, l, m);
        mergeSort(arr, m + 1, r);

        merge(arr, l, m, r);
    }
}

int main() {
    int n;
    printf("Enter the number of elements: ");
    scanf("%d", &n);

    int arr[n];
    printf("Enter %d elements: ", n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    mergeSort(arr, 0, n - 1);

    printf("Sorted array: ");
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}

