    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    node->val = val;
    node->left = node->right = NULL;
    return node;
}

struct TreeNode* buildTree(int start, int end) {
    if (start > end) {
        return NULL;
    }
    struct TreeNode* root = newNode(start);
    if (start == end) {
        return root;
    }
    root->left = buildTree(start + 1, end);
    root->right = buildTree(start + 2, end);
    return root;
}

void printPreorder(struct TreeNode* node) {
    if (node == NULL) {
        return;
    }
    printf("%d ", node->val);
    printPreorder(node->left);
    printPreorder(node->right);
}

int countTrees(int n) {
    if (n == 0) {
        return 1;
    }
    int count = 0;
    for (int i = 1; i <= n; i++) {
        count += countTrees(i - 1) * countTrees(n - i);
    }
    return count;
}

