void print_partitions(char* str, int start, int end) {
    if (start >= end) {
        return;
    }

    int i, j;
    for (i = start; i < end; i++) {
        for (j = i + 1; j <= end; j++) {
            if (strncmp(str + start, str + i, j - i) == 0 && (j-i) * 2 - 1 == end - start) {
                print_partitions(str, j, end);
                printf("%.*s %.*s\n", (int)(end - start + 1), str + start, (int)(end - start + 1), str + i);
                return;
            }
        }
    }
}

