    char** current = preorder;

    while (**current == '-') {
        current++;
        level++;
    }

    TreeNode* root = newNode((*current)[0] - '0');

    while (*++current[0] == '-') {
        level--;
        if (level == 0) {
            if (root->left == NULL) {
                root->left = newNode((*current)[0] - '0');
            } else {
                root->right = newNode((*current)[0] - '0');
