struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
};

int dfs(struct TreeNode *root, int target) {
    if (root == NULL) {
        return -1;
    }

    if (root->val == target) {
        return 1;
    }

    int left = dfs(root->left, target);
    if (left != -1) {
        root->left = NULL;
        return left + 1;
    }

    int right = dfs(root->right, target);
    if (right != -1) {
        root->right = NULL;
        return right + 1;
    }

    return -1;
}

int minTime(struct TreeNode* root, int target) {
    int result = dfs(root, target);
    return result == -1 ? -1 : result - 1;
}

