    struct Node *right;
    int height;
} Node;

Node *createNode(int val) {
    Node *node = (Node *)malloc(sizeof(Node));
    node->val = val;
    node->left = NULL;
    node->right = NULL;
    node->height = 1;
    return node;
}

int height(Node *node) {
    if (node == NULL) return 0;
    return node->height;
}

int balanceFactor(Node *node) {
    if (node == NULL) return 0;
    return height(node->left) - height(node->right);
}

Node *rightRotate(Node *y) {
    Node *x = y->left;
    Node *T2 = x->right;
    x->right = y;
    y->left = T2;
    y->height = max(height(y->left), height(y->right)) + 1;
    x->height = max(height(x->left), height(x->right)) + 1;
    return x;
}

Node *leftRotate(Node *x) {
    Node *y = x->right;
    Node *T2 = y->left;
    y->left = x;
    x->right = T2;
    x->height = max(height(x->left), height(x->right)) + 1;
    y->height = max(height(y->left), height(y->right)) + 1;
    return y;
}

Node *balanceTree(Node *node) {
    if (node == NULL) return NULL;
    if (balanceFactor(node) > 1) {
        if (balanceFactor(node->left) < 0) node->left = leftRotate(node->left);
        return rightRotate(node);
    } else if (balanceFactor(node) < -1) {
        if (balanceFactor(node->right) > 0) node->right = rightRotate(node->right);
        return leftRotate(node);
    }
    return node;
}

Node *insertNode(Node *node, int val) {
    if (node == NULL) return createNode(val);
    if (val < node->val) node->left = insertNode(node->left, val);
    else node->right = insertNode(node->right, val);
    node->height = 1 + max(height(node->left), height(node->right));
    return balanceTree(node);
}

void findNodes(Node *node, int target, int k) {
    if (node == NULL) return;
    if (k == 0) {
        printf("%d ", node->val);
        return;
    }
    if (abs(height(node->left) - height(node->right)) <= k) {
        findNodes(node->left, target, k);
        findNodes(node->right, target, k);
    } else if (height(node->left) <= height(node->right)) {
        findNodes(node->right, target, k);
    } else {
        findNodes(node->left, target, k);
    }
}

