void connect(struct Node *root) {
    if (root == NULL)
        return;

    struct Node *nextLevel = root->left;
    struct Node *prev = root;

    while (root != NULL) {
        if (root->left != NULL) {
            root->left->next = root->right;
        }

        if (root->right != NULL) {
            root->right->next = root->next ? root->next->left : NULL;
        }

        root = root->next;
    }

    connect(nextLevel);
}

struct Node *buildTree(int pre[], int in[], int start, int end) {
    if (start > end)
        return NULL;

    struct Node *node = newNode(pre[0]);

    int i;
    for (i = 0; i <= end; i++) {
        if (in[i] == pre[0])
            break;
    }

    node->left = buildTree(pre, in, start + 1, i);
    node->right = buildTree(pre + 1 + i, in + 1 + i, start + i + 1, end - 1);

    return node;
}

