void findDuplicateSubtrees(TreeNode* root, SubTree** rootSet, int* count) {
    if (root == NULL) {
        return;
    }
    findDuplicateSubtreesHelper(root, rootSet, count);
    findDuplicateSubtrees(root->left, rootSet, count);
    findDuplicateSubtrees(root->right, rootSet, count);
}

void findDuplicateSubtreesHelper(TreeNode* root, SubTree** rootSet, int* count) {
    if (root == NULL) {
        return;
    }
    SubTree* subTree = NULL;
    for (int i = 0; i < *count; i++) {
        if (rootSet[i]->val == root->val) {
            subTree = rootSet[i];
            break;
        }
    }
    if (subTree == NULL) {
        subTree = newSubTree(root->val);
        rootSet[*count] = subTree;
        (*count)++;
    }
    addSubTree(&subTree, root->val);
}

