int isComplete(Node* root, int i, int n) {
    if (i >= n) {
        return 1;
    }

    if (root->left && root->right) {
        return isComplete(root->left, 2 * i + 1, n) &&
               isComplete(root->right, 2 * i + 2, n);
    } else if (root->left) {
        return isComplete(root->left, 2 * i + 1, n);
    } else if (root->right) {
        return isComplete(root->right, 2 * i + 2, n);
    }

    return 1;
}

