int setDepth(struct Node* node, int depth, int* maxDepth, int* res) {
    if (node == NULL) {
        return depth - 1;
    }
    if (*maxDepth < depth) {
    }
    int leftDepth = setDepth(node->left, depth + 1, maxDepth, res);
    int rightDepth = setDepth(node->right, depth + 1, maxDepth, res);
    return (leftDepth > rightDepth) ? leftDepth : rightDepth;
}

struct Node* deepestNode(struct Node* root, int target, int* res) {
    if (root == NULL) {
        return NULL;
    }
    if (root->data == target) {
        return root;
    }
    struct Node* left = deepestNode(root->left, target, res);
    struct Node* right = deepestNode(root->right, target, res);
    if (left != NULL) {
        return left;
    }
    if (right != NULL) {
        return right;
    }
    return NULL;
}

struct Node* construct(int pre[], int *preIndex, int low, int high, int size) {
    if (*preIndex >= size || pre[*preIndex] < low || pre[*preIndex] > high) {
        return NULL;
    }
    struct Node* node = newNode(pre[(*preIndex)++]);
    if (low < node->data && node->data <= high) {
        node->left = construct(pre, preIndex, low, node->data, size);
    }
    if (high > node->data && node->data >= low) {
        node->right = construct(pre, preIndex, node->data, high, size);
    }
    return node;
}

