struct Node* findPredecessor(struct Node* root, int target) {
    struct Node* temp = root;
    while (temp) {
        if (target < temp->data) {
            if (temp->left) {
                return temp->left;
            }
        } else if (target > temp->data) {
            if (temp->right) {
                return temp;
            }
        } else {
            if (temp->left) {
                temp = temp->left;
                while (temp->right) {
                    temp = temp->right;
                }
                return temp;
            }
            return NULL;
        }
        temp = temp->right;
    }
    return NULL;
}

