int houseRobber(int N, int arr[]) {
    if (N == 1)
        return arr[0];
    if (N == 2)
        return max(arr[0], arr[1]);

    int *dp = (int*)malloc(N * sizeof(int));
    dp[0] = arr[0];
    dp[1] = max(arr[0], arr[1]);

    for (int i = 2; i < N; i++)
        dp[i] = max(dp[i - 1], dp[i - 2] + arr[i]);

    int result = dp[N - 1];
    free(dp);

    dp = (int*)malloc(N * sizeof(int));
    dp[0] = 0;
    dp[1] = arr[1];

    for (int i = 2; i < N; i++)
        dp[i] = max(dp[i - 1], dp[i - 2] + arr[i]);

    result = max(result, dp[N - 1]);
    free(dp);

    return result;
}

