    if (dp[i] != -1)
        return dp[i];
    int left = (i > 0 && arr[i] - arr[i-1] == 1) ? 1 + findLongestConsecutivePath(arr, N, dp, i - 1) : 0;
    int right = (i < N - 1 && arr[i] - arr[i+1] == 1) ? 1 + findLongestConsecutivePath(arr, N, dp, i + 1) : 0;
    dp[i] = max(left, right);
    return dp[i];
}

