    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    node->val = val;
    node->left = node->right = NULL;
    return node;
}

TreeNode* constructTree(int inOrder[], int startIn, int endIn, int postOrder[], int startPost, int endPost) {
    if (startIn > endIn) {
        return NULL;
    }

    TreeNode* node = newNode(postOrder[endPost]);
    int rootIndex = -1;
    for (int i = startIn; i <= endIn; i++) {
        if (inOrder[i] == node->val) {
            rootIndex = i;
            break;
        }
    }

    node->left = constructTree(inOrder, startIn, rootIndex - 1, postOrder, startPost, startPost + rootIndex - startIn - 1);
    node->right = constructTree(inOrder, rootIndex + 1, endIn, postOrder, startPost + rootIndex - startIn, endPost - 1);

    return node;
}

void prune(TreeNode* root) {
    if (root == NULL || (root->left == NULL && root->right == NULL)) {
        free(root);
        return;
    }

    if (root->left && root->right) {
        prune(root->left);
        prune(root->right);
    } else {
        if (!root->left) {
            TreeNode* temp = root->right;
            free(root);
            prune(temp);
        } else {
            TreeNode* temp = root->left;
            free(root);
            prune(temp);
        }
    }
}

