    int sum = node->data;
    if (node->left)
        sum += node->left->data;
    if (node->right)
        sum += node->right->data;

    if (node->left && node->right)
        sum += node->right->data + node->left->data;

    return (sum == node->data && isSumProperty(node->left) && isSumProperty(node->right));
}

void fixValue(struct Node* node, int& total) {
    if (node == NULL)
        return;

    fixValue(node->left, total);
    fixValue(node->right, total);

    if (node->left || node->right) {
        int childSum = (node->left ? node->left->data : 0) + (node->right ? node->right->data : 0);
        total += abs(childSum - node->data);
        node->data = childSum;
    }
}

