thread_node* build_threaded_tree(int num_nodes, int* pre_order, int* in_order, int start_index, int end_index) {
    if (start_index > end_index) {
        return NULL;
    }

    thread_node* root = new_thread_node(pre_order[start_index], 1);

    int index;
    for (index = start_index; index <= end_index; index++) {
        if (in_order[index] == pre_order[start_index]) {
            break;
        }
    }

    int left_subtree_size = index - start_index;
    root->left = build_threaded_tree(pre_order, in_order, start_index + 1, start_index + left_subtree_size);
    root->right = build_threaded_tree(pre_order, in_order, start_index + left_subtree_size + 1, end_index);

    return root;
}

int verify_threaded_tree(thread_node* root) {
    if (root == NULL) {
        return 1;
    }

    if (root->color == 1) {
        if (root->left != NULL || root->right != NULL) {
            return 0;
        }
    } else {
        if (root->left == NULL || root->right == NULL) {
            return 0;
        }
    }

    if ((root->left != NULL && root->left->color == 1) || (root->right != NULL && root->right->color == 1)) {
        return 0;
    }

    return verify_threaded_tree(root->left) && verify_threaded_tree(root->right);
}

