struct Node* constructTreeUtil(int pre[], int *preIndex, int low, int high, int size) {
    if (*preIndex >= size || low > high) {
        return NULL;
    }

    struct Node* node = newNode(pre[*preIndex]);

    ++(*preIndex);

    if (low == high) {
        return node;
    }

    int i;
    for (i = low; i <= high; ++i) {
        if (pre[*preIndex] > pre[i]) {
            break;
        }
    }

    node->left = constructTreeUtil(pre, preIndex, low, i - 1, size);
    node->right = constructTreeUtil(pre, preIndex, i + 1, high, size);

    return node;
}

struct Node* constructTree(int pre[], int size) {
    int preIndex = 0;
    return constructTreeUtil(pre, &preIndex, 0, size - 1, size);
}

