int countNodes(Node* node, int level, int* count) {
    if (node == NULL)
        return 0;

    if (*count >= MAX_HEAP_SIZE)
        return 0;

    if (*count == level)
        (*count)++;

    return 1 + countNodes(node->left, level, count) + countNodes(node->right, level, count);
}

int median(Node* root, int level, int* count) {
    if (root == NULL)
        return 0;

    int leftCount = 0, rightCount = 0;

    if (height(root->left) == level)
        leftCount = countNodes(root->left, level, count);
    else if (height(root->right) == level)
        rightCount = countNodes(root->right, level, count);

    if (leftCount > rightCount)
        return median(root->left, level + 1, count);
    else if (leftCount < rightCount)
        return median(root->right, level + 1, count);
    else
        return root->value;
}

Node* buildTree(int value, int* index, char ch) {
    if (ch == '-') {
        return NULL;
    }

    Node* node = newNode(value);

    if (ch == 'L') {
        node->left = buildTree(*index, index, getchar());
        (*index)++;
    }

    if (ch == 'R') {
        node->right = buildTree(*index, index, getchar());
        (*index)++;
    }

    return node;
}

void freeNode(Node* node) {
    if (node == NULL)
        return;

    freeNode(node->left);
    freeNode(node->right);
    free(node);
