    node->left = node->right = NULL;
    return node;
}

TreeNode* buildTree(int* inorder, int* postorder, int start, int end, int* index) {
    if (start > end) {
        return NULL;
    }

    TreeNode* node = newNode(postorder[*index]);

    (*index)--;

    if (start == end) {
        return node;
    }

    int k;
    for (k = start; k <= end; k++) {
        if (inorder[k] == node->val) {
            break;
        }
    }

    node->right = buildTree(inorder, postorder, k + 1, end, index);
    node->left = buildTree(inorder, postorder, start, k - 1, index);

    return node;
}

int isValidBST(int* inorder, int* postorder, int N) {
    int index = N - 1;
    TreeNode* root = buildTree(inorder, postorder, 0, N - 1, &index);

    if (root->left) {
        if (root->left->val > root->val || root->right->val > root->left->val) {
            return 0;
        }
    } else if (root->right) {
        if (root->right->val > root->val) {
            return 0;
        }
    }

    return 1;
}

