    if (node->right != NULL)
        return minValueNode(node->right);

    struct node* successor = NULL;

    struct node* current = root;
    while (current != NULL) {
        if (node->val < current->val) {
            successor = current;
            current = current->left;
        }
        else if (node->val > current->val)
            current = current->right;
        else
            break;
    }
    return successor;
}

