struct Node* constructBSTFromPreorder(int pre[], int *preIndex, int low, int high, int size) {
    if (*preIndex >= size || pre[*preIndex] < low || pre[*preIndex] > high) {
        return NULL;
    }

    struct Node* root = newNode(pre[(*preIndex)++]);

    if (low < root->data && root->data <= high) {
        root->left = constructBSTFromPreorder(pre, preIndex, low, root->data-1, size);
    }

    if (high > root->data && root->data >= low) {
        root->right = constructBSTFromPreorder(pre, preIndex, root->data+1, high, size);
    }

    return root;
}

