struct TreeNode* recoverFromPreorder(int*& traversal, int n) {
    int i = 0;
    struct TreeNode *root = NULL;

    while (i < n) {
        if (traversal[i] != -1) {
            struct TreeNode **node = &root;
            while (*node != NULL && i < n) {
                if (traversal[i] == -2) {
                    node = &((*node)->left);
                } else {
                    node = &((*node)->right);
                }
                i++;
            }
        }
        i++;
    }

    int swapped = 0;
    struct TreeNode *firstNode = NULL, *secondNode = NULL;
    recoverTree(root, &firstNode, &secondNode, &swapped);

    if (swapped == 0 && firstNode && secondNode) {
        firstNode->left = secondNode->left;
        firstNode->right = secondNode->right;
        secondNode->left = secondNode->right = NULL;
    }

    return root;
}

