int maxWidth(Node* root) {
    if(root == NULL) {
        return 0;
    }

    int maxWidth = 0;
    int height = 0;

    while(root) {
        height++;
        root = root->left;
    }

    for(int i = 0; i < height; i++) {
        int count = 0;

        for(int j = 0; j < pow(2, i); j++) {
            Node* temp = root;

            for(int k = 0; k < pow(2, i) - 1 - j; k++) {
                temp = temp->left;
            }

            count++;
            root = temp->right;
        }

        maxWidth = fmax(maxWidth, count);
    }

    return maxWidth;
}

