        return largestBSTSubtree(root->left) + largestBSTSubtree(root->right) + 1;
    } else if (largestBSTSubtree(root->left) != -1) {
        return largestBSTSubtree(root->left);
    } else if (largestBSTSubtree(root->right) != -1) {
        return largestBSTSubtree(root->right);
    }
    return -1;
}

