int calculate_cost(int n, search_cost cost[], int i, int sum) {
    if (i >= n) {
        return 0;
    }

    int curr_cost = (sum - cost[i].cost * cost[i].frequency);

    return curr_cost + calculate_cost(n, cost, i + 1, sum);
}

node* build_tree(int key[], int frequency[], int start, int end, search_cost cost[]) {
    if (start > end) {
        return NULL;
    }

    int min_cost = INT_MAX;
    int min_index = -1;
    for (int i = start; i <= end; i++) {
        if (cost[i].cost < min_cost) {
            min_cost = cost[i].cost;
            min_index = i;
        }
    }

    node* new_node = (node*)malloc(sizeof(node));
    new_node->key = key[min_index];
    new_node->frequency = frequency[min_index];
    new_node->left = build_tree(key, frequency, start, min_index - 1, cost);
    new_node->right = build_tree(key, frequency, min_index + 1, end, cost);

    return new_node;
}

