    while (cur) {
        if (!isLeafC(cur)) res[idx++] = cur->val;
        cur = cur->left ? cur->left : cur->right;
    }

    addLeavesC(root, res, &idx);

    int st[10005], top = 0;
    cur = root->right;
    while (cur) {
        if (!isLeafC(cur)) st[top++] = cur->val;
        cur = cur->right ? cur->right : cur->left;
    }
    while (top > 0) res[idx++] = st[--top];

    *returnSize = idx;
    return res;
}

