    struct TreeNode *xParent = NULL, *yParent = NULL;
    int xDepth = -1, yDepth = -1;
    dfsCousins(root, NULL, 0, x, y, &xParent, &yParent, &xDepth, &yDepth);
    return xDepth == yDepth && xParent != yParent;
}

