int lca(int *arr, int n, int p, int q) {
    int i = 0;
    while(i < n) {
        if(arr[i] > p && arr[i] > q) i = 2*i+1;
        else if(arr[i] < p && arr[i] < q) i = 2*i+2;
        else return arr[i];
    }
    return -1;
}

