int consec(int *arr, int i, int n) {
    if(i >= n || arr[i] == -1) return 0;
    int l = 0, r = 0;
    if(2*i+1 < n && arr[2*i+1] != -1 && arr[2*i+1] == arr[i] + 1) l = 1 + consec(arr, 2*i+1, n);
    if(2*i+2 < n && arr[2*i+2] != -1 && arr[2*i+2] == arr[i] + 1) r = 1 + consec(arr, 2*i+2, n);
    return l > r ? l : r;
}

