int univalue(int *arr, int i, int n) {
    if(i >= n || arr[i] == -1) return 0;
    int l = univalue(arr, 2*i+1, n);
    int r = univalue(arr, 2*i+2, n);
    int res = 0;
    if(2*i+1 < n && arr[2*i+1] == arr[i]) res += l + 1;
    if(2*i+2 < n && arr[2*i+2] == arr[i]) res += r + 1;
    return res;
}

