struct Node { int val; struct Node *left, *right; };
struct Node* newNode(int val) { struct Node* n = malloc(sizeof(struct Node)); n->val=val; n->left=n->right=NULL; return n; }
struct Node* insert(struct Node* root, int val) {
    if(!root) return newNode(val);
    if(val < root->val) root->left = insert(root->left, val);
    else root->right = insert(root->right, val);
    return root;
}
int idx = 0;
void inorderToArr(struct Node* root, int* arr) {
    if(!root) return;
    inorderToArr(root->left, arr);
    arr[idx++] = root->val;
    inorderToArr(root->right, arr);
}
void arrToMinHeap(struct Node* root, int* arr, int n) {
    if(!root) return;
    root->val = arr[idx++];
    arrToMinHeap(root->left, arr, n);
    arrToMinHeap(root->right, arr, n);
}
void levelOrder(struct Node* root) {
    if(!root) return;
    struct Node* q[10000]; int f=0, r=0;
    q[r++] = root;
    while(f<r) {
        struct Node* curr = q[f++];
        printf("%d ", curr->val);
        if(curr->left) q[r++] = curr->left;
        if(curr->right) q[r++] = curr->right;
    }
    printf("\n");
}
int main() {
    int n; scanf("%d", &n);
    struct Node* root = NULL;
    for(int i=0; i<n; i++) { int v; scanf("%d", &v); root = insert(root, v); }
    int arr[n]; idx=0;
    inorderToArr(root, arr);
    // Sort array for min-heap property (already sorted from inorder)
    idx=0;
    arrToMinHeap(root, arr, n);
    levelOrder(root);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
int isValidPreorder(int* pre, int n) {
    int stack[10000], top=-1;
    int root = INT_MIN;
    for(int i=0; i<n; i++) {
        if(pre[i] < root) return 0;
        while(top >= 0 && stack[top] < pre[i]) { root = stack[top--]; }
        stack[++top] = pre[i];
    }
    return 1;
}
int main() {
    int n; scanf("%d", &n);
    int pre[n];
    for(int i=0; i<n; i++) scanf("%d", &pre[i]);
    printf("%s\n", isValidPreorder(pre, n) ? "YES" : "NO");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
int isValidPostorder(int* post, int n) {
    int stack[10000], top=-1;
    int root = INT_MAX;
    for(int i=n-1; i>=0; i--) {
        if(post[i] > root) return 0;
        while(top >= 0 && stack[top] > post[i]) { root = stack[top--]; }
        stack[++top] = post[i];
    }
    return 1;
}
int main() {
    int n; scanf("%d", &n);
    int post[n];
    for(int i=0; i<n; i++) scanf("%d", &post[i]);
    printf("%s\n", isValidPostorder(post, n) ? "YES" : "NO");
    return 0;
}

