void merge(vector<int>&a,int lo,int mid,int hi){
    vector<int>tmp;int i=lo,j=mid+1;
    while(i<=mid&&j<=hi)tmp.push_back(a[i]<=a[j]?a[i++]:a[j++]);
    while(i<=mid)tmp.push_back(a[i++]);while(j<=hi)tmp.push_back(a[j++]);
    for(int k=lo;k<=hi;++k)a[k]=tmp[k-lo];
}
void msort(vector<int>&a,int lo,int hi){
    if(lo>=hi)return;int mid=(lo+hi)/2;msort(a,lo,mid);msort(a,mid+1,hi);merge(a,lo,mid,hi);
}
