#include <bits/stdc++.h>
using namespace std;
using ll = long long;
struct Node{ll v; int l=-1,r=-1;};
struct Tree{vector<Node> a; int root=-1;};
Tree readTree(bool hasValues){
    int n; if(!(cin>>n)) return {};
    Tree t; t.a.resize(max(0,n));
    if(n==0) return t;
    if(hasValues){ for(int i=0;i<n;i++) cin>>t.a[i].v; for(int i=0;i<n;i++) cin>>t.a[i].l>>t.a[i].r; }
    else { for(int i=0;i<n;i++) cin>>t.a[i].v>>t.a[i].l>>t.a[i].r; }
    vector<int> indeg(n); for(auto &x:t.a){ if(x.l>=0&&x.l<n) indeg[x.l]++; if(x.r>=0&&x.r<n) indeg[x.r]++; }
    t.root=0; for(int i=0;i<n;i++) if(indeg[i]==0){t.root=i;break;}
    return t;
}
void printTree(const Tree&t){
    cout<<t.a.size()<<'\n';
    for(auto &x:t.a) cout<<x.v<<' '<<x.l<<' '<<x.r<<'\n';
}
vector<int> bfs(const Tree&t){vector<int> o;if(t.root<0)return o;queue<int>q;q.push(t.root);while(!q.empty()){int u=q.front();q.pop();o.push_back(u);if(t.a[u].l>=0)q.push(t.a[u].l);if(t.a[u].r>=0)q.push(t.a[u].r);}return o;}
vector<int> inorder(const Tree&t){vector<int>o,st;if(t.root<0)return o;int u=t.root;while(u>=0||!st.empty()){while(u>=0){st.push_back(u);u=t.a[u].l;}u=st.back();st.pop_back();o.push_back(u);u=t.a[u].r;}return o;}
vector<int> preorder(const Tree&t){vector<int>o;if(t.root<0)return o;vector<int>s{t.root};while(!s.empty()){int u=s.back();s.pop_back();o.push_back(u);if(t.a[u].r>=0)s.push_back(t.a[u].r);if(t.a[u].l>=0)s.push_back(t.a[u].l);}return o;}
vector<int> postorder(const Tree&t){vector<int>o;if(t.root<0)return o;vector<pair<int,int>>s{{t.root,0}};while(!s.empty()){auto &[u,k]=s.back();if(k==0){k=1;if(t.a[u].l>=0)s.push_back({t.a[u].l,0});}else if(k==1){k=2;if(t.a[u].r>=0)s.push_back({t.a[u].r,0});}else{o.push_back(u);s.pop_back();}}return o;}
int height(const Tree&t){if(t.root<0)return -1;queue<int>q;q.push(t.root);int h=-1;while(!q.empty()){int z=q.size();h++;while(z--){int u=q.front();q.pop();if(t.a[u].l>=0)q.push(t.a[u].l);if(t.a[u].r>=0)q.push(t.a[u].r);}}return h;}

int main(){Tree t=readTree(false);if(t.root<0){cout<<0;return 0;}auto o=inorder(t);vector<int>bad;for(int i=1;i<(int)o.size();i++)if(t.a[o[i-1]].v>t.a[o[i]].v){{bad.push_back(i-1);bad.push_back(i);}}if(bad.size()>=2)swap(t.a[o[bad[0]]].v,t.a[o[bad[-1]]].v);printTree(t);
}

