#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

void generateCombinations(int n, int k, vector<int> &current, vector<vector<int>> &result) {
    if (current.size() == k) {
        result.push_back(current);
        return;
    }

    for (int i = n; i >= 1; i--) {
        current.push_back(i);
        generateCombinations(i - 1, k, current, result);
        current.pop_back();
    }
}

int main() {
    int n, k;
    cout << "Enter N and K: ";
    cin >> n >> k;

    vector<vector<int>> result;
    vector<int> current;
    generateCombinations(n, k, current, result);

    for (const auto &comb : result) {
        for (int num : comb) {
            cout << num << ' ';
        }
        cout << '\n';
    }

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

bool isPalindrome(string s, int start, int end) {
    while (start < end) {
        if (s[start] != s[end])
            return false;
        start++;
        end--;
    }
    return true;
}

void partition(string s, int start, vector<string>& partitions, string partition) {
    if (start >= s.size()) {
        partitions.push_back(partition);
        return;
    }

    for (int end = start; end < s.size(); end++) {
        if (isPalindrome(s, start, end)) {
            string part = s.substr(start, end - start + 1);
            partition += part;
            partition(s, end + 1, partitions, partition);
            partition.pop_back();
        }
    }
}

int main() {
    string s;
    cout << "Enter a string: ";
    cin >> s;

    vector<string> partitions;
    partition(s, 0, partitions, "");

    cout << "All palindrome partitions: ";
    for (string partition : partitions) {
        cout << partition << " ";
    }
    cout << endl;

    return 0;
}

#include <iostream>
using namespace std;

void merge(int arr[], int l, int m, int r) {
    int i, j, k;
    int n1 = m - l + 1;
    int n2 = r - m;

    int L[n1], R[n2];

    for (i = 0; i < n1; i++)
        L[i] = arr[l + i];
    for (j = 0; j < n2; j++)
        R[j] = arr[m + 1 + j];

    i = 0;
    j = 0;
    k = l;
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) {
            arr[k] = L[i];
            i++;
        }
        else {
            arr[k] = R[j];
            j++;
        }
        k++;
    }

    while (i < n1) {
        arr[k] = L[i];
        i++;
        k++;
    }

    while (j < n2) {
        arr[k] = R[j];
        j++;
        k++;
    }
}

void mergeSort(int arr[], int l, int r) {
    if (l < r) {
        int m = l + (r - l) / 2;

        mergeSort(arr, l, m);
        mergeSort(arr, m + 1, r);

        merge(arr, l, m, r);
    }
}

