    for (int i = 0; i < n; i++) {
        int data;
        cin >> data;
        nodes.push_back(data);
    }

    Node *root = buildTree(nodes);
    printLevelOrder(root);

    if (isSymmetric(root, root))
        cout << "YES\n";
    else
        cout << "NO\n";

    return 0;
}

