    Node(int data) : data(data), left(NULL), right(NULL) {}
};

void topView(Node *root) {
    if (root == NULL)
        return;

    map<int, Node *> nodes;
    queue<pair<Node*, int>> q;

    q.push({root, 0});

    while (!q.empty()) {
        pair<Node*, int> p = q.front();
        q.pop();

        Node *node = p.first;
        int hd = p.second;

        if (nodes.find(hd) == nodes.end()) {
            nodes[hd] = node;
        } else {
            nodes[hd]->left = node;
            return;
        }

        if (node->left)
            q.push({node->left, hd - 1});
        if (node->right)
            q.push({node->right, hd + 1});
    }
}

