    TreeNode* root = createTree(nodes, 0, n);
    recoverTree(root);

    std::cout << "Inorder traversal: ";
    TreeNode* temp = first;
    while (temp != nullptr) {
        std::cout << temp->val << " ";
        if (temp->right) {
            temp = temp->right;
        } else {
            temp = temp->left;
        }
    }
    std::cout << std::endl;

    return 0;
}

