    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

class Solution {
public:
    TreeNode* flatten(TreeNode* root) {
        if (root == NULL) return NULL;
        TreeNode* left = flatten(root->left);
        TreeNode* right = flatten(root->right);
        root->left = NULL;
        root->right = left;
        TreeNode* curr = root;
        while (curr->right != NULL) {
            curr = curr->right;
        }
        curr->right = right;
        return root;
    }
};

