struct Node {
    int data;
    Node* left;
    Node* right;
};

Node* createNode(int data) {
    Node* newNode = new Node();
    if (!newNode) {
        cout << "Memory error\n";
        return NULL;
    }
    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

string serialize(Node* node, unordered_map<string, int>& m) {
    if (!node) {
        return "#";
    }
    string s = "(" + to_string(node->data) + ")";
    s += serialize(node->left, m) + serialize(node->right, m);
    return s;
}

int countNodes(Node* node, unordered_map<string, int>& m) {
    if (!node) {
        return 0;
    }
    string s = serialize(node, m);
    m[s]++;
    return m[s];
}

void detectDuplicates(Node* root) {
    unordered_map<string, int> m;
    int maxCount = 0;
    for (int i = 1; i <= 2; i++) {
        int count = countNodes(root, m);
        if (count > maxCount) {
            maxCount = count;
        }
    }
    if (maxCount < 2) {
        cout << "None\n";
        return;
    }
    for (auto& pair : m) {
        if (pair.second > 1) {
            cout << pair.first << "\n";
        }
    }
}

