bool isBalanced(Node* root) {
    if (root == nullptr) {
        return true;
    }

    int heightDiff = height(root->left) - height(root->right);

    if (abs(heightDiff) > 1 || !isBalanced(root->left) || !isBalanced(root->right)) {
        return false;
    }

    return true;
}

int height(Node* root) {
