        if (node->left != NULL) {
            if (isLeaf) {
                return false;
            }
            q.push(node->left);
        } else {
            isLeaf = true;
        }

        if (node->right != NULL) {
            if (isLeaf) {
                return false;
            }
            q.push(node->right);
        } else {
            isLeaf = false;
        }
    }

    return true;
