    for (int i = 0; i < N; i++) {
        cin >> inOrder[i];
    }

    Node* root = buildTree(preOrder, inOrder, 0, N - 1, 0, N - 1);
    if (isPerfect(root)) {
        cout << "YES\n";
    } else {
        cout << "NO\n";
    }

    return 0;
}

