        if (children[i] == -1) {
            tree[i] = nullptr;
        } else {
            tree[i] = new Node();
            tree[i]->data = i + 1;
            tree[i]->left = nullptr;
            tree[i]->right = nullptr;
            if (tree[children[i]] != nullptr) {
                tree[i]->parent = tree[children[i]];
