int findLevel(Node* root) {
    if (!root) {
        return 0;
    }
    queue<pair<Node*, int>> q;
    q.push({root, 1});
    int curLevel = 0;
    int maxSum = INT_MIN;
    while (!q.empty()) {
        int size = q.size();
        int levelSum = 0;
        while (size--) {
            Node* node = q.front().first;
            int level = q.front().second;
            q.pop();
            levelSum += node->val;
            if (node->left) {
                q.push({node->left, level + 1});
            }
            if (node->right) {
                q.push({node->right, level + 1});
            }
        }
        if (levelSum > maxSum) {
            maxSum = levelSum;
            curLevel = q.front().second;
        }
    }
    return curLevel;
}

