    if (preorder.empty()) {
        return nullptr;
    }

    TreeNode* root = newTreeNode(preorder[0]);
    queue<TreeNode*> q;
    q.push(root);

    for (size_t i = 1, j = 0; i < preorder.size(); ++i) {
        while (!q.empty() && q.front()->val == inorder[j]) {
            TreeNode* node = newTreeNode(preorder[i]);
            q.front()->left = node;
            q.push(node);
            ++j;
            i++;
        }
        if (!q.empty() && q.front()->val == inorder[j]) {
            TreeNode* node = newTreeNode(preorder[i]);
            q.front()->right = node;
            q.push(node);
            ++j;
            i++;
        }
        if (q.front()->left) {
            q.pop();
        }
    }
    return root;
}

