        if (nodes.empty()) {
            return;
        }

        queue<TreeNode*> q;
        TreeNode* root = new TreeNode(nodes[0]);
        q.push(root);

        for (int i = 1; i < nodes.size(); i += 2) {
            TreeNode* node = q.front();
            q.pop();

            if (nodes[i] != -1) {
                node->left = new TreeNode(nodes[i]);
                q.push(node->left);
            }

            if (i + 1 < nodes.size()) {
                node->right = new TreeNode(nodes[i + 1]);
                q.push(node->right);
            }
        }

        solve(root);
    }
};

