bool isValid(vector<int> &preorder, int start, int end) {
    if (start >= end) {
        return true;
    }

    int root = preorder[start];
    int i = start + 1;

    while (i <= end && preorder[i] < root) {
        i++;
    }

    while (i <= end && preorder[i] > root) {
        if (preorder[i] < root) {
            return false;
        }
        i++;
    }

    return isValid(preorder, start + 1, i - 1) && isValid(preorder, i, end);
}

