bool isValidPostorder(vector<int> &sequence) {
    stack<int> s;
    int root = INT_MAX;

    for (int i = sequence.size() - 1; i >= 0; --i) {
        if (sequence[i] > root) {
            return false;
        }

        while (!s.empty() && sequence[i] > s.top()) {
            root = s.top();
            s.pop();
        }

        s.push(sequence[i]);
    }

    return true;
}

