int numTrees(int n, int duplicateInsertionRule) {
    vector<int> nums(n, 0);
    for (int i = 0; i < n; i++) {
        nums[i] = i + 1;
    }

    if (duplicateInsertionRule == 1) {
        nums.erase(unique(nums.begin(), nums.end()), nums.end());
        return solve(nums, 0, nums.size() - 1);
    } else if (duplicateInsertionRule == 2) {
        return solve(nums, 0, nums.size() - 1);
    } else {
        nums.erase(unique(nums.begin(), nums.end()), nums.end());
        return solve(nums, 0, nums.size() - 1);
    }
