int validSeq(Node* root, int arr[], int n) {
    if(root == NULL)
        return 1;

    int index = 0;
    while(root != NULL) {
        if(index == 0 || arr[index - 1] > root->data) {
            if(index == 0 || arr[index - 1] < root->data)
                return 0;
        } else {
            return 0;
        }
        index++;
        root = root->right;
    }

    root = (Node*)1;
