                unsigned long long curIdx = idx - minIdx;
                if (i == 0) first = curIdx;
                if (i == size - 1) last = curIdx;

                if (node->left) q.push({node->left, 2 * curIdx});
                if (node->right) q.push({node->right, 2 * curIdx + 1});
            }
            maxWidth = std::max(maxWidth, last - first + 1);
        }
        return maxWidth;
    }
};

