        int mid = postMap[nextVal];
        root->left = build(preorder, postStart, mid);
        root->right = build(preorder, mid + 1, postEnd - 1);
        return root;
    }
public:
    TreeNode* constructFromPrePost(std::vector<int>& preorder, std::vector<int>& postorder) {
        preIdx = 0;
        postMap.clear();
