class Solution {
    bool isLeaf(TreeNode* node) {
        return node && !node->left && !node->right;
    }

    void addLeavesRev(TreeNode* node, std::vector<int>& res) {
        if (isLeaf(node)) {
            res.push_back(node->val);
            return;
        }
        if (node->right) addLeavesRev(node->right, res);
        if (node->left) addLeavesRev(node->left, res);
    }
public:
    std::vector<int> boundaryOfBinaryTreeClockwise(TreeNode* root) {
        std::vector<int> res;
        if (!root) return res;

        if (!isLeaf(root)) res.push_back(root->val);

        TreeNode* cur = root->right;
        while (cur) {
            if (!isLeaf(cur)) res.push_back(cur->val);
            cur = cur->right ? cur->right : cur->left;
        }

        addLeavesRev(root, res);

        std::stack<int> st;
        cur = root->left;
        while (cur) {
            if (!isLeaf(cur)) st.push(cur->val);
            cur = cur->left ? cur->left : cur->right;
        }
        while (!st.empty()) {
            res.push_back(st.top());
            st.pop();
        }

        return res;
    }
};

