        int n = keys.size();
        std::vector<std::vector<int>> cost(n, std::vector<int>(n, 0));
        std::vector<std::vector<int>> rootIdx(n, std::vector<int>(n, 0));
        std::vector<std::vector<int>> w(n, std::vector<int>(n, 0));

