int countNodes(TreeNode* root) {
    if (!root) return 0;
    
    TreeNode* left = root;
    TreeNode* right = root;
    int hl = 0, hr = 0;
    
    while (left) {
        hl++;
        left = left->left;
    }
    while (right) {
        hr++;
        right = right->right;
    }
    
