            level.push_back(node->val);
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
        
        int left = 0, right = level.size() - 1;
        while (left < right) {
            if (level[left] != level[right]) return false;
            left++;
            right--;
        }
    }
    return true;
}

