void recoverBST(TreeNode* root, TreeNode*& prev, TreeNode*& first, TreeNode*& second) {
    if (!root) return;
    
    recoverBST(root->left, prev, first, second);
    
    if (prev && root->val < prev->val) {
        if (!first) first = prev;
        second = root;
    }
    prev = root;
    
    recoverBST(root->right, prev, first, second);
}

