        }
        System.out.println();
    }
    static void outLongArr(long[] a) {
        for(int i=0;i<a.length;i++){
            if(i>0) System.out.print(" ");
            System.out.print(a[i]);
        }
        System.out.println();
    }

    static void ms(int[]a,int l,int r,int[]t){
        if(l>=r)return;
        int m=(l+r)>>>1;
        ms(a,l,m,t);
        ms(a,m+1,r,t);
        int i=l,j=m+1,k=l;
        while(i<=m&&j<=r)t[k++]=a[i]<=a[j]?a[i++]:a[j++];
        while(i<=m)t[k++]=a[i++];
        while(j<=r)t[k++]=a[j++];
        for(i=l;i<=r;i++)a[i]=t[i];
    }
    public static void main(String[] z)throws Exception{
        FS f=new FS();
        int n=f.nextInt();
        int[]a=new int[n],t=new int[n];
        for(int i=0;i<n;i++)a[i]=f.nextInt();
        ms(a,0,n-1,t);
        outArr(a);
    }
}

