j++;
}int p=s.peek();
if(a[p].l<0)a[p].l=i;
else a[p].r=i;
s.push(i);
}while(!s.isEmpty()&&j<n&&a[s.peek()].v==post[j]){s.pop();
j++;
}printTree(a);
}
}

