while(pos<s.length()&&s.charAt(pos)=='-'){d++;
pos++;
}int st=pos;
while(pos<s.length()&&s.charAt(pos)!='-')pos++;
if(d!=dep){pos=st-d;
return null;
}T x=new T(Long.parseLong(s.substring(st,pos)));
x.l=build(dep+1);
x.r=build(dep+1);
return x;
}static void pre(T x,List<Long>o){if(x==null)return;
o.add(x.v);
pre(x.l,o);
pre(x.r,o);
}public static void main(String[]z)throws Exception{FS f=new FS();
