}
 static boolean hasSubtree(N[]a,N[]b,int u,int v){if(u<0)return false;
if(eq(a,u,b,v))return true;
return hasSubtree(a,b,a[u].l,v)||hasSubtree(a,b,a[u].r,v);
}
 static boolean eq(N[]a,int u,N[]b,int v){if(u<0||v<0)return u==v;
if(a[u].v!=b[v].v)return false;
return eq(a,a[u].l,b,b[v].l)&&eq(a,a[u].r,b,b[v].r);
}
