 static void perfect(N[]a,int u,int[]best){if(u<0)return;
int[]l={0},r={0};
perfectH(a,a[u].l,l);
perfectH(a,a[u].r,r);
if(l[0]==r[0]&&l[0]>=0)best[0]=Math.max(best[0],(1<<(Math.min(l[0]+1,30)))-1);
perfect(a,a[u].l,best);
perfect(a,a[u].r,best);
}
 static int perfectH(N[]a,int u,int[]h){if(u<0){h[0]=0;
return 1;
}int[]l={0},r={0};
int A=perfectH(a,a[u].l,l),B=perfectH(a,a[u].r,r);
if(A==1&&B==1&&l[0]==r[0]){h[0]=l[0]+1;
return 1;
}h[0]=Math.max(l[0],r[0])+1;
return 0;
}
 static void complete(N[]a,int u,int[]best){if(u<0)return;
int s=comp(a,u);
best[0]=Math.max(best[0],s);
complete(a,a[u].l,best);
complete(a,a[u].r,best);
}
 static int comp(N[]a,int u){if(u<0)return 0;
int lh=0,rh=0,x=u;
while(x>=0){lh++;
x=a[x].l;
}x=a[u].r;
while(x>=0){rh++;
x=a[x].l;
}if(lh==rh)return (1<<Math.min(lh,30))-1;
return 1+comp(a,a[u].l)+comp(a,a[u].r);
}
 static N[]removeLeaves(N[]a){ArrayList<N>o=new ArrayList<>();
int[]map=new int[a.length];
Arrays.fill(map,-1);
for(int i=0;i<a.length;i++)if(!(a[i].l<0&&a[i].r<0)){map[i]=o.size();
o.add(new N(a[i].v));
}for(int i=0;i<a.length;i++)if(map[i]>=0){int L=a[i].l,R=a[i].r;
while(L>=0&&map[L]<0)L=a[L].l>=0?a[L].l:a[L].r;
while(R>=0&&map[R]<0)R=a[R].r>=0?a[R].r:a[R].l;
o.get(map[i]).l=L<0?-1:map[L];
o.get(map[i]).r=R<0?-1:map[R];
}return o.toArray(new N[0]);
}
