 static void boundLeft(N[]a,int u,List<Long>o){int c=a[u].l>=0?a[u].l:a[u].r;
if(c>=0){if(!(a[c].l<0&&a[c].r<0))o.add(a[c].v);
boundLeft(a,c,o);
