 static int[] depth(N[]a){int[]d=new int[a.length];
Arrays.fill(d,-1);
if(a.length==0)return d;
ArrayDeque<Integer>q=new ArrayDeque<>();
q.add(0);
d[0]=0;
while(!q.isEmpty()){int u=q.remove();
if(a[u].l>=0){d[a[u].l]=d[u]+1;
