 static int lca(N[]a,int u,int v){ArrayList<Integer>p=new ArrayList<>(),q=new ArrayList<>();
path(a,0,u,p);
path(a,0,v,q);
int z=-1;
for(int i=0;i<Math.min(p.size(),q.size())&&p.get(i).equals(q.get(i));
i++)z=p.get(i);
return z;
}
 static boolean path(N[]a,int u,int t,List<Integer>p){if(u<0)return false;
p.add(u);
if(u==t)return true;
if(path(a,a[u].l,t,p)||path(a,a[u].r,t,p))return true;
p.remove(p.size()-1);
return false;
}
