 static boolean iso(N[]a,int u,N[]b,int v){if(u<0||v<0)return u==v;
if(a[u].v!=b[v].v)return false;
return (iso(a,a[u].l,b,b[v].l)&&iso(a,a[u].r,b,b[v].r))||(iso(a,a[u].l,b,b[v].r)&&iso(a,a[u].r,b,b[v].l));
}
 static N[]merge(N[]a,int u,N[]b,int v){if(u<0&&v<0)return new N[0];
ArrayList<N>o=new ArrayList<>();
mergeNode(a,u,b,v,o);
return o.toArray(new N[0]);
}
 static int mergeNode(N[]a,int u,N[]b,int v,List<N>o){if(u<0&&v<0)return -1;
long x=(u>=0?a[u].v:0)+(v>=0?b[v].v:0);
int id=o.size();
o.add(new N(x));
int l=mergeNode(a,u>=0?a[u].l:-1,b,v>=0?b[v].l:-1,o),r=mergeNode(a,u>=0?a[u].r:-1,b,v>=0?b[v].r:-1,o);
o.get(id).l=l;
o.get(id).r=r;
return id;
}
 static N[]removeHalf(N[]a){if(a.length==0)return a;
return removeHalfRec(a,0).toArray(new N[0]);
}
 static List<N> removeHalfRec(N[]a,int root){ArrayList<N>o=new ArrayList<>();
Map<Integer,Integer>m=new HashMap<>();
rebuildHalf(a,root,o,m);
return o;
}
 static int rebuildHalf(N[]a,int u,List<N>o,Map<Integer,Integer>m){if(u<0)return -1;
while(u>=0&&((a[u].l<0)^(a[u].r<0))){u=a[u].l>=0?a[u].l:a[u].r;
}if(u<0)return -1;
int id=o.size();
o.add(new N(a[u].v));
m.put(u,id);
o.get(id).l=rebuildHalf(a,a[u].l,o,m);
o.get(id).r=rebuildHalf(a,a[u].r,o,m);
return id;
}
