Fast()throws Exception{b=System.in.readAllBytes();
}String next(){while(p<b.length&&b[p]<=32)p++;
if(p>=b.length)return null;
int s=p;
while(p<b.length&&b[p]>32)p++;
return new String(b,s,p-s);
}int ni(){return Integer.parseInt(next());
}long nl(){return Long.parseLong(next());
}}
 static N[] read(Fast f, boolean separate)throws Exception{int n=f.ni();
if(n==0)return new N[0];
N[]a=new N[n];
if(separate){for(int i=0;i<n;i++)a[i]=new N(f.nl());
for(int i=0;i<n;i++){a[i].l=f.ni();
a[i].r=f.ni();
}}else{for(int i=0;i<n;i++){a[i]=new N(f.nl());
a[i].l=f.ni();
a[i].r=f.ni();
}}return a;
}
 static void children(N[]a,int u,List<Integer> out){if(u<0)return;
if(a[u].l>=0)out.add(a[u].l);
if(a[u].r>=0)out.add(a[u].r);
}
 static void treeOut(N[]a){if(a.length==0){System.out.println(0);
return;
}int[]mp=new int[a.length];
Arrays.fill(mp,-1);
ArrayList<Integer>ord=new ArrayList<>();
ArrayDeque<Integer>st=new ArrayDeque<>();
st.push(0);
while(!st.isEmpty()){int u=st.pop();
if(u<0||mp[u]>=0)continue;
mp[u]=0;
ord.add(u);
if(a[u].r>=0)st.push(a[u].r);
if(a[u].l>=0)st.push(a[u].l);
}for(int i=0;i<ord.size();
i++)mp[ord.get(i)]=i;
StringBuilder s=new StringBuilder();
s.append(ord.size()).append('\n');
for(int u:ord){s.append(a[u].v).append(' ').append(a[u].l<0?-1:mp[a[u].l]).append(' ').append(a[u].r<0?-1:mp[a[u].r]).append('\n');
}System.out.print(s);
}
 static void vals(List<Long>v){for(int i=0;i<v.size();
i++){if(i>0)System.out.print(' ');
System.out.print(v.get(i));
}System.out.println();
}
 static void levels(N[]a, boolean leafOnly){if(a.length==0)return;
ArrayDeque<Integer>q=new ArrayDeque<>();
q.add(0);
while(!q.isEmpty()){int z=q.size();
for(int i=0;i<z;i++){int u=q.remove();
if(leafOnly&&!(a[u].l<0&&a[u].r<0)){} else { } if(a[u].l>=0)q.add(a[u].l);
if(a[u].r>=0)q.add(a[u].r);
}}}
 static int[] depth(N[]a){int[]d=new int[a.length];
Arrays.fill(d,-1);
if(a.length==0)return d;
ArrayDeque<Integer>q=new ArrayDeque<>();
q.add(0);
d[0]=0;
while(!q.isEmpty()){int u=q.remove();
if(a[u].l>=0){d[a[u].l]=d[u]+1;
q.add(a[u].l);
}if(a[u].r>=0){d[a[u].r]=d[u]+1;
q.add(a[u].r);
}}return d;
}
 static int sub(N[]a,int u){if(u<0)return 0;
return 1+sub(a,a[u].l)+sub(a,a[u].r);
}
 static long subSum(N[]a,int u){if(u<0)return 0;
return a[u].v+subSum(a,a[u].l)+subSum(a,a[u].r);
}
 static int lca(N[]a,int u,int v){ArrayList<Integer>p=new ArrayList<>(),q=new ArrayList<>();
path(a,0,u,p);
path(a,0,v,q);
int z=-1;
for(int i=0;i<Math.min(p.size(),q.size())&&p.get(i).equals(q.get(i));
i++)z=p.get(i);
return z;
}
 static boolean path(N[]a,int u,int t,List<Integer>p){if(u<0)return false;
p.add(u);
if(u==t)return true;
if(path(a,a[u].l,t,p)||path(a,a[u].r,t,p))return true;
p.remove(p.size()-1);
return false;
}
 static void inorder(N[]a,int u,List<Long>o){if(u<0)return;
inorder(a,a[u].l,o);
o.add(a[u].v);
inorder(a,a[u].r,o);
}
