 static int comp(N[]a,int u){if(u<0)return 0;
int lh=0,rh=0,x=u;
while(x>=0){lh++;
x=a[x].l;
}x=a[u].r;
while(x>=0){rh++;
x=a[x].l;
}if(lh==rh)return (1<<Math.min(lh,30))-1;
return 1+comp(a,a[u].l)+comp(a,a[u].r);
}
