 static void dfsPath(N[]a,int u,List<Long>cur,List<Long>best){if(u<0)return;
cur.add(a[u].v);
if(a[u].l<0&&a[u].r<0){if(cur.size()>best.size())best.clear();
if(cur.size()==best.size()&&best.isEmpty())best.addAll(cur);
}else{dfsPath(a,a[u].l,cur,best);
dfsPath(a,a[u].r,cur,best);
}cur.remove(cur.size()-1);
}
 static long downSum(N[]a,int u,long sum,long K,HashMap<Long,Integer>m){if(u<0)return 0;
long s=sum+a[u].v,ans=m.getOrDefault(s-K,0);
m.merge(s,1,Integer::sum);
ans+=downSum(a,a[u].l,s,K,m)+downSum(a,a[u].r,s,K,m);
m.put(s,m.get(s)-1);
return ans;
}
 static int[]postorder(N[]a){int[]o=new int[a.length];
int k=0;
if(a.length==0)return o;
ArrayDeque<Integer>s=new ArrayDeque<>();
s.push(0);
while(!s.isEmpty()){int u=s.pop();
o[k++]=u;
if(a[u].l>=0)s.push(a[u].l);
if(a[u].r>=0)s.push(a[u].r);
}return Arrays.copyOf(o,k);
}
