 static void leafOrder(N[]a,int u,List<Long>o,boolean rev){if(u<0)return;
if(a[u].l<0&&a[u].r<0){o.add(a[u].v);
return;
}if(rev){leafOrder(a,a[u].r,o,true);
leafOrder(a,a[u].l,o,true);
}else{leafOrder(a,a[u].l,o,false);
leafOrder(a,a[u].r,o,false);
}}
 static void uni(N[]a,int u,int[]c){if(u<0)return;
boolean ok=true;
if(a[u].l>=0){uni(a,a[u].l,c);
if(a[a[u].l].v!=a[u].v)ok=false;
}if(a[u].r>=0){uni(a,a[u].r,c);
if(a[a[u].r].v!=a[u].v)ok=false;
}if(ok)c[0]++;
}
 static int uniSize(N[]a,int u){if(u<0)return 0;
if((a[u].l>=0&&a[a[u].l].v!=a[u].v)||(a[u].r>=0&&a[a[u].r].v!=a[u].v))return 0;
int l=uniSize(a,a[u].l),r=uniSize(a,a[u].r);
if(a[u].l>=0&&l==0)return 0;
if(a[u].r>=0&&r==0)return 0;
return 1+l+r;
}
 static void uniBest(N[]a,int u,int[]best){if(u<0)return;
best[0]=Math.max(best[0],uniSize(a,u));
uniBest(a,a[u].l,best);
uniBest(a,a[u].r,best);
}
 static void alt(N[]a,int u,int len,int[]best){if(u<0)return;
best[0]=Math.max(best[0],len);
if(a[u].l>=0&&((a[u].v&1)!=(a[a[u].l].v&1)))alt(a,a[u].l,len+1,best);
else if(a[u].l>=0)alt(a,a[u].l,1,best);
if(a[u].r>=0&&((a[u].v&1)!=(a[a[u].r].v&1)))alt(a,a[u].r,len+1,best);
else if(a[u].r>=0)alt(a,a[u].r,1,best);
}
 static void mono2(N[]a,int u,int dir,int[]c){if(u<0)return;
if(a[u].l<0&&a[u].r<0){c[0]++;
return;
}if(a[u].l>=0){int nd=a[u].v<a[a[u].l].v?1:a[u].v>a[a[u].l].v?-1:0;
if(nd!=0&&(dir==0||dir==nd))mono2(a,a[u].l,nd,c);
else if(dir==0&&nd!=0)mono2(a,a[u].l,nd,c);
else if(nd!=0&&dir==nd)mono2(a,a[u].l,nd,c);
else monoBreak(a,a[u].l,c);
}if(a[u].r>=0){int nd=a[u].v<a[a[u].r].v?1:a[u].v>a[a[u].r].v?-1:0;
if(nd!=0&&(dir==0||dir==nd))mono2(a,a[u].r,nd,c);
else monoBreak(a,a[u].r,c);
}}
 static void monoBreak(N[]a,int u,int[]c){if(u<0)return;
if(a[u].l<0&&a[u].r<0){return;
}if(a[u].l>=0)monoBreak(a,a[u].l,c);
if(a[u].r>=0)monoBreak(a,a[u].r,c);
}
 static void mono(N[]a,int u,int[]c){if(u<0)return;
if(a[u].l<0&&a[u].r<0){c[0]++;
return;
}boolean inc=true,dec=true;
if(a[u].l>=0){if(a[a[u].l].v<=a[u].v)inc=false;
if(a[a[u].l].v>=a[u].v)dec=false;
}if(a[u].r>=0){if(a[a[u].r].v<=a[u].v)inc=false;
if(a[a[u].r].v>=a[u].v)dec=false;
}if(inc||dec)c[0]++;
if(a[u].l>=0)mono(a,a[u].l,c);
