    static long binom(int n,int k){k=Math.min(k,n-k);
long z=1;
for(int i=1;i<=k;i++){if(z>Long.MAX_VALUE/(n-k+i))return Long.MAX_VALUE;
z=z*(n-k+i)/i;
}return z;
}
    static int diam(T t,int u){if(u<0)return -1;
return Math.max(0,height(t,t.a.get(u).l)+height(t,t.a.get(u).r)+1);
}
    static boolean isBSTSub(T t,int u,long lo,long hi){if(u<0)return true;
long v=t.a.get(u).v;
return v>lo&&v<hi&&isBSTSub(t,t.a.get(u).l,lo,v)&&isBSTSub(t,t.a.get(u).r,v,hi);
}
    static class Opt{long cost;
T t;
Opt(long c,T t){cost=c;
this.t=t;
}}
    static Opt optimal(long[]k,long[]w,long[]dummy){int n=k.length;
if(n==0)return new Opt(0,new T());
long[]ps=new long[n+1];
for(int i=0;i<n;i++)ps[i+1]=ps[i]+w[i];
long[][]dp=new long[n][n];
int[][]rt=new int[n][n];
for(int i=0;i<n;i++){dp[i][i]=w[i];
rt[i][i]=i;
}for(int len=2;len<=n;len++)for(int l=0;l+len<=n;l++){int r=l+len-1;
long sum=ps[r+1]-ps[l];
dp[l][r]=Long.MAX_VALUE/4;
int from=rt[l][r-1],to=(r<n-1?rt[l+1][r]:r);
if(from<l)from=l;
if(to>r)to=r;
for(int z=from;z<=to;z++){long v=sum+(z>l?dp[l][z-1]:0)+(z<r?dp[z+1][r]:0);
if(v<dp[l][r]){dp[l][r]=v;
rt[l][r]=z;
}}}T t=new T();
t.a=new ArrayList<>(Collections.nCopies(n,null));
t.root=buildOpt(t,k,rt,0,n-1);
return new Opt(dp[0][n-1],t);
}
    static int buildOpt(T t,long[]k,int[][]rt,int l,int r){if(l>r)return -1;
int z=rt[l][r];
int id=z;
t.a.set(id,new N(k[z]));
t.a.get(id).l=buildOpt(t,k,rt,l,z-1);
t.a.get(id).r=buildOpt(t,k,rt,z+1,r);
return id;
}
    static Opt optimalUn(long[]k,long[]p,long[]q){int n=k.length;
long[][]dp=new long[n+1][n+1];
int[][]rt=new int[n][n];
for(int i=0;i<=n;i++)dp[i][i]=q[i];
for(int len=1;len<=n;len++)for(int l=0;l+len<=n;l++){int r=l+len;
long sum=q[l]+q[r];
for(int j=l;j<r;j++)sum+=p[j];
dp[l][r]=Long.MAX_VALUE/4;
for(int z=l;z<r;z++){long v=sum+dp[l][z]+dp[z+1][r];
if(v<dp[l][r]){dp[l][r]=v;
rt[l][r-1]=z;
}}}T t=new T();
t.a=new ArrayList<>(Collections.nCopies(n,null));
t.root=buildUn(t,k,rt,0,n-1);
return new Opt(dp[0][n],t);
}
    static int buildUn(T t,long[]k,int[][]rt,int l,int r){if(l>r)return -1;
int z=rt[l][r];
t.a.set(z,new N(k[z]));
t.a.get(z).l=buildUn(t,k,rt,l,z-1);
t.a.get(z).r=buildUn(t,k,rt,z+1,r);
return z;
}

    static java.math.BigInteger validInsertionBig(T t,int u){if(u<0)return java.math.BigInteger.ONE;
int l=t.a.get(u).l,r=t.a.get(u).r;
int ls=l<0?0:sz(t,l),rs=r<0?0:sz(t,r);
return binomBig(ls+rs,ls).multiply(validInsertionBig(t,l)).multiply(validInsertionBig(t,r));
}
    static java.math.BigInteger binomBig(int n,int k){k=Math.min(k,n-k);
java.math.BigInteger z=java.math.BigInteger.ONE;
for(int i=1;i<=k;i++)z=z.multiply(java.math.BigInteger.valueOf(n-k+i)).divide(java.math.BigInteger.valueOf(i));
return z;
}
    static void inorderIds(T t,int u,List<Integer> o){if(u<0)return;
inorderIds(t,t.a.get(u).l,o);
o.add(u);
inorderIds(t,t.a.get(u).r,o);
}

