    private static boolean isSymmetric(int[] nodes, int start, int end) {
        if (start >= end) {
            return true;
        }
        if (nodes[start] != nodes[end]) {
            return false;
        }
        return isSymmetric(nodes, start + 1, end - 1);
    }
}

