        int n = scanner.nextInt();
        Tree tree = new Tree();
        String[] arr = new String[n];
        for (int i = 0; i < n; i++) arr[i] = scanner.next();
        tree.root = tree.buildTree(arr, 0, n);
        System.out.println(tree.diameter(tree.root));
    }
