public class Main {
    static class Node {
        int val;
        Node left;
        Node right;
        Node(int val) {
            this.val = val;
        }
    }

    static class Tree {
        Node root;
        Node target;
        int k;
        Tree(Node root, Node target, int k) {
            this.root = root;
            this.target = target;
            this.k = k;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        Node[] nodes = new Node[n];
        for (int i = 0; i < n; i++) {
            nodes[i] = new Node(i);
        }
        for (int i = 0; i < n - 1; i++) {
            String[] line = br.readLine().split(" ");
            int parent = Integer.parseInt(line[0]);
            int child = Integer.parseInt(line[1]);
            if (nodes[parent].left == null) {
                nodes[parent].left = nodes[child];
            } else {
                nodes[parent].right = nodes[child];
            }
        }
        String[] line = br.readLine().split(" ");
        int target = Integer.parseInt(line[0]);
        int k = Integer.parseInt(line[1]);
        Tree tree = new Tree(nodes[0], nodes[target], k);
        List<Integer> res = new ArrayList<>();
        dfs(tree.root, tree.target, tree.k, res);
        for (int val : res) {
            System.out.println(val);
        }
    }

    static int dfs(Node node, Node target, int k, List<Integer> res) {
        if (node == null) {
            return -1;
        }
        if (node == target) {
            res.add(node.val);
            return 0;
        }
        int left = dfs(node.left, target, k, res);
        if (left != -1) {
            if (left + 1 == k) {
                res.add(node.val);
            } else {
                dfs(node.right, target, k - left - 1, res);
            }
            return left + 1;
        }
        int right = dfs(node.right, target, k, res);
        if (right != -1) {
            if (right + 1 == k) {
                res.add(node.val);
            } else {
                dfs(node.left, target, k - right - 1, res);
            }
            return right + 1;
        }
        return -1;
    }
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

class Node {
    int data;
    Node left, right, next;

    Node(int data) {
        this.data = data;
        left = right = next = null;
    }
}

public class Main {
    public static void connect(Node root) {
        if (root == null) return;
        Queue<Node> queue = new LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            Node cur = queue.poll(), prev = null;
            if (cur != null) {
                prev = cur;
                while (cur != null) {
                    Node next = cur.left != null ? cur.left : cur.right;
                    if (prev.next != null) {
                        prev.next.next = next;
                        prev = prev.next;
                    } else {
                        prev.next = next;
                        prev = prev.next;
                    }
                    cur = cur.right;
                }
                queue.offer(null);
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Node[] nodes = new Node[n + 1];
        for (int i = 1; i <= n; i++) {
            nodes[i] = new Node(sc.nextInt());
            if (i > 1) {
                nodes[sc.nextInt()].left = nodes[i];
                nodes[sc.nextInt()].right = nodes[i];
            }
        }
        connect(nodes[1]);
        for (int i = 1; i <= n; i++) {
            if (nodes[i].left != null && nodes[i].right != null) {
                System.out.print(nodes[i].left.data + " " + nodes[i].right.data + " ");
            } else {
                System.out.print(nodes[i].left != null ? nodes[i].left.data : -1 + " " + nodes[i].right.data + " ");
            }
        }
    }
}

