        if (start == end) {
            return node;
        }

        int iIndex = index;
        while (in[iIndex] != node.data) {
            iIndex++;
        }

        node.right = buildTreeUtil(pre, post, in, iIndex + 1, end, index);
        node.left = buildTreeUtil(pre, post, in, start, iIndex - 1, index);

        return node;
    }

    static void preOrder(Node node) {
        if (node == null) {
            return;
        }

        System.out.print(node.data + " ");
        preOrder(node.left);
        preOrder(node.right);
