class MorrisInorderTraversal {
    Node root;
    Node prev, curr;

    MorrisInorderTraversal(Node root) {
        this.root = root;
        this.prev = null;
        this.curr = null;
    }

    void printInorder() {
        if (root == null) return;

        curr = root;
        while (curr != null) {
            if (curr.left == null) {
                printNode(curr);
                curr = curr.right;
            } else {
                prev = curr.left;
                while (prev.right != null && prev.right != curr) {
                    prev = prev.right;
                }

                if (prev.right == null) {
                    prev.right = curr;
                    curr = curr.left;
                } else {
                    printNode(curr);
                    prev.right = null;
                    curr = curr.right;
                }
            }
        }
    }

    void printNode(Node node) {
        System.out.print(node.val + " ");
    }
}

