import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] values = new int[n];
        int[] lefts = new int[n];
        int[] rights = new int[n];
        for (int i = 0; i < n; i++) {
            values[i] = scanner.nextInt();
            lefts[i] = scanner.nextInt() - 1;
            rights[i] = scanner.nextInt() - 1;
        }
        System.out.println(isPossible(n, values, lefts, rights) ? "YES" : "NO");
    }

    private static boolean isPossible(int n, int[] values, int[] lefts, int[] rights) {
        int[] inDegree = new int[n];
        for (int i = 0; i < n; i++) {
            if (lefts[i] != -1) {
                inDegree[lefts[i]]++;
            }
            if (rights[i] != -1) {
                inDegree[rights[i]]++;
            }
        }
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (inDegree[i] == 0) {
                queue.offer(i);
            }
        }
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            if (lefts[cur] != -1) {
                if (values[lefts[cur]] >= values[cur]) {
                    return false;
                }
                if (--inDegree[lefts[cur]] == 0) {
                    queue.offer(lefts[cur]);
                }
            }
            if (rights[cur] != -1) {
                if (values[rights[cur]] <= values[cur]) {
                    return false;
                }
                if (--inDegree[rights[cur]] == 0) {
                    queue.offer(rights[cur]);
                }
            }
        }
        return true;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }
        System.out.println(minSwaps(arr));
    }

    static int minSwaps(int arr[]) {
        int n = arr.length;
        Pair[] pairs = new Pair[n];
        for (int i = 0; i < n; i++) {
            pairs[i] = new Pair(arr[i], i);
        }
        Arrays.sort(pairs);

        boolean[] visited = new boolean[n];
        Arrays.fill(visited, false);

        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (visited[i] || pairs[i].index == i) {
                continue;
            }

            int cycleSize = 0;
            int j = i;
            while (!visited[j]) {
                visited[j] = true;
                j = pairs[j].index;
                cycleSize++;
            }

            if (cycleSize > 0) {
                ans += (cycleSize - 1);
            }
        }

        return ans;
    }

    static class Pair implements Comparable<Pair> {
        int value;
        int index;

        Pair(int value, int index) {
