                        break;
                    }
                    current = current.left;
                } else {
                    if (!current.right) {
                        current.right = node;
                        break;
                    }
                    current = current.right;
                }
            }
        }
    }

    maxWidth() {
        if (!this.root) return 0;
        let queue = [this.root];
        let width = 0;
        while (queue.length) {
            width = Math.max(width, queue.length);
            let len = queue.length;
            for (let i = 0; i < len; i++) {
                if (queue[i].left) queue.push(queue[i].left);
                if (queue[i].right) queue.push(queue[i].right);
            }
            queue.length = len;
        }
        return width;
    }
}

