        let res = [];
        function solve(r, c, path) {
            if (r === n-1 && c === n-1) {
                res.push(path);
                return;
            }
            maze[r][c] = 0;
            if (r+1 < n && maze[r+1][c] === 1) solve(r+1, c, path+"D");
            if (c+1 < n && maze[r][c+1] === 1) solve(r, c+1, path+"R");
            if (r-1 >= 0 && maze[r-1][c] === 1) solve(r-1, c, path+"U");
            if (c-1 >= 0 && maze[r][c-1] === 1) solve(r, c-1, path+"L");
            maze[r][c] = 1;
        }
        if (maze[0][0] === 1) solve(0, 0, "");
        console.log(res.join("\n"));
        rl.close();
    }
});

const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
let lines = [];
rl.on('line', (line) => {
    lines.push(line.trim());
    if (lines.length >= 3) {
        const [v, e, m] = lines[0].split(/\s+/).map(Number);
        let adj = Array.from({length: v}, ()=>[]);
        for (let i = 1; i <= e; i++) {
            const [u, w] = lines[i].split(/\s+/).map(Number);
            adj[u-1].push(w-1);
            adj[w-1].push(u-1);
        }
        
        let colors = new Array(v).fill(0);
        function solve(node) {
            if (node === v) return true;
            for (let c = 1; c <= m; c++) {
                if (isSafe(node, c)) {
                    colors[node] = c;
                    if (solve(node + 1)) return true;
                    colors[node] = 0;
                }
            }
            return false;
        }
        function isSafe(node, color) {
            for (let neighbor of adj[node]) {
                if (colors[neighbor] === color) return false;
            }
            return true;
        }
        console.log(solve(0) ? "YES" : "NO");
        rl.close();
    }
});

