                if (L[i] <= R[j]) arr[k++] = L[i++];
                else arr[k++] = R[j++];
            }
            while (i < n1) arr[k++] = L[i++];
            while (j < n2) arr[k++] = R[j++];
        }
        mergeSort(arr, 0, n - 1);
        console.log(arr.join(" "));
        rl.close();
    }
