# P001641 - Determine Whether One Tree is a Subtree of Another

import sys
from collections import deque

def read_tree(it, n):
    values = [0] * n
    left = [-1] * n
    right = [-1] * n
    for i in range(n):
        values[i] = int(next(it))
        li = int(next(it))
        ri = int(next(it))
        if li > 0:
            left[i] = li - 1
        if ri > 0:
            right[i] = ri - 1
    return values, left, right

def serialize(v, l, r, root):
    out = []
    stack = [root]
    while stack:
        u = stack.pop()
        if u == -1:
            out.append(None)
            continue
        out.append(v[u])
        stack.append(r[u])
        stack.append(l[u])
    return out

def contains(text, pattern):
    if not pattern:
        return True
    pi = [0] * len(pattern)
    j = 0
    for i in range(1, len(pattern)):
        while j and pattern[i] != pattern[j]:
            j = pi[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
        pi[i] = j
    j = 0
    for x in text:
        while j and x != pattern[j]:
            j = pi[j - 1]
        if x == pattern[j]:
            j += 1
            if j == len(pattern):
                return True
    return False

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n1 = int(next(it))
    v1, l1, r1 = read_tree(it, n1) if n1 else ([], [], [])
    n2 = int(next(it))
    v2, l2, r2 = read_tree(it, n2) if n2 else ([], [], [])
    if n2 == 0:
        print('YES')
        return
    if n1 == 0:
        print('NO')
        return
    print('YES' if contains(serialize(v1, l1, r1, 0), serialize(v2, l2, r2, 0)) else 'NO')

if __name__ == "__main__":
    main()

