# P001649 - Construct a Binary Tree from Preorder and Inorder Traversals
import sys

def build_from_pre_in(pre, ino):
    n = len(pre)
    if n == 0:
        return [], [], -1
    values = pre[:]
    left = [-1] * n
    right = [-1] * n
    root = 0
    stack = [0]
    in_idx = 0
    for cur in range(1, n):
        if values[stack[-1]] != ino[in_idx]:
            left[stack[-1]] = cur
            stack.append(cur)
        else:
            last = -1
            while stack and values[stack[-1]] == ino[in_idx]:
                last = stack.pop()
                in_idx += 1
                if in_idx == n:
                    break
            right[last] = cur
            stack.append(cur)
    return values, left, right, root

def postorder(v, l, r, root):
    out = []
    stack = [(root, 0)]
    while stack:
        u, seen = stack.pop()
        if u == -1:
            continue
        if seen:
            out.append(str(v[u]))
        else:
            stack.append((u, 1))
            if r[u] != -1:
                stack.append((r[u], 0))
            if l[u] != -1:
                stack.append((l[u], 0))
