    left = [-1] * n
    right = [-1] * n
    root = n - 1
    stack = [root]
    in_idx = n - 1
    for cur in range(n - 2, -1, -1):
        if values[stack[-1]] != ino[in_idx]:
            right[stack[-1]] = cur
            stack.append(cur)
        else:
            last = -1
            while stack and values[stack[-1]] == ino[in_idx]:
                last = stack.pop()
                in_idx -= 1
                if in_idx < 0:
