def palindrome_partitions(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for gap in range(n):
        for i in range(n - gap):
            j = i + gap
            if gap == 0:
                dp[i][j] = 1
            elif gap == 1:
                dp[i][j] = s[i] == s[j]
            else:
                dp[i][j] = dp[i + 1][j - 1] and s[i] == s[j]

    palindromes = []
    for i in range(n):
        for j in range(i, n):
            if dp[i][j]:
                partition = s[i:j+1]
                if partition not in palindromes:
                    palindromes.append(partition)

    return sorted(palindromes)

