class Solution:
    def widthOfBST(self, root: TreeNode) -> int:
        if not root:
            return 0
        dq = deque([(root, 0)])
        max_width = 0

        while dq:
            first = dq[0][1]
            last = dq[-1][1]
            max_width = max(max_width, last - first + 1)

            for _ in range(len(dq)):
                node, idx = dq.popleft()
                cur_idx = idx - first
                if node.left: dq.append((node.left, 2 * cur_idx))
                if node.right: dq.append((node.right, 2 * cur_idx + 1))

        return max_width

