def boundary_traversal(root):
    if not root:
        return []
    res = []
    if root.left or root.right:
        res.append(root.val)
        
    # Left boundary
    node = root.left
    while node:
        if node.left or node.right:
            res.append(node.val)
        if node.left:
            node = node.left
        else:
            node = node.right
            
    # Leaves
    def add_leaves(node):
        if not node:
            return
        if not node.left and not node.right:
            res.append(node.val)
            return
        add_leaves(node.left)
        add_leaves(node.right)
        
    add_leaves(root.left)
    add_leaves(root.right)
    
    # Right boundary (reverse)
    stack = []
    node = root.right
    while node:
        if node.left or node.right:
            stack.append(node.val)
        if node.right:
            node = node.right
        else:
            node = node.left
            
    res.extend(stack[::-1])
    return res

