    if not root:
        return True
    q = deque([(root, 0)])
    while q:
        size = len(q)
        prev_val = None
        for i in range(size):
            node, level = q.popleft()
            if level % 2 == 0: # Even level -> Odd values, Strictly Increasing
                if node.val % 2 == 0:
                    return False
                if prev_val is not None and node.val <= prev_val:
                    return False
            else: # Odd level -> Even values, Strictly Decreasing
                if node.val % 2 != 0:
                    return False
                if prev_val is not None and node.val >= prev_val:
                    return False
