def clockwise_boundary(root):
    if not root:
        return []
    res = [root.val]
    
    # Left boundary (excluding leaves)
    node = root.left
    while node:
        if node.left or node.right:
            res.append(node.val)
        if node.left:
            node = node.left
        else:
