    # Right boundary (excluding leaves, reverse)
    stack = []
    node = root.right
    while node:
        if node.left or node.right:
            stack.append(node.val)
        if node.right:
            node = node.right
        else:
            node = node.left
    res.extend(stack[::-1])
    
    return res

