        if not node:
            return None
        if node.val == val:
            return node
        left = find_node(node.left, val)
        if left:
            return left
        return find_node(node.right, val)
        
    u_node = find_node(root, u_val)
    v_node = find_node(root, v_val)
    
    if not u_node or not v_node:
