struct Fenwick {
    int n;
    vector<int> bit;
    Fenwick(int n): n(n), bit(n + 1, -1) {}
    void update(int i, int v) {
        for (++i; i <= n; i += i & -i) bit[i] = max(bit[i], v);
    }
    int query(int i) const {
        int ans = -1;
        for (; i > 0; i -= i & -i) ans = max(ans, bit[i]);
        return ans;
    }
};

