        return [];
    }

    let triangle = [[1]];

    for (let row = 1; row < numRows; row++) {
        let prevRow = triangle[row - 1];
        let newRow = [1];

        for (let i = 1; i < prevRow.length; i++) {
            let leftParent = prevRow[i - 1];
            let rightParent = prevRow[i];

            newRow[i] = leftParent + rightParent;
        }

        newRow.push(1);
        triangle.push(newRow);

    }

    return triangle;
}

