    public static List<Integer> findAnagrams(String s, String p) {
        List<Integer> result = new ArrayList<>();
        if (s.length() == 0 || p.length() == 0) {
            return result;
        }
        int m = p.length();
        int n = s.length();
        for (int i = 0; i <= n - m; i++) {
            if (isAnagram(s.substring(i, i + m), p)) {
                result.add(i);
            }
        }
        return result;
    }

