    private static int findMinPrefixLength(int[] arr, int x) {
        int left = 0, right = arr.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (getSum(arr, mid) >= x) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

    private static int getSum(int[] arr, int prefixLength) {
        int sum = 0;
        for (int i = 0; i < prefixLength; i++) {
            sum += arr[i];
        }
        return sum;
    }
}

