    public static int[] finalPrices(int[] prices) {
        int n = prices.length;
        int[] stack = new int[n];
        int[] ans = new int[n];
        Arrays.fill(ans, -1);
        int top = -1;
        for (int i = n - 1; i >= 0; i--) {
            while (top != -1 && prices[stack[top]] > prices[i]) {
                ans[stack[top]] = prices[i];
                top--;
            }
            stack[++top] = i;
        }
        for (int i = 0; i < n; i++) {
            if (ans[i] == -1) {
                ans[i] = prices[i];
            }
        }
        return ans;
    }
}

