int maxSubarray(int* nums, int n) {
    int max = 0;
    int sum = 0;
    int max_sum = 0;
    for (int i = 0; i < n; i++) {
        if (sum == 0) {
            sum += nums[i];
        } else {
            sum += nums[i];
            if (sum > max_sum) {
                max_sum = sum;
                max = i - sum + 1;
            }
        }
    }
    return max;
}

