int minMutation(string start, string end, int n, vector<string> bank) {
    unordered_set<string> s(bank.begin(), bank.end());
    queue<pair<string, int>> q;
    q.push({start, 0});
    s.erase(start);
    while (!q.empty()) {
        string t = q.front().first;
        int step = q.front().second;
        q.pop();
        if (t == end)
            return step;
        for (int i = 0; i < 8; i++)
            for (int j = i + 1; j < 8; j++) {
                swap(t[i], t[j]);
                if (s.count(t)) {
                    q.push({t, step + 1});
                    s.erase(t);
                }
                swap(t[i], t[j]);
            }
    }
    return -1;
}

