        if (arr[i] === 'A') arr[i] = 'B';
        if (arr[i] === 'C') arr[i] = 'D';
        if (arr[i] === 'G') arr[i] = 'I';
        if (arr[i] === 'T') arr[i] = 'V';
        neighbors.push(arr.join(''));
        arr[i] = gene[i];
    }
    return neighbors;
