int max_fruits(int n, int arr[]) {
    int i, j, max_count;
    max_count = 1;

    for (i = 0; i < n-1; i++) {
        if (arr[i] == arr[i+1]) {
            j = i + 1;
            while (j < n && arr[j] == arr[i]) {
                j++;
            }
            if (j-i+1 > max_count) {
                max_count = j-i+1;
            }
            i = j-1;
        }
    }
    return max_count;
}

