def maxFruits(arr):
    left = 0
    right = 0
    max_fruits = 0
    fruit_dict = {}
    
    while right < len(arr):
        fruit_dict[arr[right]] = fruit_dict.get(arr[right], 0) + 1
        while len(fruit_dict) > 2:
            fruit_dict[arr[left]] = fruit_dict[arr[left]] - 1
            if fruit_dict[arr[left]] == 0:
                del fruit_dict[arr[left]]
            left += 1
        max_fruits = max(max_fruits, right - left + 1)
        right += 1
    
    return max_fruits

