void processString(char* s) {
    int len = strlen(s);
    int i = 0;

    while(i < len) {
        if(islower(s[i])) {
            if(i > 0 && islower(s[i-1]) && !strchr(s, s[i])) {
                for(int j = i-1; j >= 0; --j) {
                    if(islower(s[j]) && !strchr(s, s[j])) {
                        s[j] = s[j+1];

                        for(int k = j+2; k < len; k++) {
                            s[k-1] = s[k];
                        }

                        len -= 2;
                        break;
                    }
                }
            }
        }

        i++;
    }
}

