string clearDigits(string s) {
    stack<char> st;
    for(int i=0; i<s.length(); i++){
        if(s[i]>='a' && s[i]<='z'){
            st.push(s[i]);
        }
        else if(s[i]>='0' && s[i]<='9'){
            if(!st.empty() && st.top()>='a' && st.top()<='z'){
                st.pop();
            }
            else{
                s[i]='0'+s[i];
            }
        }
    }

    while(!st.empty()){
        s=s.substr(0,s.length()-1);
        st.pop();
    }

    return s;
}

