long int uniqueBinarySearchTrees(int N) {
    long int dp[N+1];
    dp[0] = 1;
    dp[1] = 1;

    for(int i=2; i<=N; i++) {
        dp[i] = 0;
        for(int j=1; j<=i; j++) {
            dp[i] += dp[j-1] * dp[i-j];
        }
    }

    return dp[N];
}

