void expandAround(char* s, int left, int right, char* maxStr, int* maxLen) {
    while (left >= 0 && right < strlen(s) && s[left] == s[right]) {
        left--;
        right++;
    }
    if (right - left - 1 > *maxLen) {
        maxStr[0] = s[left + 1];
        maxLen[0] = right - left - 1;
    }
}

void longestPalindrome(char* s) {
    char maxStr[1000];
    int maxLen = 0;
    for (int i = 0; i < strlen(s); i++) {
        expandAround(s, i, i, maxStr, &maxLen);
        expandAround(s, i, i + 1, maxStr, &maxLen);
    }
    printf("%s", maxStr);
}

