    string best;
    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        string odd = expand(s, i, i);
        string even = expand(s, i, i + 1);
        if (odd.size() > best.size()) {
            best = odd;
        }
        if (even.size() > best.size()) {
            best = even;
        }
    }
    cout << best;
