#include <iostream>
using namespace std;

string longestPalindrome(string s) {
    int n = s.length();
    if (n < 2) return s;

    bool dp[n][n];

    for (int i = 0; i < n; i++) {
        dp[i][i] = true;
    }

    int maxLen = 1;
    int start = 0;

    for (int i = 0; i < n - 1; i++) {
        if (s[i] == s[i + 1]) {
            dp[i][i + 1] = true;
            start = i;
            maxLen = 2;
        }
    }

    for (int length = 3; length <= n; length++) {
        for (int i = 0; i < n - length + 1; i++) {
            int j = i + length - 1;
            if (dp[i + 1][j - 1] && s[i] == s[j]) {
                dp[i][j] = true;
                start = i;
                maxLen = length;
            }
        }
    }

