typedef struct {
    int num;
    int freq;
} Number;

void swap(Number *a, Number *b) {
    Number temp = *a;
}

int partition(Number arr[], int low, int high) {
    Number pivot = arr[high];
    int i = (low - 1);

    for (int j = low; j <= high - 1; j++) {
        if (arr[j].freq > pivot.freq) {
            i++;
            swap(&arr[i], &arr[j]);
        } else if (arr[j].freq == pivot.freq) {
            if (arr[j].num < pivot.num) {
                i++;
                swap(&arr[i], &arr[j]);
            }
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

void quickSort(Number arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);

        quickSort(arr, low, pi - 1);
        quickSort(arr + 1, pi + 1, high);
    }
}

