using namespace std;

int maxLength(vector<string> &words) {
    int maxLength = 0;
    vector<int> dp(1 << words.size(), 0);
    vector<int> dp2(1 << words.size(), 1 << words.size() - 1);
    for (int mask = 0; mask < 1 << words.size(); ++mask) {
        if (__builtin_popcount(mask) > 1) {
            continue;
        }
        bool flag = false;
        for (int i = 0; i < words.size(); ++i) {
            if ((mask >> i) & 1) {
                for (char c : words[i]) {
                    if ((mask >> (c - 'a')) & 1) {
                        flag = true;
                        break;
                    }
                    (mask >>= (c - 'a')) &= ~1;
                }
                if (!flag) {
                    break;
                }
            }
        }
        if (flag) {
            for (int i = 0; i < words.size(); ++i) {
                if ((mask >> i) & 1) {
                    for (char c : words[i]) {
                        (mask >>= (c - 'a')) &= ~1;
                    }
                }
            }
            for (int i = 0; i < words.size(); ++i) {
                if ((mask >> i) & 1) {
                    for (char c : words[i]) {
                        (mask >>= (c - 'a')) &= ~1;
                    }
                }
            }
            dp[mask] = max(dp[mask], dp2[mask] + 2);
            maxLength = max(maxLength, dp[mask]);
        }
    }
    return maxLength;
}

