int median(int a[], int n, int b[], int m) {
    int i = 0, j = 0, k = 0;
    int c[n + m];

    while(i < n && j < m) {
        if(a[i] < b[j])
            c[k++] = a[i++];
        else
            c[k++] = b[j++];
    }

    while(i < n)
        c[k++] = a[i++];

    while(j < m)
        c[k++] = b[j++];

    if(n + m == 1)
        return c[0];

    if((n + m) % 2 == 0)
        return c[n + m - 1] / 2;

    return c[n + m / 2];
}

