        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        String[] h=br.readLine().trim().split("\\s+");
        int m=Integer.parseInt(h[0]), n=Integer.parseInt(h[1]);
        int[] a=read(br,m), b=read(br,n);
        if((m+n)%2==1){
            System.out.println(kth(a,b,(m+n)/2+1));
        } else{
            long x=kth(a,b,(m+n)/2);
            long y=kth(a,b,(m+n)/2+1);
            System.out.println((x+y)/2.0);
        }
    }
    static int[] read(BufferedReader br,int n)throws Exception{
        String[] s=br.readLine().trim().split("\\s+");
        int[] a=new int[n];
        for(int i=0;i<n;i++)a[i]=Integer.parseInt(s[i]);
        return a;
    }
    static int kth(int[] a,int[] b,int k){
        if(a.length>b.length)return kth(b,a,k);
        int lo=Math.max(0,k-b.length),hi=Math.min(k,a.length);
        while(lo<=hi){
            int cutA=(lo+hi)>>>1,cutB=k-cutA;
            int la=cutA==0?Integer.MIN_VALUE:a[cutA-1];
            int ra=cutA==a.length?Integer.MAX_VALUE:a[cutA];
            int lb=cutB==0?Integer.MIN_VALUE:b[cutB-1];
            int rb=cutB==b.length?Integer.MAX_VALUE:b[cutB];
            if(la<=rb && lb<=ra)return Math.max(la,lb);
            if(la>rb)hi=cutA-1;
            else lo=cutA+1;
        }
        throw new IllegalArgumentException();
    }
}

