#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

#define MAX_LEN 1000
#define MAX_OPS 20

typedef enum {
    ADD, SUB, MUL, DIV, NUM, OTHER
} OpType;

typedef struct {
    OpType op;
    double val;
} Operand;

typedef struct {
    Operand op;
    int count;
} Operator;

double evaluate(char* expression);
double applyOperation(OpType op, double a, double b);
Operator* createOperator(OpType op);
double pop(Operator** ops, double* values);

int main(void) {
    char expression[MAX_LEN];

    printf("Enter the expression: ");
    fgets(expression, MAX_LEN, stdin);
    expression[strcspn(expression, "\n")] = 0;

    double result = evaluate(expression);
    printf("Result: %.6lf\n", result);

    return 0;
}

double evaluate(char* expression) {
    Operator* ops = NULL;
    double* values = NULL;
    int opsCount = 0;
    double num = 0, result = 0;
    char op;

    for (char* token = strtok(expression, " "); token != NULL; token = strtok(NULL, " ")) {
        switch (token[0]) {
            case '+':
                op = ADD;
                break;
            case '-':
                op = SUB;
                break;
            case '*':
                op = MUL;
                break;
            case '/':
                op = DIV;
                break;
            default:
                if (isdigit(token[0])) {
                    num = atof(token);
                } else {
                    return 0;
                }
                continue;
        }

        if (opsCount == 0 || ops[opsCount - 1].op != op) {
            ops[opsCount] = *createOperator(op);
            opsCount++;
        } else {
            result = applyOperation(op, pop(&ops, &values), num);
            values[--ops[opsCount - 1].count] = result;
        }

        num = 0;
    }

    return pop(&ops, &values);
}

Operator* createOperator(OpType op) {
    Operator* o = malloc(sizeof(Operator));
    o->op = op;
    o->count = 0;

    return o;
}

double pop(Operator** ops, double* values) {
    double result = values[--ops[opsCount - 1].count];

    if (ops[opsCount - 1].count == 0) {
        free(ops[--opsCount]);
    }

    return result;
}

double applyOperation(OpType op, double a, double b) {
    switch (op) {
        case ADD:
            return a + b;
        case SUB:
            return a - b;
        case MUL:
            return a * b;
        case DIV:
            return a / b;
        default:
            return 0;
    }
}

