            else if (sign == '-') st.push_back(-num);
            else if (sign == '*') {
                int prev = st.back(); st.pop_back();
                st.push_back(prev * num);
            } else if (sign == '/') {
                int prev = st.back(); st.pop_back();
                st.push_back(prev / num);
            }
            sign = c;
            num = 0;
        }
    }
