            } else if(sign == '/') {
                pre /= num;
            }
            if(i < len - 1 && (s.charAt(i + 1) == '+' || s.charAt(i + 1) == '-' || s.charAt(i + 1) == '*' || s.charAt(i + 1) == '/')) {
                sign = s.charAt(i + 1);
            }
            num = 0;
        }
        return res + pre;
    }
}

