int find(int node) {
    if (node == parent[node]) return node;
    return parent[node] = find(parent[node]);
}

void union_set(int node1, int node2) {
    node1 = find(node1);
    node2 = find(node2);
    if (node1 != node2) parent[node2] = node1;
}

bool check(int node1, int node2) {
    node1 = find(node1);
    return node1 == find(node2);
}

int main() {
    int N, M, Q;
    scanf("%d %d %d", &N, &M, &Q);
    for (int i = 0; i <= N; i++) {
        parent[i] = i;
        reachable[i] = false;
    }
    while (M--) {
        int u, v;
        scanf("%d %d", &u, &v);
        union_set(u, v);
    }
    while (Q--) {
        int u, v;
        scanf("%d %d", &u, &v);
        printf(check(u, v) ? "YES\n" : "NO\n");
    }
    return 0;
}

