const getParent = (x, p) => {
    if (p[x] == x) return x;
    return getParent(p[x], p);
}

const union = (x, y, p, rank) => {
    x = getParent(x, p);
    y = getParent(y, p);

    if (x == y) return false;

    if (rank[x] < rank[y]) {
        p[x] = y;
        rank[y] += rank[x];
    } else {
        p[y] = x;
        rank[x] += rank[y];
    }

    return true;
}

