    for(auto& interval : intervals) {
        int min_end = interval[1];
        bool found = false;
        for(auto& other : intervals) {
            if(other[0] >= min_end) {
                result.push_back(other[1]);
                found = true;
                break;
            }
        }
        if(!found) {
            result.push_back(-1);
        }
    }
    return result;
}

