        if (!this.head || !this.head.next) {
            return this.head;
        }
        let current = this.head;
        while (current !== null) {
            let nextValue = current.next.value;
            let currentValue = current.value;
            let gcd = this.gcd(currentValue, nextValue);
            current.next.value = gcd;
            current = current.next;
        }
        return this.head;
    }
}

