void addParentheses(char* str, int start, int end, char* out, int outIndex) {
    if (start == end) {
        out[outIndex] = str[start];
        outIndex++;
        out[outIndex] = '\0';
        printf("%s\n", out);
        return;
    }
    out[outIndex] = str[start];
    outIndex++;
    out[outIndex] = '(';
    outIndex++;
    addParentheses(str, start + 1, end, out, outIndex);
    out[outIndex] = ')';
    outIndex++;
    if (start + 1 < end) {
        out[outIndex] = ' ';
        outIndex++;
        addParentheses(str, start + 1, end, out, outIndex);
    }
}

