// Split the expression at every operator and combine all left/right sub-results recursively.
public class Main {
    static Map<String, List<Integer>> memo = new HashMap<>();
    static List<Integer> ways(String e) {
        if (memo.containsKey(e)) return memo.get(e);
        List<Integer> out = new ArrayList<>();
        for (int i = 0; i < e.length();
        i++) {
            char op = e.charAt(i);
            if (op != '+' && op != '-' && op != '*') continue;
            List<Integer> left = ways(e.substring(0, i)), right = ways(e.substring(i + 1));
            for (int a : left) for (int b : right)
            out.add(op == '+' ? a + b : op == '-' ? a - b : a * b);
        }
        if (out.isEmpty()) out.add(Integer.parseInt(e));
        memo.put(e, out);
        return out;
    }
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String e = br.readLine();
        if (e == null) return;
        for (int x : ways(e.replace(" ", ""))) System.out.println(x);
    }
}

