                            case '*':
                                res.add(n1 * n2);
                                break;
                        }
                    }
                }
            }
        }
        if (res.isEmpty()) {
            res.add(Integer.valueOf(input));
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.next();
        List<Integer> result = diffWaysToCompute(input);
        for (int num : result) {
            System.out.println(num);
        }
    }
}

