void swapKth(struct Node* head, int k) {
    struct Node* p1 = head;
    struct Node* p2 = head;

    for (int i = 0; i < k; i++) {
        if (p2 == NULL) {
            printf("Error: K is larger than the length of the list.\n");
            return;
        }
        p2 = p2->next;
    }

    while (p2 != NULL) {
        p2 = p2->next;
        p1 = p1->next;
    }

    int temp = p1->data;
    p1->data = p1->next->data;
    p1->next->data = temp;
}

