function swapNodes(head, k) {
  if (k <= 0 || k > head.length) {
    return head;
  }

  let arr = [];
  let current = head;
  let index = 0;

  while (current !== null) {
    arr.push(current.val);
    current = current.next;
    index++;
  }

  [arr[k - 1], arr[index - k]] = [arr[index - k], arr[k - 1]];

  current = head;
  for (let i = 0; i < index; i++) {
    current.val = arr[i];
    if (i < index - 1) {
      current.next = new ListNode(arr[i + 1]);
      current = current.next;
    }
  }

  return head;
}

