bool dfs(int u, int count, int n, EdgeNode** adj, bool* vis) {
    if (count == n) {
        EdgeNode* cur = adj[u];
        while (cur) {
            if (cur->v == 0) return true;
            cur = cur->next;
        }
        return false;
    }
    vis[u] = true;
    EdgeNode* cur = adj[u];
    while (cur) {
        if (!vis[cur->v] && dfs(cur->v, count + 1, n, adj, vis)) return true;
        cur = cur->next;
    }
    vis[u] = false;
    return false;
}

