    public static boolean hamiltonianCycle(int current, int start) {
        visited[start] = true;
        path[current] = start;

        if (current == N) {
            if (graph[start][0] == 1) {
                return true;
            } else {
                return false;
            }
        } else {
            for (int i = 1; i < N; i++) {
                if (graph[start][i] == 1 && !visited[i]) {
                    if (hamiltonianCycle(current + 1, i)) {
                        return true;
                    }
                }
            }
        }

        visited[start] = false;
        return false;
    }
}

