    const vis = new Array(n).fill(false);

    // Helper function to evaluate dfs for problem constraints.
    function dfs(u, count) {
        if (count === n) return adj[u].includes(0);
        vis[u] = true;
        for (const v of adj[u]) {
            if (!vis[v] && dfs(v, count + 1)) return true;
        }
        vis[u] = false;
        return false;
    }

    return dfs(0, 1);
}

