    int freq[MAX_TRIP_COUNT];
    int size;
} Itinerary;

void init_itinerary(Itinerary *it) {
    it->size = 0;
}

void add_trip(Itinerary *it, char *departure, char *arrival) {
    assert(it->size < MAX_TRIP_COUNT);
    strcpy(it->airports[it->size], arrival);
    strcpy(it->airports[it->size + 1], departure);
    it->freq[it->size] = 1;
    it->size += 2;
}

char *get_smallest_itinerary(Itinerary *it) {
    for (int i = 0; i < it->size; i++) {
        for (int j = 0; j < it->size - i - 1; j++) {
            if (it->freq[j] < it->freq[j + 1]) {
                char *tmp = it->airports[j];
                it->airports[j] = it->airports[j + 1];
                it->airports[j + 1] = tmp;

                int tmp_freq = it->freq[j];
                it->freq[j] = it->freq[j + 1];
                it->freq[j + 1] = tmp_freq;
            }
        }
    }
    return it->airports[0];
}

