using namespace std;
vector<long long> seg;
void build(vector<long long>&a,int node,int s,int e){
    if(s==e){seg[node]=a[s];return;}
    int m=(s+e)/2;
    build(a,2*node,s,m);build(a,2*node+1,m+1,e);
    seg[node]=min(seg[2*node],seg[2*node+1]);
}
void update(int node,int s,int e,int idx,long long val){
    if(s==e){seg[node]=val;return;}
    int m=(s+e)/2;
    if(idx<=m)update(2*node,s,m,idx,val);else update(2*node+1,m+1,e,idx,val);
    seg[node]=min(seg[2*node],seg[2*node+1]);
}
long long query(int node,int s,int e,int l,int r){
    if(r<s||e<l) return LLONG_MAX;
    if(l<=s&&e<=r) return seg[node];
    int m=(s+e)/2;
    return min(query(2*node,s,m,l,r),query(2*node+1,m+1,e,l,r));
}
