void findMaxNumber(string& num, int k, int index, string& maxNum) {
    if (k == 0 || index == num.length()) {
        if (num > maxNum) maxNum = num;
        return;
    }
    
    char maxChar = num[index];
    for (int i = index + 1; i < num.length(); ++i) {
        if (num[i] > maxChar) maxChar = num[i];
