    if (maxChar != num[index]) {
        for (int i = index + 1; i < num.length(); ++i) {
            if (num[i] == maxChar) {
                swap(num[index], num[i]);
                findMaxNumber(num, k - 1, index + 1, maxNum);
                swap(num[index], num[i]);
            }
        }
    } else {
        findMaxNumber(num, k, index + 1, maxNum);
    }
}

