    static void search(int pos, int left) {
        if (pos == digits.length || left == 0) {
            String cur = new String(digits);
            if (cur.compareTo(best) > 0) best = cur;
            return;
        }
        char largest = digits[pos];
        for (int j = pos + 1; j < digits.length; j++) largest = (char)Math.max(largest, digits[j]);
        if (largest == digits[pos]) {
            search(pos + 1, left);
            return;
