        for (int j = digits.length - 1; j > pos; j--) {
            if (digits[j] != largest) continue;
            char t = digits[pos];
            digits[pos] = digits[j];
            digits[j] = t;
            search(pos + 1, left - 1);
            t = digits[pos];
            digits[pos] = digits[j];
            digits[j] = t;
        }
    }

