function getMaxNumber(string, k) {
  let digits = Array.from(string, Number);
  digits.sort((a, b) => b - a);
  let map = {};
  for (let i = 0; i < digits.length; i++) {
    if (map[digits[i]]) {
      map[digits[i]].push(i);
    } else {
      map[digits[i]] = [i];
    }
  }
  let sortedDigits = Array.from({ length: digits.length }, () => -1);
  let count = 0;
  while (count < k) {
    let maxIndex = -1;
    for (let i = 0; i < digits.length; i++) {
      if (map[digits[i]] && map[digits[i]].length > 0) {
        let index = map[digits[i]].pop();
        sortedDigits[index] = digits[i];
        maxIndex = Math.max(maxIndex, index);
      }
    }
    if (maxIndex != -1) {
      digits[maxIndex] = digits[sortedDigits[maxIndex]];
      map[digits[maxIndex]] = [sortedDigits[maxIndex]];
      count++;
    } else {
      break;
    }
  }
  return digits.join('');
}

// Helper function to evaluate maximumswap for problem constraints.
function maximumSwap(num) {
    const digits = String(num).split('');
    const last = {};
    digits.forEach((d, i) => { last[d] = i; });

    for (let i = 0; i < digits.length; i++) {
        for (let d = 9; d > Number(digits[i]); d--) {
            if (last[d] > i) {
                [digits[i], digits[last[d]]] = [digits[last[d]], digits[i]];
                return Number(digits.join(''));
            }
        }
    }
    return num;
}

