def tree_lines(root):
    if root is None:return ["0"]
    nodes=[]; q=deque([root]); seen=set()
    while q:
        x=q.popleft()
        if id(x) in seen: continue
        seen.add(id(x)); nodes.append(x)
        if x.l:q.append(x.l)
        if x.r:q.append(x.r)
    idx={id(x):i+1 for i,x in enumerate(nodes)}
    out=[str(len(nodes))]
    for x in nodes: out.append(f"{x.v} {idx.get(id(x.l),-1)} {idx.get(id(x.r),-1)}")
    return out

def inorder(root):
    out=[]; st=[]; x=root
    while st or x:
        while x: st.append(x); x=x.l
        x=st.pop(); out.append(x.v); x=x.r
    return out

def preorder(root):
    if not root:return []
    out=[]; st=[root]
    while st:
        x=st.pop(); out.append(x.v)
        if x.r:st.append(x.r)
        if x.l:st.append(x.l)
    return out

def postorder(root):
    if not root:return []
    out=[]; st=[(root,0)]
    while st:
        x,s=st.pop()
        if s: out.append(x.v); continue
        st.append((x,1))
        if x.r:st.append((x.r,0))
        if x.l:st.append((x.l,0))
    return out

def levels(root):
    if not root:return []
    q=deque([root]); out=[]
    while q:
        cur=[]
        for _ in range(len(q)):
            x=q.popleft(); cur.append(x)
            if x.l:q.append(x.l)
            if x.r:q.append(x.r)
        out.append(cur)
    return out

def make_bst(seq):
    root=None
    for v in seq:
        if root is None: root=Node(v); continue
        x=root
        while True:
            if v<x.v:
                if x.l:x=x.l
                else:x.l=Node(v);break
            elif v>x.v:
                if x.r:x=x.r
                else:x.r=Node(v);break
            else: break
    return root

