        std::vector<int> res;
        auto p1 = a.begin(), p2 = b.begin();
        while (p1 != a.end() || p2 != b.end()) {
            if (std::lexicographical_compare(p1, a.end(), p2, b.end())) {
                res.push_back(*p2++);
            } else {
                res.push_back(*p1++);
            }
        }
        return res;
    }
