SegTreeNode makeNode(int left, int right, int min, int max) {
    SegTreeNode node;
    node.left = left;
    node.right = right;
    node.min = min;
    node.max = max;
    return node;
}

SegTreeNode initSegTree(int left, int right) {
    if (left > right) return makeNode(INF, INF, INF, INF);
    if (left == right) {
        return makeNode(arr[left], arr[left], arr[left], arr[left]);
    }
    int mid = (left + right) / 2;
    SegTreeNode node = initSegTree(left, mid);
    SegTreeNode rnode = initSegTree(mid + 1, right);
    node.min = node.left < node.right ? node.left : node.right;
    node.max = node.left < node.right ? node.right : node.left;
    node.min = node.min < rnode.min ? node.min : rnode.min;
    node.max = node.max > rnode.max ? node.max : rnode.max;
    return node;
}

void reconstruct(SegTreeNode node, int start, int end, int* index) {
    if (start > end) return;
    if (node.left == node.right) {
        arr[*index] = node.min;
        (*index)++;
        return;
    }
    int mid = (node.left + node.right) / 2;
    if (*index <= mid) {
        reconstruct(segTree[2 * node.left], start, mid, index);
    } else {
        reconstruct(segTree[2 * node.right + 1], mid + 1, end, index);
    }
}

