}

void mergeKArrays(int k, int *arr[], int *result) {
    int size = 0;
    Node nodes[100000];

    for (int i = 0; i < k; i++) {
        for (int j = 0; j < k; j++) {
            if (arr[i][j] != INT_MAX) {
                nodes[size].val = arr[i][j];
                nodes[size].arrIndex = i;
                nodes[size].nextIndex = j + 1;
                size++;
            }
        }
    }

    qsort(nodes, size, sizeof(Node), compare);

    int r = 0;
    for (int i = 0; i < size; i++) {
        result[r] = nodes[i].val;
        r++;
    }

    for (int i = 0; i < size; i++) {
        if (nodes[i].nextIndex < k && arr[nodes[i].arrIndex][nodes[i].nextIndex] != INT_MAX) {
            nodes[i].val = arr[nodes[i].arrIndex][nodes[i].nextIndex];
        } else {
            nodes[i].val = INT_MAX;
        }
    }

    qsort(nodes, size, sizeof(Node), compare);

    for (int i = 0; i < size; i++) {
        result[r] = nodes[i].val;
        r++;
    }
}

