    for (int i = 0; i < itemCount; i++) {
        while (items[i].count > 0) {
            res[idx] = items[i].val;
            items[i].count--;
            idx += 2;
            if (idx >= barcodesSize) idx = 1;
        }
    }

    free(freq);
    free(items);
