function isAnagram(s, t) {
    if (s.length !== t.length) {
        return false;
    }
    const count = new Array(256).fill(0);
    for (let i = 0; i < s.length; i++) {
        count[s.charCodeAt(i)]++;
        count[t.charCodeAt(i)]--;
    }
    for (let i = 0; i < 256; i++) {
        if (count[i] !== 0) {
            return false;
        }
    }
    return true;
}

