        int gold = grid[r][c];
        grid[r][c] = 0;

        int maxSub = Math.max(
            Math.max(dfs(grid, r + 1, c), dfs(grid, r - 1, c)),
            Math.max(dfs(grid, r, c + 1), dfs(grid, r, c - 1))
        );

        grid[r][c] = gold;
        return gold + maxSub;
    }

