long long modular_exponentiation(long long base, long long exp, long long mod) {
    if (exp == 0) {
        return 1;
    } else if (exp % 2 == 0) {
        long long half_exp = modular_exponentiation(base, exp / 2, mod);
        return (half_exp * half_exp) % mod;
    } else {
        return ((base % mod) * (modular_exponentiation(base, exp - 1, mod))) % mod;
    }
}

