using namespace std;
using u64 = unsigned long long;

u64 addMod(u64 a, u64 b, u64 mod) {
    // Addition is kept below mod without overflowing even when mod is near 10^18.
    return a >= mod - b ? a - (mod - b) : a + b;
}

u64 mulMod(u64 a, u64 b, u64 mod) {
    // Double-and-add avoids a*b overflow while computing the modular product.
    u64 result = 0;
    while (b > 0) {
        if (b & 1ULL) result = addMod(result, a, mod);
        a = addMod(a, a, mod);
        b >>= 1;
    }
    return result;
}

u64 modPow(u64 base, u64 exp, u64 mod) {
    // Repeated squaring reduces the exponent by half at every recursive level.
    if (exp == 0) return 1 % mod;
    u64 half = modPow(base, exp / 2, mod);
    u64 result = mulMod(half, half, mod);
    if (exp & 1ULL) result = mulMod(result, base % mod, mod);
    return result;
}

