def power_recursive(base, exponent, mod):
    if exponent == 0:
        return 1
    elif exponent % 2 == 0:
        half_exp = power_recursive(base, exponent // 2, mod)
        return (half_exp * half_exp) % mod
    else:
        return (base * power_recursive(base, exponent - 1, mod)) % mod


