int can_segment(char *str) {
    int len = strlen(str);
    dp[len] = 1;

    for (int i = len - 1; i >= 0; i--) {
        for (int j = 0; j < num_words; j++) {
            if (dp[i] && strncmp(str + i, words[j], len - i) == 0) {
                dp[i] = dp[i + strlen(words[j])];
                break;
            }
        }
    }

    return dp[0];
}

