    public static boolean wordBreak(String s, Set<String> dict) {
        boolean[] f = new boolean[s.length() + 1];
        f[0] = true;
        for (int i = 1; i <= s.length(); i++) {
            for (String word : dict) {
                if (word.length() <= i && f[i - word.length()] && s.startsWith(word, i - word.length())) {
                    f[i] = true;
                    break;
                }
            }
        }
        return f[s.length()];
    }
