// A stack tracks the currently running function while timestamps give each call's exclusive duration.
public class Main {
    public static void main(String[] args)throws Exception{
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        int n=Integer.parseInt(br.readLine().trim()),m=Integer.parseInt(br.readLine().trim());
        int[] ans=new int[n];
        Deque<Integer> st=new ArrayDeque<>();
        int prev=0;
        for(int k=0;k<m;k++){
            String log=br.readLine().trim();
            String[] p=log.split(":");
            int id=Integer.parseInt(p[0]),time=Integer.parseInt(p[2]);
            if(p[1].equals("start")){
                if(!st.isEmpty())ans[st.peek()]+=time-prev;
                st.push(id);
                prev=time;
            }
            else{
                ans[st.pop()]+=time-prev+1;
                prev=time+1;
            }
        }
        for(int i=0;i<n;i++){
            if(i>0)System.out.print(" ");
            System.out.print(ans[i]);
        }
        System.out.println();
    }
}

import java.util.*;

public class Main {
    public static int[] exclusiveTime(int n, List<String> logs) {
        int[] res = new int[n];
        Stack<Integer> stack = new Stack<>();
        int prevTime = 0;

        for (String log : logs) {
            String[] parts = log.split(":");
            int id = Integer.parseInt(parts[0]);
            int time = Integer.parseInt(parts[2]);

            if (parts[1].equals("start")) {
                if (!stack.isEmpty()) {
                    res[stack.peek()] += time - prevTime;
                }
                stack.push(id);
            } else {
                res[stack.pop()] += time - prevTime + 1;
            }
            prevTime = time + 1;
        }
