struct Node {
    int key;
    int val;
    struct Node* prev;
    struct Node* next;
};

struct Node* newNode(int key, int val) {
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node->key = key;
    node->val = val;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

struct LRUCache {
    int capacity;
    struct Node* head;
    struct Node* tail;
    struct Node* dict;
};

struct LRUCache* createLRU(int capacity) {
    struct LRUCache* cache = (struct LRUCache*)malloc(sizeof(struct LRUCache));
    cache->capacity = capacity;
    cache->dict = NULL;
    cache->head = NULL;
    cache->tail = NULL;
    return cache;
}

void put(struct LRUCache* cache, int key, int val) {
    struct Node* node = cache->dict;
    if(node) {
        while(node) {
            if(node->key == key) {
                node->val = val;
                break;
            }
            node = node->next;
        }
    } else {
        struct Node* newNode = newNode(key, val);
        if(cache->head == NULL) {
            cache->head = newNode;
            cache->tail = newNode;
        } else {
            newNode->next = cache->head;
            cache->head->prev = newNode;
            cache->head = newNode;
        }
    }
    cache->dict = cache->dict->next;
}

int get(struct LRUCache* cache, int key) {
    struct Node* node = cache->dict;
    while(node) {
        if(node->key == key) {
            if(node->next) {
                node->next->prev = node->prev;
            } else {
                cache->tail = node->prev;
            }
            if(node->prev) {
                node->prev->next = node->next;
            } else {
                cache->head = node->next;
            }
            node->next = NULL;
            node->prev = NULL;
            node->val = cache->tail->val;
            put(cache, cache->tail->key, cache->tail->val);
            break;
        }
        node = node->next;
    }
    return -1;
}

void printCache(struct LRUCache* cache) {
    struct Node* node = cache->head;
    while(node) {
        printf("%d ", node->val);
        node = node->next;
    }
    printf("\n");
}

int main() {
    int q, capacity, key, val;
    scanf("%d %d", &capacity, &q);
    struct LRUCache* cache = createLRU(capacity);
    for(int i = 0; i < q; i++) {
        scanf("%d %d", &key, &val);
        if(i % 2 == 0) {
            put(cache, key, val);
        } else {
            printf("%d\n", get(cache, key));
        }
        printCache(cache);
    }
    return 0;
}

