void union_op(int v1, int v2, int *parent, int *rank) {
    v1 = find(v1, parent);
    v2 = find(v2, parent);
    if (v1 != v2) {
        if (rank[v1] < rank[v2])
            parent[v1] = v2;
        else {
            parent[v2] = v1;
            if (rank[v1] == rank[v2])
                rank[v1]++;
        }
    }
}

