typedef struct EdgeNode {
    int v;
    struct EdgeNode* next;
} EdgeNode;

void bfs(int src, int n, EdgeNode** adj, int* farthest, int* maxDist) {
    int* dist = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) dist[i] = -1;
    dist[src] = 0;
    int* q = (int*)malloc(n * sizeof(int));
    int head = 0, tail = 0;
    q[tail++] = src;
    *farthest = src;
    *maxDist = 0;

    while (head < tail) {
        int u = q[head++];
        EdgeNode* cur = adj[u];
        while (cur) {
            if (dist[cur->v] == -1) {
                dist[cur->v] = dist[u] + 1;
                q[tail++] = cur->v;
                if (dist[cur->v] > *maxDist) {
                    *maxDist = dist[cur->v];
                    *farthest = cur->v;
                }
            }
            cur = cur->next;
        }
    }
    free(dist);
    free(q);
}

