function dfs(u, p) {
  let max1 = 0;
  let max2 = 0;
  let heights = new Array(N).fill(0);
  let heights_u = [u, p];
  let indexes = [0, 1];
  for (let i of graph.get(u)) {
    if (i === p) continue;
    let height = dfs(i, u) + 1;
    heights[height]++;
    if (height > max1) {
      [max1, max2] = [height, max1];
    } else if (height > max2) {
      max2 = height;
    }
    heights_u[indexes[0]] = height;
    indexes[1] = indexes[0];
    indexes[0] = i;
  }
  max1 = heights_u[max1];
  max2 = heights_u[max2];
  let diameter = max1 + max2;
  return Math.max(max1, max2) + 1;
}

