struct Node {
  int data;
  struct Node* next;
};

void deleteEveryKthNode(struct Node** head_ref, int k) {
  struct Node* temp = *head_ref;
  struct Node* prev = NULL;
  if(temp != NULL && k == 1) {
    free(temp);
    return;
  }
  while(temp != NULL && k > 1) {
    if(temp->next == NULL)
      return;
    prev = temp;
    temp = temp->next;
    k--;
  }
  if(temp != NULL) {
    prev->next = temp->next;
    free(temp);
    deleteEveryKthNode(head_ref, k);
  }
}

void push(struct Node** head_ref, int new_data) {
  struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
  new_node->data  = new_data;
  new_node->next = (*head_ref);
  (*head_ref) = new_node;
}

void printList(struct Node* n) {
  while(n != NULL) {
    printf("%d->", n->data);
    n = n->next;
  }
  printf("NULL\n");
}

