ListNode* deleteEveryKthNode(ListNode* head, int k) {
    ListNode dummy(0);
    dummy.next = head;
    ListNode* prev = &dummy;
    ListNode* curr = head;

    while(curr) {
        prev->next = curr->next;
        delete curr;
        curr = prev->next;
        k--;
        if(k==0) {
            k = -1;
        }
    }

    return dummy.next;
}

