struct Node* addTwoLists(struct Node* first, struct Node* second) {
    struct Node* result = NULL;
    if (first == NULL)
        return (second);
    else if (second == NULL)
        return (first);
    if (first->data < second->data) {
        result = first;
        result->next = addTwoLists(first->next, second);
    }
    else {
        result = second;
        result->next = addTwoLists(first, second->next);
    }
