ListNode* reverseFirstKNodes(ListNode* head, int k) {
    if (head == NULL || k <= 0)
        return head;

    ListNode* dummy = new ListNode(0);
    dummy->next = head;
    ListNode* pre = dummy, *end = dummy;

    while (k-- > 0) {
        if (end->next == NULL)
            return dummy->next;
        end = end->next;
    }

    while (pre != end) {
        ListNode* next = pre->next;
        pre->next = end->next;
        end->next = pre;
        pre = pre->next;
    }

    return dummy->next;
}

