def maxProfit(jobs):
    n = len(jobs)
    profit = [0] * n
    for i in range(n):
        profit[i] = jobs[i][2]

    dp = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        dp[i + 1] = max(dp[i + 1], profit[i])
        if i + 1 < n:
            dp[i] = max(dp[i], profit[i] + dp[i + 2])

    return dp[0], dp[1]

