int egg_drop(int eggs, int floors) {
    if (floors == 0 || eggs == 1)
        return floors;

    int min_attempts = floors;

    for (int i = 1; i <= floors; i++) {
        int temp = egg_drop(eggs - 1, floors - i);
        if (temp + 1 < min_attempts)
            min_attempts = temp + 1;
    }

    return min_attempts;
