struct Node {
    int data;
    struct Node *next;
};

struct Node* removeEveryNthNode(struct Node* head, int N) {
    if (head == NULL || N <= 0) {
        return head;
    }

    struct Node *current = head;
    while (current != NULL) {
        if ((N - 1) % N == 0) {
            struct Node *next = current->next;
            free(current);
            current = next;
        } else {
            current = current->next;
        }
    }

    return head;
}

