struct ListNode {
  int val;
  ListNode *next;
  ListNode(int x) : val(x), next(NULL) {}
};

ListNode* removeNthNode(ListNode* head, int n) {
    ListNode dummy(0);
    dummy.next = head;
    ListNode* p = &dummy;
    ListNode* q = &dummy;
    for (int x = 1; p && x < n; ++x) {
        p = p->next;
    }
    if (!p) {
        return head;
    }
    while (p->next) {
        p = p->next;
        q = q->next;
    }
    p->next = q->next;
    return dummy.next;
}

