function removeEveryNthNode(head, N) {
    let current = head;
    let previous = head;
    let index = 1;
    while (current !== null) {
        if (index % N === 0) {
            if (previous === current) {

                head = head.next;
                if (head !== null) {
                    previous.next = head;
                }
            } else {
                previous.next = current.next;
            }
        }
        previous = current;
        current = current.next;
        index++;
    }
    return head;
}

