public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int target = scanner.nextInt();
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            nums[i] = scanner.nextInt();
        }
        scanner.close();
        Set<List<Integer>> result = new HashSet<>();
        backtrack(nums, target, 0, new ArrayList<>(), result);
        for (List<Integer> list : result) {
            System.out.println(list);
        }
    }

    private static void backtrack(int[] nums, int target, int start, List<Integer> current, Set<List<Integer>> result) {
        if (current.size() > 0 && current.size() + nums.length - start < target) {
            return;
        }
        if (current.size() == target) {
            if (current.stream().mapToInt(Integer::intValue).sum() == target) {
                result.add(new ArrayList<>(current));
            }
            return;
        }
        for (int i = start; i < nums.length; i++) {
            current.add(nums[i]);
            backtrack(nums, target, i + 1, current, result);
            current.remove(current.size() - 1);
        }
    }
}

import java.util.*;

public class Solution {
    private void backtrack(int[] candidates, int target, int idx, List<Integer> cur, List<List<Integer>> res) {
        if (target == 0) {
            res.add(new ArrayList<>(cur));
            return;
        }
        if (target < 0) return;

        for (int i = idx; i < candidates.length; i++) {
            if (i > idx && candidates[i] == candidates[i - 1]) continue;
            cur.add(candidates[i]);
            backtrack(candidates, target - candidates[i], i + 1, cur, res);
            cur.remove(cur.size() - 1);
        }
    }

    public List<List<Integer>> combinationSum2(int[] candidates, int target) {
        Arrays.sort(candidates);
        List<List<Integer>> res = new ArrayList<>();
        backtrack(candidates, target, 0, new ArrayList<>(), res);
        return res;
    }
}

