    var a = dist(p1, p2);
    var b = dist(p2, p3);
    var c = dist(p3, p1);
    var z = (a + b + c) / 2;
    var z_a = z - a;
    var z_b = z - b;
    var z_c = z - c;
    return Math.sqrt(z * z_a * z_b * z_c);
}

function dist(p1, p2) {
    return Math.sqrt(
        Math.pow(p1[0] - p2[0], 2) +
        Math.pow(p1[1] - p2[1], 2)
    );
}

