def high_entropy_passphrases_v1(s):
    """Check whether a sequece is a valid passphrase."""
    mmap = {}
    for word in s.split(' '):
        if word not in mmap:
            mmap[word] = 0
        mmap[word] += 1
        if mmap[word] > 1:
            return False

    return True


def high_entropy_passphrases_v2(s):
    """Check whether a sequece is a valid passphrase."""
    mmap = {}
    for word in s.split(' '):
        k = ''.join(list(sorted(word)))
        if k not in mmap:
            mmap[k] = 0
        mmap[k] += 1
        if mmap[k] > 1:
            return False

    return True


