def sortedMerge(head1, head2):
    if head1 == None:
        return head2
    elif head2 == None:
        return head1

    mergedHead = None
    if head1.data <= head2.data:
        mergedHead = head1
        head1 = head1.next
    else:
        mergedHead = head2
        head2 = head2.next

    mergedTail = mergedHead

    while head1 != None and head2 != None:
