    double v[N];
    memset(v,0,sizeof(v));
    REP(i,m) {
      cin >> faucetx[i] >> faucetv[i];
      REP(j,N) {
        if (wallx[j] < faucetx[i] && faucetx[i] < wallx[j+1]) {
          v[j] += faucetv[i];
          break;
        }
      }
    }
    int l;
    cin >> l;
    double ans[l];
    int anx[l], time[l];
    REP(i,l) {
      cin >> anx[i] >> time[i];
      ans[i] = 50;
    }
    vector<P> V(N);
    REP(i,N) {
      V[i] = (P){i,i+1,0,v[i]};
    }
    double t = 0;
    while(t<1000000) {
      double mi = INF;
      int idx = 0;
      bool right = 0;
      REP(i,V.size()) {
        int a = V[i].a, b = V[i].b;
        double hoge = (wallx[b]-wallx[a])*30*min(wallh[a], wallh[b]);
        if (V[i].v > 0 && mi > (hoge - V[i].w) / V[i].v) {
          mi = (hoge - V[i].w) / V[i].v;
          idx = i;
          if (wallh[a] > wallh[b]) right = 1;
          else right = 0;
        }
      }
      
      REP(i, l) {
        if (t <= time[i] && time[i] < t+mi) {
          FOR(it,V) {
            if (wallx[it->a] < anx[i] && anx[i] < wallx[it->b]) {
              // cout << anx[i] << " " << wallx[it->a] << " ";
              // cout << (it->w + (time[i]-t)*it->v) << endl;
              ans[i] = (it->w + (time[i]-t)*it->v) / ((wallx[it->b]-wallx[it->a])*30);
            }
          }
        }
      }
      
      t += mi;
      REP(i,V.size())
        V[i].w += mi*V[i].v;


      // cout << "t=" << t << endl;
      // FOR(it, V) {
      //   printf("(%d,%d) w=%f, v=%f\n",it->a,it->b,it->w,it->v);
      // }
      
      if (V.size()==1) {
        break;
      }
      if (right) {
        if (abs(V[idx+1].w - (wallx[V[idx+1].b]-wallx[V[idx+1].a]) * 30 * wallh[V[idx+1].a]) < 1e-8) { // Ì
          V[idx+1] = (P){V[idx].a, V[idx+1].b, V[idx].w+V[idx+1].w, V[idx].v+V[idx+1].v};
          V.erase(V.begin() + idx);
        } else {                // ¬o
          V[idx+1].v += V[idx].v;
          V[idx].v = 0;
        }
      } else {
        if (abs(V[idx-1].w - (wallx[V[idx-1].b]-wallx[V[idx-1].a]) * 30 * wallh[V[idx-1].b]) < 1e-8) { // Ì
          V[idx] = (P){V[idx-1].a, V[idx].b, V[idx].w+V[idx-1].w, V[idx].v+V[idx-1].v};
          V.erase(V.begin() + idx-1);
        } else {                // ¬o
          V[idx-1].v += V[idx].v;
          V[idx].v = 0;
        }
      }
    }
    REP(i,l) {
      printf("%.5lf\n", ans[i]);
    }
  }
}

