double euc(double xa, double ya, double xb, double yb) {
	int dx = xb - xa, dy = yb - ya;
	return sqrt(dx*dx + dy*dy);
}

signed main() {
	double xa, xb, xc, ya, yb, yc;
	cin >> xa >> ya >> xb >> yb >> xc >> yc;
	double al = euc(xa, ya, xb, yb), bl = euc(xb, yb, xc, yc), cl = euc(xc, yc, xa, ya);
	double bca = acos((bl*bl + cl*cl - al*al) /( 2 * bl*cl));
	double abc = acos((al*al + bl*bl - cl*cl) / (2 * al*bl));
	double cab = acos((cl*cl + al*al - bl*bl) / (2 * al*cl));
	double lb = 0, ub = 1000000000;
	bca /= 2.0; abc /= 2.0; cab /= 2.0;
	rep(i, 300) {
