def merge_sort(arr):
    if len(arr) == 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right, arr)

def merge(left, right, arr):
    l = r = i = 0

    ll = len(left)
    lr = len(right)

    while l < ll and r < lr :
        if left[l] < right[r]:
            arr[i] = left[l]
            l += 1
        else:
            arr[i] = right[r]
            r += 1
        i += 1

    # poplulating remaining
    while l < ll:
        arr[i] = left[l]
        i += 1
        l += 1

    while r < lr:
        arr[i] = right[r]
        i += 1
        r += 1

    return arr



