// This function associates each piece with 
// a number 
int indexOf(char piece) 
{ 
    if (piece=='P') 
        return 0; 
    if (piece=='N') 
        return 1; 
    if (piece=='B') 
        return 2; 
    if (piece=='R') 
        return 3; 
    if (piece=='Q') 
        return 4; 
    if (piece=='K') 
        return 5; 
    if (piece=='p') 
        return 6; 
    if (piece=='n') 
        return 7; 
    if (piece=='b') 
        return 8; 
    if (piece=='r') 
        return 9; 
    if (piece=='q') 
        return 10; 
    if (piece=='k') 
        return 11; 
    else
        return -1; 
} 

// Initializes the table 
void initTable() 
{ 
    for (int i = 0; i<8; i++) 
      for (int j = 0; j<8; j++) 
        for (int k = 0; k<12; k++) 
          ZobristTable[i][j][k] = randomInt(); 
} 

// Computes the hash value of a given board 
unsigned long long int computeHash(char board[8][9]) 
{ 
    unsigned long long int h = 0; 
    for (int i = 0; i<8; i++) 
    { 
        for (int j = 0; j<8; j++) 
        { 
            if (board[i][j]!='-') 
            { 
                int piece = indexOf(board[i][j]); 
                h ^= ZobristTable[i][j][piece]; 
            } 
        } 
    } 
    return h; 
} 

// Main Function 
int main() 
{ 
    // Uppercase letters are white pieces 
    // Lowercase letters are black pieces 
    char board[8][9] = 
    { 
        "---K----", 
        "-R----Q-", 
        "--------", 
        "-P----p-", 
        "-----p--", 
        "--------", 
        "p---b--q", 
        "----n--k"
    }; 

    initTable(); 

    unsigned long long int hashValue = computeHash(board); 
    printf("The hash value is     : %llu\n", hashValue); 

    //Move the white king to the left 
    char piece = board[0][3]; 

    board[0][3] = '-'; 
    hashValue ^= ZobristTable[0][3][indexOf(piece)]; 

    board[0][2] = piece; 
    hashValue ^= ZobristTable[0][2][indexOf(piece)]; 


    printf("The new hash vlaue is : %llu\n", hashValue); 

    // Undo the white king move 
    piece = board[0][2]; 

    board[0][2] = '-'; 
    hashValue ^= ZobristTable[0][2][indexOf(piece)]; 

    board[0][3] = piece; 
    hashValue ^= ZobristTable[0][3][indexOf(piece)]; 

    printf("The old hash vlaue is : %llu\n", hashValue); 

    return 0; 
}

// 6.3. Write a Program  to convert an infix expression into its equivalent postfix expression using suitable user defined function.
// Input : a+b
// Output: 
// Enter the infix expression 
// a+b
// Equivalent Postfix Expression is:
// ab+

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 100

struct Stack
{
    char items[MAX_SIZE];
    int top;
};

typedef struct Stack Stack;

void initialize(Stack *stack);
int isEmpty(Stack *stack);
void push(Stack *stack, char item);
char pop(Stack *stack);
int isOperator(char ch);
int getPrecedence(char ch);
void infixToPostfix(char infix[], char postfix[]);

int main()
{
    char infix[MAX_SIZE], postfix[MAX_SIZE];

    printf("Enter the infix expression: ");
    scanf("%s", infix);

    infixToPostfix(infix, postfix);

    printf("Equivalent Postfix Expression is: %s\n", postfix);

    return 0;
}

void initialize(Stack *stack)
{
    stack->top = -1;
}

int isEmpty(Stack *stack)
{
    return stack->top == -1;
}

void push(Stack *stack, char item)
{
    if (stack->top == MAX_SIZE - 1)
    {
        printf("Stack Overflow\n");
        exit(1);
    }
    stack->items[++(stack->top)] = item;
}

char pop(Stack *stack)
{
    if (isEmpty(stack))
    {
        printf("Stack Underflow\n");
        exit(1);
    }
    return stack->items[(stack->top)--];
}

int isOperator(char ch)
{
    return (ch == '+' || ch == '-' || ch == '*' || ch == '/');
}

int getPrecedence(char ch)
{
    switch (ch)
    {
    case '+':
    case '-':
        return 1;
    case '*':
    case '/':
        return 2;
    default:
        return 0;
    }
}

void infixToPostfix(char infix[], char postfix[])
{
    Stack stack;
    initialize(&stack);

    int i, j;
    i = j = 0;

    while (infix[i] != '\0')
    {
        if ((infix[i] >= 'a' && infix[i] <= 'z') || (infix[i] >= 'A' && infix[i] <= 'Z'))
        {
            postfix[j++] = infix[i++];
        }
        else if (isOperator(infix[i]))
        {
            while (!isEmpty(&stack) && getPrecedence(stack.items[stack.top]) >= getPrecedence(infix[i]))
            {
                postfix[j++] = pop(&stack);
            }
            push(&stack, infix[i++]);
        }
        else if (infix[i] == '(')
        {
            push(&stack, infix[i++]);
        }
        else if (infix[i] == ')')
        {
            while (!isEmpty(&stack) && stack.items[stack.top] != '(')
            {
                postfix[j++] = pop(&stack);
            }
            if (!isEmpty(&stack) && stack.items[stack.top] == '(')
            {
                pop(&stack);
            }
            i++;
        }
        else
        {
            // Ignore other characters
            i++;
        }
    }

    while (!isEmpty(&stack))
    {
        postfix[j++] = pop(&stack);
    }

    postfix[j] = '\0';
}

