struct node
{
    int data;
    struct node *next;
};

struct node *head = NULL;

void circularInsert()
{
    struct node *new = (struct node *)malloc(sizeof(struct node));
    printf("Enter the data: ");
    scanf("%d", &new->data);
    if (head == NULL)
    {
        head = new;
        new->next = head;
    }
    else
    {
        struct node *temp = head;
        while (temp->next != head)
        {
            temp = temp->next;
        }
        temp->next = new;
        new->next = head;
    }
    printf("Node inserted\n");
}

void circularDelete()
{
    if (head == NULL)
    {
        printf("List is empty\n");
        return;
    }
    int key;
    printf("Enter the element to delete: ");
    scanf("%d", &key);
    struct node *temp = head, *prev = NULL;
    if (temp->data == key)
    {
        if (temp->next == head)
        {
            free(head);
            head = NULL;
        }
        else
        {
            while (temp->next != head)
            {
                temp = temp->next;
            }
            temp->next = head->next;
            free(head);
            head = temp->next;
        }
        printf("Node deleted\n");
        return;
    }
    do
    {
        prev = temp;
        temp = temp->next;
    } while (temp != head && temp->data != key);
    if (temp == head)
    {
        printf("Node not found\n");
        return;
    }
    prev->next = temp->next;
    free(temp);
    printf("Node deleted\n");
}

void circularDisplay()
{
    if (head == NULL)
    {
        printf("List is empty\n");
        return;
    }
    struct node *temp = head;
    do
    {
        printf("%d\t", temp->data);
        temp = temp->next;
    } while (temp != head);
    printf("\n");
}

