#include<bits/stdc++.h>
using namespace std;

const int mod = 1000*1000*1000+7;

int N;
vector<int> A, B, invA, invB;
vector<vector<int> > Rev, Cnt;

int cc[402][402][140][2];
int dp(int a, int b, int n, int t) {
    if(a < 0 && b < 0 && n == N / 3) {
        return 1;
    }
    if(n == N) return 0;
    if(a < 0 || b < 0) return 0;
    int &ret = cc[a][b][n][t];
    if(ret != -1) return ret;

    ret = 0;
    if(t == 0) {
        ret += dp(a, b, n, 1);
        ret %= mod;
        ret += dp(a - 1, b, n, 0);
        ret %= mod;
    }
    if(t == 1) {
        if(Rev[ A[a] ][ B[b] ] && (Cnt[ A[a] ][ B[b] ] - 3*n) > 0) {
            ret += 1LL * (Cnt[ A[a] ][ B[b] ] - 3*n) * dp(a - 1, b - 1, n + 1, 0) % mod;
            ret %= mod;
        }
        ret += dp(a, b - 1, n, 1);
        ret %= mod;
    }
    return ret;
}

int po;

int main() {
