	//char word[10][100]={"apple","code","vinegar"};
	Trie t;
	t.addWord("vinegar");
	t.addWord("vine");
	t.addWord("cinnamon");

	cout<<t.search("vine")<<endl;
	cout<<t.search("ape")<<endl;

}

