class Node {
  constructor(data) {
    this.data = data
    this.next = null
  }
}

class listStack {
  constructor() {
    this.top = null
    this.size = 0
  }

  push(data) {
    const nodeData = new Node(data)
    if (this.top == null) {
      this.top = nodeData
    } else {
      nodeData.next = this.top
      this.top = nodeData
    }
    this.size++
  }

  pop() {
    this.top = this.top.next
  }

  peek() {
    return this.top.data
  }
  print() {
    let curr = this.top
    while (curr) {
      console.log(curr.data);
      curr = curr.next;
    }
  }
}

