            dfs(graph, graph.at(children.at(i)), r, root);
        }
    }
    return;
}

void getRoot(vector<vector<int>> &graph, vector<int> &root) {
    for(int i = 0; i < (int)graph.size(); i++)
    {
        if (root.at(i) == -1) {
            root.at(i) = i;

            for(int j = 0; j < (int)graph.at(i).size(); j++)
            {
                dfs(graph, graph.at(i), i, root);
            }
            
        }
    }
    return;
}

int main() {
    int n,m;
    cin >> n >> m;
    vector<int> p(n);
    for (int i = 0; i < n; i++) cin >> p.at(i);
    
    vector<vector<int>> graph(n, vector<int>(0, 0));
    int x,y;
    for(int i = 0; i < m; i++)
    {
        cin >> x >> y;
        graph.at(min((x - 1), (y - 1))).push_back(max((x - 1), (y - 1)));
        graph.at(max((x - 1), (y - 1))).push_back(min((x - 1), (y - 1)));
    }
    
    vector<int> root(n, -1);
    
    getRoot(graph, root);
    
    int ans = 0;
    for (int i = 0; i < n; i++) {
        if (root.at(i) == root.at(p.at(i) - 1)) ans++;
    }
    
    cout << ans << endl;
}

