void push()
{
    newn = (struct node *)malloc(sizeof(struct node));
    printf("Enter the element : \n");
    scanf("%d",&newn->data);

    if(top==NULL)
        newn -> next = NULL;
    else
        newn -> next = top;
    top = newn;
    printf("Element(%d) pushed in stack successful\n",newn->data);
}

void pop()
{
    x = top;
    if(top==NULL)
        printf("Stack is Underflow. \n");
    else
        top = x -> next;
}

void peek()
{
    x = top;
    printf("Top element is : \t %d \n",top -> data);
}

void search()
{
    int n,k=0;
    x = top;
    printf("Enter the element which you want to search: \n");
    scanf("%d",&n);
    while(x != NULL)
    {
        if(x->data==n)
            k=1;
        x = x -> next;
    }
    (k==1)?printf("Element(%d) found in stack\n",n):printf("Element(%d) is not in stack\n",n);
}

void min()
{
    x = top;
    int temp;
    int k = x -> data;
    while(x !=NULL)
    {
        if(x->data < k)
        {
            temp = x->data;
            x->data = k;
            k = temp;
        }
        x = x -> next;
    }
    printf("Minimum element in stack is : %d\n",k);
}

void max()
{
    x = top;
    int temp;
    int k = x -> data;
    while(x !=NULL)
    {
        if(x->data > k)
        {
            temp = x->data;
            x->data = k;
            k = temp;
        }
        x = x -> next;
    }
    printf("Maximum element in stack is: %d\n",k);
}

void display()
{
    x = top;
    printf("Printing elements of stack: \n");
    while(x != NULL)
    {
        printf("%d\n",x->data);
        x = x -> next;
    }
}

