void dfs1(int v) {
  d[v] = 1;
  for (int i = 0; i < child[v].size(); ++i) {
    int c = child[v][i];
    if (c == p[v]) {
      if (pref[v].size() == 0)
        pref[v].PB(1);
      else
        pref[v].PB(pref[v].back());
    }
    else {
      p[c] = v;
      dfs1(c);
      d[v] = (d[v]*(1+d[c]))%m;
      if (pref[v].size() == 0)
        pref[v].PB(d[v]);
      else
        pref[v].PB((pref[v].back()*(1+d[c]))%m);
    }
  }
  for (int i = child[v].size()-1; i >= 0; --i) {
    int c = child[v][i];
    if (c == p[v]) {
      if (suf[v].size() == 0)
        suf[v].PB(1);
      else
        suf[v].PB(suf[v].back());
    }
    else {
      if (suf[v].size() == 0)
        suf[v].PB((1+d[c])%m);
      else
        suf[v].PB((suf[v].back()*(1+d[c]))%m);
    }
  }
  reverse(suf[v].begin(), suf[v].end());
}

void dfs2(int v) {
  if (v == 1)
    g[v] = 0;
  if (v != 1) {
    int oj = p[v];
    g[v] = 1+g[oj];
    int x1 = 0, x2 = pref[oj].size()-1, x3;
    while (x2-x1 > 1) {
      x3 = (x1+x2)/2;
      if (child[oj][x3] <= v)
        x1 = x3;
      else
        x2 = x3;
    }
    int co = x1;
    if (child[oj][x2] == v)
      co = x2;
    if (co > 0)
      g[v] = (g[v]*pref[oj][co-1])%m;
    if (co+1 < suf[oj].size())
      g[v] = (g[v]*suf[oj][co+1])%m;
  }
  for (int c: child[v])
    if (c != p[v])
      dfs2(c);
}

