/*
 * @desc  : 向某个位置插入一个元素
 * @param : 头指针
   @param : index是位置
   @parma : element是要节点的元素内容
 */
int create_node( link_list node, int index, int element ) {
  if ( index < 1 ) {
    return ERROR;
  } 
  int    counter = 1;
  while ( node && counter < index ) {
    node = node->next;
    counter++;
  } 
  // 判断index位置是否存在或合法
  if ( NULL == node || counter > index ) {
    printf( "位置不存在\n" );
    return ERROR;
  }
  // 此时的ll，就是index位置上的节点了
  // 证明一个指向node的指针类型变量
  // 并为之分配内存
  // 然后往内存中存储数据
  link_list new_node;
  new_node = ( link_list )malloc( sizeof( link_list ) ); 
  new_node->element = element;
  new_node->next    = node->next;
  node->next = new_node;
  // 创建新的节点  
  return TRUE;
}

/*
 * @desc  : 更新某个位置上元素
 */
int update_node( link_list node, int index, int element ) {
  // 位置不能小于第一个吧
  if ( index < 1 ) {
    return ERROR;
  }   
  node = node->next;
  int counter = 1;
  while ( node && counter < index ) {
    node = node->next;
    counter++;  
  } 
  // 位置超过了最后一个了，也就是index位置不存在节点了
  if ( NULL == node ) {
    return ERROR;
  }
  // 执行更新操作
  node->element = element;
  return TRUE;
}

/*
 * @desc  : 读取链表某个位置上的元素
 * @param : index表示位置,自然长度，不是数组那种傻屌似的0表示第一个，1就是第一个
 * @param : ll就是链表的入口节点
 */
int read_node( link_list node, int index ) {
  // 位置不能小于第一个吧
  if ( index < 1 ) {
    return ERROR;
  }   
  node = node->next;
  int counter = 1;
  while ( node && counter < index ) {
    node = node->next;
    counter++;  
  } 
  // 位置超过了最后一个了，也就是index位置不存在节点了
  if ( NULL == node ) {
    return ERROR;
  }
  // 此时的ll表示index位置的节点
  return node->element;
}

int delete_node( link_list node, int index ) {
  // 位置不能小于第一个吧
  if ( index < 1 ) {
    return ERROR;
  }   
  //node = node->next;
  int counter = 1;
  while ( node && counter < index ) {
    node = node->next;
    counter++;  
  } 
  // 位置超过了最后一个了，也就是index位置不存在节点了
  if ( NULL == node ) {
    return ERROR;
  }
  link_list temp = node->next;
  node->next = node->next->next;  
  free( temp );
  return TRUE;   
}

