void scoring(int D, vector<int>& decline, vector<vector<int>>& satis){
    vector<int> schedule(D);
    for (int i = 0; i < D; i++){
        cin>>schedule[i];
        schedule[i]--;
    }
    vector<int> lastHeld(26, 0);
    ll sat = 0;
    for(int d = 1;d <= D;d++){
