	rep(i, n) cin >> h[i];
	int ans = 0;
	while (1) {
		bool elf = false;
		bool flag = false;
		rep(i, n) {
			if (h[i] > 0) {
				flag = true;
				h[i]--;
				elf = true;
			}
			else {
				if (flag) ans++;
				flag = false;
			}
		}
		if (flag) ans++;
		if (!elf) break;
	}
	cout << ans << endl;
	return 0;
}

