int main() {
	ll N, K;
	cin >> N >> K;
	vector<ll> P(N);
	vector<ll> C(N);
	rep(i, N) {
		cin >> P.at(i);
	}
	rep(i, N) {
		cin >> C.at(i);
	}
	ll an = -999999999999;
	rep(i, N) {
		ll kf = i;
		ll koma = P.at(kf);
		ll score = C.at(koma-1);
		ll scm = C.at(koma-1);
		ll kai = 1;
		while (koma != (kf+1)&&kai<K) {
			scm = max(scm, score);
			koma = P.at(koma - 1);
			score+= C.at(koma-1);
			
			kai++;
			scm = max(scm, score);
		}
		an = max(scm, an);
		if (score > 0 && kai < K) {
			score = ((K / kai) - 1) * score;

			kai = ((K / kai) - 1) * kai;
			while (kai < K) {
				scm = max(scm, score);
				score += C.at(koma-1);
				koma = P.at(koma-1);
				kai++;
				scm = max(scm, score);
			}
		}
		an = max(scm, an);
	}
	cout << an << endl;
}

// Given a string containing just the characters '(', ')', '{', '}', '[' and ']', determine if the input string is valid.

// The brackets must close in the correct order, "()" and "()[]{}" are all valid but "(]" and "([)]" are not.

public class ValidParentheses {
    public boolean isValid(String s) {
        if(s.length() % 2 == 1) {
            return false;
        }

        Stack<Character> stack = new Stack<Character>();

        for(int i = 0; i < s.length(); i++) {
            if(s.charAt(i) == '(' || s.charAt(i) == '[' || s.charAt(i) == '{') {
                stack.push(s.charAt(i));
            } else if(s.charAt(i) == ')' && !stack.isEmpty() && stack.peek() == '(') {
                stack.pop();
            } else if(s.charAt(i) == ']' && !stack.isEmpty() && stack.peek() == '[') {
                stack.pop();
            } else if(s.charAt(i) == '}' && !stack.isEmpty() && stack.peek() == '{') {
                stack.pop();
            } else {
                return false;
            }
        }

        return stack.isEmpty();
    }
}

