using namespace std;

/* constant */

const int MAX_N = 100000;

const double INF = 1e70;

/* typedef */

template <typename T>
struct Pt {
  T x, y;

  Pt() {}
  Pt(T _x, T _y) : x(_x), y(_y) {}
  Pt(const Pt& pt) : x(pt.x), y(pt.y) {}

  bool operator==(const Pt pt) const { return x == pt.x && y == pt.y; }
  Pt<T> operator+(const Pt pt) const { return Pt<T>(x + pt.x, y + pt.y); }
  Pt<T> operator-() const { return Pt<T>(-x, -y); }
  Pt<T> operator-(const Pt pt) const { return Pt<T>(x - pt.x, y - pt.y); }
  Pt<T> operator*(T t) const { return Pt<T>(x * t, y * t); }
  Pt<T> operator/(T t) const { return Pt<T>(x / t, y / t); }
  T dot(Pt v) const { return x * v.x + y * v.y; }
  T cross(Pt v) const { return x * v.y - y * v.x; }
  Pt<T> mid(const Pt pt) { return Pt<T>((x + pt.x) / 2, (y + pt.y) / 2); }
  T d2() { return x * x + y * y; }
  double d() { return sqrt(d2()); }

  Pt<T> rot(double th) {
    double c = cos(th), s = sin(th);
    return Pt<T>(c * x - s * y, s * x + c * y);
  }

  bool operator<(const Pt& pt) const {
    return x < pt.x || (x == pt.x && y < pt.y);
  }

  void print(string format) {
    printf(("(" + format + ", " + format + ")\n").c_str(), x, y);
  }
  void print() { print("%.6lf"); }
};

typedef Pt<double> pt;

struct Robot {
  pt p;
  int drc;
  Robot() {}
  Robot(pt _p, int _drc) : p(_p), drc(_drc) {}
  bool operator<(const Robot& r0) const { return p.x < r0.p.x; }
};

typedef set<Robot> srbt;

/* global variables */

int n;
pt v;
double r;
Robot rbts[MAX_N];

/* subroutines */

bool lessy(const Robot& r0, const Robot& r1) { return r0.p.y < r1.p.y; }

/* main */

int main() {
  for (;;) {
    cin >> n;
    if (n == 0) break;

    cin >> v.x >> v.y >> r;

    double th = -atan2(v.y, v.x);
    pt v0 = v.rot(th);
    //v0.print(); printf("th=%.6lf\n", th);

    double rr = r * 2;
    double dvx = v0.x * 2;
    
    for (int i = 0; i < n; i++) {
      pt p;
      cin >> p.x >> p.y >> rbts[i].drc;
      rbts[i].p = p.rot(th);
    }
    sort(rbts, rbts + n, lessy);
    
    double min_t = INF;
    srbt srl, srr;
    
    for (int i0 = 0, i1 = 0; i1 < n; i1++) {
      Robot& r1 = rbts[i1];

      while (i0 < i1 && r1.p.y - rbts[i0].p.y > rr) {
	if (rbts[i0].drc > 0) srl.erase(rbts[i0]);
	else srr.erase(rbts[i0]);
	i0++;
      }
      
      if (r1.drc < 0) {
	if (! srl.empty()) {
	  srbt::iterator rit = srl.lower_bound(r1);
	  if (rit != srl.begin()) {
	    rit--;
	    pt dp = r1.p - rit->p;
	    double t = (dp.x - sqrt(rr * rr - dp.y * dp.y)) / dvx;
	    if (min_t > t) min_t = t;
	  }
	}

	srr.insert(r1);
      }
      else {
	if (! srr.empty()) {
	  srbt::iterator rit = srr.lower_bound(r1);
	  if (rit != srr.end()) {
	    pt dp = rit->p - r1.p;
	    double t = (dp.x - sqrt(rr * rr - dp.y * dp.y)) / dvx;
	    if (min_t > t) min_t = t;
	  }
	}

	srl.insert(r1);
      }
    }

    if (min_t >= INF)
      cout << "SAFE" << endl;
    else 
      printf("%.6lf\n", min_t);
  }

  return 0;
}

class Solution {
	/*
	We use bits to store the keys found till now. We can move to each cell multiple times, with different number of keys available 
	to us at a particular time. Therefore time complexity - O(mn*2^k) as 2^k is the no. of states possible. K is no. of keys represented
	as bits can be 0/1.
	if we find a key and we want to add that information to already found key.
	keys = keys | (1 << (c - 'a'))

	To check if a key is present 
	(keys >> c-'a')&1 == 1

	To check if keys collected till now is all those are present.
	convert decimal representation 'k' to binary by (1 << k) - 1 and compare with keys. 
	*/
	int[][] dirs = new int[][]{{1,0}, {0,-1}, {-1,0}, {0,1}};
	public int shortestPathAllKeys(String[] grid){
		int m = grid.length;
		int n = grid[0].length();
		int startX = -1;
		int startY = -1;
		int k = 0;
		for (int i=0; i<m; i++){
			for (int j=0; j<n; j++) {
				char c = grid[i].charAt(j);
				if (c == '@') {
					startX = i;
					startY = j;
				}
				if (isKey(c)) {
					k++;
				}
			}
		}
        System.out.println(" key " + k);
		Node start = new Node(startX, startY, 0);
		Queue<Node> q = new LinkedList<>();
		q.offer(start);
		Set<String> visited = new HashSet<>();
		visited.add(startX + " " + startY + " " + 0);
		int level = 0;
		while (!q.isEmpty()) {
			int size = q.size();
			for (int i=0; i<size; i++) {
				Node cur = q.poll();
				int res = (1 << k) - 1;
				//System.out.println(res);
				if (cur.keys == (1 << k) - 1) { // for 2 total keys, (1 << 2) - 1 = 4 -1 = 3.
					return level;
				}
				for (int[] d: dirs) {
					int x = cur.i + d[0];
					int y = cur.j + d[1];
					int keys = cur.keys;

					if (!isValid(grid, x, y, m, n)) {
						continue;
					}
					char c = grid[x].charAt(y);
					if (isKey(c)) {
						keys = keys | (1 << (c - 'a')); // for 2 keys, it will look like 11 which is equal to 3.
					}
					if (isLock(c) && (keys >> (c - 'A') & 1) == 0) {
						continue;
					}
					if (visited.add(x + " " + y + " " + keys)) {
						q.offer(new Node(x, y, keys));
					}
				}
			}
			level++;
		}
		return -1;
	}

	public boolean isLock(char c) {
		return c >= 'A' && c <= 'F';
	}

	public boolean isKey(char c) {
		return c >= 'a' && c <= 'f';
	}

	public boolean isValid(String[] grid, int i, int j, int m, int n) {
		return i >= 0 && i < m && j >= 0 && j < n && grid[i].charAt(j) != '#';
	}

	class Node {
		int i, j, keys;
		public Node(int i, int j, int keys) {
			this.i = i;
			this.j = j;
			this.keys = keys;
		}
	}
}

#include <stdio.h>
