function findHighestHills(arr) {
	if (arr.length <= 1) {
		return arr;
	}

	var pivot = parseInt(arr.pop());
	var left = [];
	var right = [];

	while (arr.length) {
		var elem = parseInt(arr.pop());
		if (elem > pivot) {
			left.push(elem);
		} else {
			right.push(elem);
		}
	}

	var sorted = [].concat(findHighestHills(left), pivot, findHighestHills(right));
	return sorted.splice(0, 3);
}

