int hash(int key)
{
	return (key % TSIZE);
}
void insert(struct student rec, struct Node *table[])
{
	int h, key;
	struct Node *temp;

	key = rec.studentId;  

	if(search(key, table)!=-1)
	{
		printf("Duplicate key\n");
		return;
	}

    h = hash(key);		

	temp =(struct Node*) malloc(sizeof(struct Node));
	temp->info = rec;
	temp->link = table[h];
	table[h] = temp;
}

int search(int key, struct Node *table[])
{
    int h = hash(key);				
	struct Node *p = table[h];

	while(p!=NULL)
	{
		if(p->info.studentId == key)
		{
			printf("%d %s \n", p->info.studentId, p->info.studentName);
			return h;
		}
		p = p->link;

	}
	return -1;
}

void displayTable(struct Node *table[])
{
	int i;
	struct Node *p;

	for(i=0; i<TSIZE; i++)
	{
		printf("\n[%d]  ",i);

		if(table[i]!=NULL)
		{
			p=table[i];
			while(p!=NULL)
			{
				printf("%d %s\t", p->info.studentId, p->info.studentName);
				p=p->link;
			}
		}
	}
	printf("\n");
}

void del(int key, struct Node *table[])
{
	int h;
    struct Node *temp, *p;
	h = hash(key);				

	if(table[h]==NULL)
	{
		printf("Key %d not found\n", key);
		return;
	}
	if(table[h]->info.studentId == key)
	{
		temp = table[h];
		table[h] = table[h]->link;  
		free(temp);
		return;
	}
	p = table[h];
	while(p->link != NULL)
	{
		if(p->link->info.studentId == key)   
		{
			temp=p->link;
			p->link=temp->link;
			free(temp);
			return;
		}
		p=p->link;
	}
	printf("Key %d not found\n",key);
}

