			a[i]=b[i]=0;
			while(x+y){//cout<<x<<" "<<y<<" "<<dq<<" "<<st.top()<<endl;
				if(x+y==1){
					if(st.top()>dq){a[dq]=x; b[dq]=y; st.push(dq); break;}
					else{
						if(x==a[dq]&&y==b[dq]){
							st.pop(); a[dq]=b[dq]=0; 
