					}
				}else{
					if(st.top()>dq+lft){a[dq+lft]=b[dq+lft]=1; break;}
					else{
						lft-=st.top()-dq; dq=st.top(); st.pop(); zs.push(dq);
						x=a[dq]; y=b[dq]; swap(a[dq],b[dq]); 
					}
				}
				dq++;
			}
		}
