            message: 'Node inserted successfully',
            head: this.head,
        }
    }

    insertFirst(data) {
        const node = new Node(data);
        if(!this.head) {
            this.insertNodeIfListIsEmpty(node)
        }
        this.head.prev = node;
        node.next = this.head;
        this.head = node;
        this.size++;
        return {
            success: true,
            message: 'Node inserted successfully',
            head: this.head,
        }
    }

    insertNode(data, index=this.size) {
        if(index > this.size) {
            return {
                success: false,
                message: 'Error in inserting Node',
                head: this.head
            };
        }
        if(index === 0) {
            return this.insertFirst(data);
        }
        const node = new Node(data);
        if(!this.head) {
            this.insertNodeIfListIsEmpty(node)
        }
        let current = this.head;
        let start = 0;
        while(current) {
            if(start === index-1) {
                break;
            }
            current = current.next;
            start++;
        }
        node.next = current.next;
        node.prev = current;
        current.next = node;
        if(current.next && current.next.prev) {
            current.next.prev = node;
        }
        this.size++;
        return {
            success: true,
            message: 'Node inserted successfully',
            head: this.head,
        }
    }

    traverse() {
