            current = current.next;
        }
    }

    deleteNode(index = this.size-1) {
        if(index > this.size) {
            return {
                success: false,
                message: 'Error in deleting Node',
                head: this.head
            };
        }

        if(index === 0) {
            this.head = this.head.next;
            if(this.head && this.head.prev) {
                this.head.prev = null;
            }
            this.size--;
            return {
                success: true,
                message: 'Node deleted successfully',
                head: this.head
