package graphs;

import java.util.*;

public class Graph {

	private LinkedList<Integer> adj[];

	public Graph(int v) {
		adj = new LinkedList[v];
		for(int i = 0; i<v; i++) {
			adj[i] = new LinkedList<Integer>();
		}
	}

	public void addEdge(int source, int destination) {
		adj[source].add(destination);
		adj[destination].add(source);
	}

	public int bfs(int source, int destination) {

		boolean vis[] = new boolean[adj.length];
		int parent[] = new int[adj.length];
		Queue<Integer> q = new LinkedList<>();

		q.add(source);
		parent[source] = -1;
		vis[source] = true;

		while(!q.isEmpty()) {
			int cur = q.poll();
			if(cur == destination) break;

			for(int neighbor: adj[cur]) {
				if(!vis[neighbor]) {
					vis[neighbor] = true;
					q.add(neighbor);
					parent[neighbor] = cur;
				}
			}
		}

		int cur = destination;
		int distance = 0;


		while(parent[cur] != -1) {
			System.out.print(cur+" -> ");
			cur = parent[cur];
			distance++;
		}

		return distance;
	}

	private boolean dfsUtil(int source, int destination, boolean vis[]) {
		if(source == destination) return true;

		for(int neighbor: adj[source]) {
			if(!vis[neighbor]) {
				vis[neighbor] = true;
				boolean isConnected = dfsUtil(neighbor, destination, vis);
				if(isConnected) return true;
			}
		}

		return false;
	}

	public boolean dfsStack(int source, int destination) {
		boolean vis[] = new boolean[adj.length];
		vis[source] = true;
		Stack<Integer> stack = new Stack<>();

		stack.push(source);

		while(!stack.isEmpty()) {
			int cur = stack.pop();

			if(cur == destination) return true;

			for(int neighbor: adj[cur]) {
				if(!vis[neighbor]) {
					vis[neighbor] = true;
					stack.push(neighbor);
				}
			}
		}

		return false;
	}

	public boolean dfs(int source, int destination) {
		boolean vis[] = new boolean[adj.length];
		vis[source] = true;

		return dfsUtil(source, destination, vis);
	}


	public static void main(String args[]) {
		Scanner sc = new Scanner(System.in);

		System.out.println("Enter number of vertices and edges");

		int v = sc.nextInt();
		int e = sc.nextInt();

		Graph graph = new Graph(v);
		System.out.println("Enter "+ e +" edges");
		for(int i = 0; i<e; i++) {
			int source = sc.nextInt();
			int destination = sc.nextInt();

			graph.addEdge(source, destination);
		}

		System.out.println("Enter source and destination");

		int source = sc.nextInt();
		int destination = sc.nextInt();

//		int distance = graph.bfs(source, destination);
//		System.out.println("min distance is " + distance);

		System.out.println("possible " + graph.dfsStack(source, destination));

		sc.close();
	}
}

/*          Name : Antuley Aman Siraj.
            Roll No. : 23CO25
            Branch : SE-CO
            Batch : 01

            Aim : Implement algorithm to solve n-Queen problem.

            Theory : The N-Queen Problem is a classic backtracking problem where the goal is to place N queens on an N×N chessboard such that no two queens threaten each other. That means no two queens share the same row, column, or diagonal.

            This problem is often solved using backtracking, a form of recursion that tries to build a solution incrementally and backtracks as soon as it determines that a path won’t lead to a valid solution.

            Algorithm : 
            Start from the first row (row = 0).
            Try placing a queen in each column of the current row.
            For each placement, check if it's safe (no queens in the same column or diagonal).
            If safe, place the queen and move to the next row.
            If all queens are placed, print/store the solution.
            If no valid column is found, backtrack to the previous row.

        
*/ 


#include <stdio.h>
#include <stdlib.h>

int board[20], count;

int isSafe(int row, int col) {
    int i;
    for (i = 1; i < row; i++) {
        if (board[i] == col || abs(board[i] - col) == abs(i - row))
            return 0;
    }
    return 1;
}

void printBoard(int n) {
    int i, j;
    printf("\nSolution %d:\n", ++count);
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n; j++) {
            if (board[i] == j)
                printf("Q ");
            else
                printf(". ");
        }
        printf("\n");
    }
}

void solve(int row, int n) {
    int col;
    for (col = 1; col <= n; col++) {
        if (isSafe(row, col)) {
            board[row] = col;
            if (row == n)
                printBoard(n);
            else
                solve(row + 1, n);
        }
    }
}

int main() {
    int n;
    printf("Enter number of queens: ");
    scanf("%d", &n);

    if (n < 1 || n > 20) {
        printf("Invalid input. Enter a number between 1 and 20.\n");
        return 0;
    }

    count = 0;
    solve(1, n);

    if (count == 0)
        printf("No solutions found.\n");

    return 0;
}

