class Node {
  constructor() {
    this.list = [];
  }
  addEdge(edge) {
    this.list.push(edge);
  }
  isOdd() {
    return !!(this.list.length % 2);
  }
}

class Graph {
  constructor() {
    this.init();
  }
  init() {
    this.map = new Map();
  }
  getNode(source, edge) {
    if (!this.map.has(source)) {
      this.map.set(source, new Node());
    }
    return this.map.get(source);
  }
  addEdge(source, edge) {
    const node = this.getNode(source);
    node.addEdge(edge);
  }
  countOdd() {
    return Array.from(this.map.values()).map(node => node.isOdd() ? 1 : 0).reduce((a, b) => a + b);
  }
  canPatrol() {
    const totalOdd = graph.countOdd();
    if (totalOdd === 0) {
      return true;
    } else if (totalOdd === 1 && (graph.getNode(1).isOdd() || graph.getNode(2).isOdd())) {
      return true;
    } else if (totalOdd === 2 && (graph.getNode(1).isOdd() && graph.getNode(2).isOdd())) {
      return true;
    }
    return false;
  }
}

