struct edge{
	int u;
	int v;
	int w;
};
struct edge e[10];
int n,m;
int f[7]={0},sum=0,count=0;
void quicksort(int left,int right)
{
	int i,j;
	struct edge t;
	if(left>right)
		return;
	
	i=left;
	j=right;
	while(i != j)
	{
		while(e[j].w >= e[left].w && i<j)
			j--;
		while(e[i].w <= e[left].w && i<j)
			i++;
		
		if(i<j)
		{
			t=e[i];
			e[i]=e[j];
			e[j]=t;
		}
	}
	
	t=e[left];
	e[left]=e[i];
	e[i]=t;
	
	quicksort(left,i-1);
	quicksort(i+1,right);
	return;
}

int getf(int v)
{
	if(f[v]==v)
		return v;
	else
	{
		f[v]=getf(f[v]);
		return f[v];
	}
}

int merge(int v,int u)
{
	int t1,t2;
	t1=getf(v);
	t2=getf(u);
	if(t1!=t2)
	{
		f[t2]=t1;
		return 1;
	}
	return 0;
}

int main()
