var SystemOfEquations = (function () {
    function SystemOfEquations(a, b, c, d, e, f) {
        this.a = a;
        this.b = b;
        this.c = c;
        this.d = d;
        this.e = e;
        this.f = f;
    }
    SystemOfEquations.prototype.lcm = function (a, b) {
        var alcm = 1;
        var blcm = 1;
        while (true) {
            if (Math.abs(a * alcm) === Math.abs(b * blcm)) {
                return [alcm, blcm];
            }
            if (Math.abs(a * alcm) > Math.abs(b * blcm)) {
                blcm++;
            } else {
                alcm++;
            }
        }
    };

    SystemOfEquations.prototype.solution = function () {
        var lcms = this.lcm(this.a, this.d);
        var b = this.b * lcms[0];
        var c = this.c * lcms[0];
        var e = this.e * lcms[1];
        var f = this.f * lcms[1];
        var g = b - (e < 0 ? -e : e);
        var h = c - (f < 0 ? -f : f);
        var y = h / g;
        var x = ((this.c - (this.b * y)) / this.a);
        return [x.toFixed(3), y.toFixed(3)];
    };
    return SystemOfEquations;
})();
