typedef struct nodeType{
	char elem;
	struct nodeType *next;
}*nodePtr;

typedef struct{
	nodePtr front, rear;
}Queue;

void initQueue(Queue *Q);
void Display(Queue Q);
void Enqueue(Queue *Q, char x);
void Dequeue(Queue *Q);
