//Structure for storing edge
struct Edge{
int src,dst,weight;
};

//Structure for storing a graph
struct Graph{
	int vertexNum;
	int edgeNum;
	struct Edge* edges;
};

//Constructs a graph with V vertices and E edges
void createGraph(struct Graph* G,int V,int E){
		G->vertexNum = V;
		G->edgeNum = E;
		G->edges = (struct Edge*) malloc(E * sizeof(struct Edge));		
}

//Adds the given edge to the graph 
void addEdge(struct Graph* G, int src, int dst, int weight){
	static int ind;
	struct Edge newEdge;
	newEdge.src = src;
	newEdge.dst = dst;
	newEdge.weight = weight;
	G->edges[ind++]= newEdge;
}


//Utility function to find minimum distance vertex in mdist
int minDistance(int mdist[], int vset[], int V){
	int minVal = INT_MAX, minInd ;
	for(int i=0; i<V;i++)
		if(vset[i] == 0 && mdist[i] < minVal){
		minVal = mdist[i];
		minInd = i;
		}
			
	return minInd;
}

//Utility function to print distances
void print(int dist[], int V){
	printf("\nVertex  Distance\n");
	for(int i = 0; i < V; i++){
		if(dist[i] != INT_MAX)
			printf("%d\t%d\n",i,dist[i]);
		else
			printf("%d\tINF",i);
	}
}

//The main function that finds the shortest path from given source
//to all other vertices using Bellman-Ford.It also detects negative
//weight cycle
void BellmanFord(struct Graph* graph, int src){
	int V = graph->vertexNum;
	int E = graph->edgeNum;
	int dist[V];

	//Initialize distances array as INF for all except source
	//Intialize source as zero
	for(int i=0; i<V; i++)
		dist[i] = INT_MAX;
	dist[src] = 0;

	//Calculate shortest path distance from source to all edges
	//A path can contain maximum (|V|-1) edges
	for(int i=0; i<=V-1; i++)
		for(int j = 0; j<E; j++){
			int u = graph->edges[j].src;
			int v = graph->edges[j].dst;
			int w = graph->edges[j].weight;
			
			if(dist[u]!=INT_MAX && dist[u] + w < dist[v])
				dist[v] = dist[u] + w;
		}
	
	//Iterate inner loop once more to check for negative cycle
	for(int j = 0; j<E; j++){
		int u = graph->edges[j].src;
		int v = graph->edges[j].dst;
		int w = graph->edges[j].weight;
		
		if(dist[u]!=INT_MAX && dist[u] + w < dist[v]){
			printf("Graph contains negative weight cycle. Hence, shortest distance not guaranteed.");
			return;
		}
	}

	print(dist, V);
	
	return;
}



//Driver Function
int main(){
	int V,E,gsrc;
	int src,dst,weight;
	struct Graph G;
	printf("Enter number of vertices: ");
	scanf("%d",&V);
	printf("Enter number of edges: ");
	scanf("%d",&E);
	createGraph(&G,V,E);
	for(int i=0; i<E; i++){
		printf("\nEdge %d \nEnter source: ",i+1);
		scanf("%d",&src);
		printf("Enter destination: ");
		scanf("%d",&dst);
		printf("Enter weight: ");
		scanf("%d",&weight);
		addEdge(&G, src, dst, weight);
	}
	printf("\nEnter source:");
	scanf("%d",&gsrc);
	BellmanFord(&G,gsrc);

	return 0;
}

class Solution {

    /*
    Catch is not to make the 0 that are connected to boundary 0 as X.
    So, we would want to do a BFS on boundary O and check if adjacent cells are O or not.
    */
    public void solve(char[][] board) {
        if (board.length == 0) {
            return;
        }

        boolean[][] visited = new boolean[board.length][board[0].length];
        int[] x = {-1,0,1,0};
        int[] y = {0,1,0,-1};
        Queue<Integer> row = new LinkedList<>();
        Queue<Integer> col = new LinkedList<>();
        for (int i=0; i< board.length; i++) {
            for (int j=0; j< board[0].length; j++){
                if((i == 0 || j == 0 || i == board.length - 1 || j == board[0].length - 1) && (board[i][j] == 'O')) {
                    row.add(i); // push all boundary O so that we can pop and do BFS on it.
                    col.add(j);
                }
            }
        }

        while(!row.isEmpty()) {
            int r = row.poll(); 
            int c = col.poll();


                if ((r >= 0) && (c >= 0) && (r < board.length) && (c < board[0].length) && (board[r][c] == 'O')) { // check if its O or not
                    board[r][c] = 'D'; // if it is mark it as D.
                for (int i=0; i< x.length; i++) {
                   int new_r = r + x[i]; // check for neighbours and put inside queue.
                   int new_c = c + y[i];
                    row.add(new_r);
                    col.add(new_c);                    
                } 
            } // since we don't use board[i][j] anywhere we are not concerned if new_r and new_c are out of bounds or not. we take care of it at the top.


        }


        for (int i=0; i < board.length; i++) {
            for (int j=0; j< board[0].length; j++) { // in the end since we did BFS on boundary O. All the cells connected to those will have turned to D and so we replace D by 0.
                if (board[i][j] == 'O') { // remaining will be interior O which we convert back to X.
                    board[i][j] = 'X';
                } else if (board[i][j] == 'D') {
                    board[i][j] = 'O';
                } else {
                    continue;
                }
            }
        }

    }
}

