node *listMerge(node *ptr1, node *ptr2){
	node *head=NULL,*tail=NULL;
	while(ptr1!=NULL || ptr2!=NULL){
		if(ptr1==NULL){
			tail->next=ptr2;
			break;
		}
		else if(ptr2==NULL){
			tail->next=ptr1;
			break;
		}
		else if(ptr1->data>ptr2->data){
			if(head==NULL){
				head=tail=ptr2;
			}
			else{
				tail->next=ptr2;
				tail=tail->next;
			}
			ptr2=ptr2->next;
			tail->next=NULL;
		}
		else{
			if(head==NULL){
				head=tail=ptr1;
			}
			else{
				tail->next=ptr1;
				tail=tail->next;
			}
			ptr1=ptr1->next;
			tail->next=NULL;
		}
	}
	return head;
}

node *MergeSortLinked(node *ptr){
	if(ptr->next==NULL)
		return ptr;

	node *ptr1=ptr,*ptr2=ptr;

	while(ptr2->next!=NULL && ptr2->next->next!=NULL){
		ptr1=ptr1->next;
		ptr2=ptr2->next->next;
	}
	node *temp=ptr1->next;
	ptr1->next=NULL;
	ptr1=temp;

	ptr=MergeSortLinked(ptr);
	ptr1=MergeSortLinked(ptr1);
	ptr=listMerge(ptr,ptr1);
	return ptr;
}


