#include <complex>
#include <iostream>

#define REP(i,n) for(int i=0; i<(int)(n); i++)

using namespace std;

typedef complex<double> P;

const double PI = 3.1415926535;
P pos[40];
int n, m;
int fst;

double memo[41][41];

inline double outp(const P &a, const P &b){
  return (conj(a)*b).imag();
}

double solve(int p, int rest){
  if(p == n) return 0.0;
  if(rest > n - p) return 0.0;
  if(rest == 0) return 0.0;
  if(memo[p][rest] > -1.0)
    return memo[p][rest];
  double ret = 0.0;

  for(int i = p + 1; i < n; i++){
    double tmp = 0.0;

    if(rest != m - 1){
      P p1 = pos[fst];
      P p2 = pos[p];
      P p3 = pos[i];
      tmp += std::abs(outp(p2 - p1, p3 - p1) / 2.0);
      // printf("tmp: %f\n", tmp);
    }

    ret = max(ret, tmp + solve(i, rest - 1));
  }

  // printf("%d %d %d: %f\n", fst, p, rest, ret);
  return memo[p][rest] = ret;
}

int main(){
  while(scanf("%d%d", &n, &m), n + m){
    REP(i,n){
      double ang;
      scanf("%lf", &ang);
      pos[i] = P(cos(2 * PI * ang), sin(2 * PI * ang));
      // cout << "pos[" << i << "]=" << pos[i] << endl;
    }

    double ans = 0.0;
    REP(i,n){
      REP(j,n) REP(k,m) memo[j][k] = -2.0;
      fst = i;
      ans = max(ans, solve(i, m - 1));
    }

    printf("%.6f\n", ans);
  }
  return 0;
}

