#include<iostream>
#include<algorithm>
#include<vector>
#include<stack>
using namespace std;

int vertex_no(int h, int w, int i, int j, int b) {
	return h * w*b + w * (j - 1) + i;
}
int grid[105][105];

struct edge
{
	int from; int to; long long cost; int rev;
};
int const MAX = 100005;
vector<edge> G[MAX];
long long const INF = 10000000000000016;
int parent[MAX];
int from_edge[MAX];
long long costs[MAX];

bool dfs(int n, int start, int goal, vector<edge>V[], long long &amount) {
	for (int i = 0; i <= n; i++) {
		parent[i] = -1;
	}
	stack<int> s;
	parent[start] = 0;
	costs[start] = INF*5;
	s.push(start);
	while (!s.empty()) {
		int now = s.top();
		s.pop();
		for (int i = 0; i < G[now].size(); i++) {
			edge next_edge = G[now][i];
			int next = next_edge.to;
			if (parent[next] == -1 && next_edge.cost > 0) {
				parent[next] = now;
				from_edge[next] = i;
				costs[next] = min(costs[now], next_edge.cost);
				s.push(next);
			}
		}
	}
	amount = costs[goal];
	return parent[goal] != -1;
}

void max_flow(int n, int start, int goal, vector<edge>V[], long long &flow) {
	long long amount;
	while (dfs(n, start, goal, V, amount)) {
		int now = goal;
		while (now != start) {
			int p = parent[now];
			G[p][from_edge[now]].cost -= amount;
			int r = G[p][from_edge[now]].rev;
			G[now][r].cost += amount;
			now = parent[now];
		}
		flow += amount;
	}
}

