				G[y].push_back({ y,x,0,int(G[x].size() - 1) });
			}
			else {
				int x, y;
				x = vertex_no(h, w, i, j, 0);
				for (int k = 0; k < 4; k++) {
					y = vertex_no(h, w, i + dir_x[k], j + dir_y[k], 1);
					G[x].push_back({ x,y,INF,int(G[y].size()) });
					G[y].push_back({ y,x,0,int(G[x].size() - 1) });
				}
				y = x;
				x = vertex_no(h, w, i, j, 1);
				G[x].push_back({ x,y,1,int(G[y].size()) });
				G[y].push_back({ y,x,0,int(G[x].size() - 1) });
			}
		}
	}
	long long flow = 0;
	max_flow(h*w*2 + 1, start, goal, G, flow);
	std::cout << flow << endl;
}

class Solution {
    public List<Integer> targetIndices(int[] nums, int target) {
        List<Integer> res = new ArrayList<>();

        Arrays.sort(nums);

        int firstPos = firstPosition(nums,target);

        if(firstPos == -1)
            return res;

        int lastPos= lastPosition(nums,target);

        for(int i = firstPos;i<=lastPos;i++)
        {
            res.add(i);
        }
        return res;
    }

   public int firstPosition(int[] nums,int target)
    {

        int start = 0;
        int end = nums.length-1;
        int ansIndex = -1;

        while (start<=end)
        {
            int mid = start + (end-start)/2;

            if(nums[mid]==target) 
            {
                   ansIndex = mid;
                   end = mid-1;
            }


           else if(nums[mid]>target) 
             end = mid-1;

           else
             start = mid+1;

        }
       return ansIndex;
    }

    public int lastPosition(int[] nums,int target)
    {
        int start = 0;
        int end = nums.length-1;
        int ansIndex = -1;

        while (start<=end)
        {
            int mid = start + (end-start)/2;

            if(nums[mid]==target) 
            {
                   ansIndex = mid;
                  start = mid+1;
            }


           else if(nums[mid]>target) 
             end = mid-1;

           else
             start = mid+1;

        }
       return ansIndex;
    }

}

