/**
 * Integer overflow check
 * @param  a [an Integer]
 * @param  b [another Integer]
 * @return   [returns true if a + b causes Integer overflow]
 */
bool integerOverflow( int a, int b)
{
    int c = a + b;
    if ( a > 0 && b > 0 && c < 0 ) {
        return true;
    } else if ( a < 0 && b < 0 && c > 0 ) {
        return true;
    }
    else {
        return false;
    }
}

