class Node {
  constructor(data) {
    this.data = data
    this.next = null
  }
}

class SinglyLinkedList {

  // 0(1) - time | 0(1) - space
  insertAtHead(data) {
    let newNode = new Node(data)
    if (!this.head) {
      this.head = newNode
      return this.head
    }
    let currentHead = this.head
    newNode.next = currentHead
    return newNode
  }

  // 0(n) - time | 0(1) - space
  insertAtTail(data) {
    let newNode = new Node(data)
    if (!this.head) {
      this.head = newNode
      return this.head
    }
    let currentHead = this.head
    while (currentHead.next) {
      currentHead = currentHead.next
    }
    currentHead.next = newNode
    return this.head
  }

  insertAtGivenPos(data, pos) {
    let newNode = new Node(data)
    let count = -1
    let current = this.head

    while (current.next) {
      if (count < pos) {
        let nxt = current.next
        current.next = newNode
        newNode.next = nxt
      } 
        count++
        current = current.next
    }
    return this.head
  }
}

