D ans=INF;


inline D cost(P a){
  for(int i=0;i<N;i++){
    dist[i]=abs(A[i]-a);
  }
  sort(dist.begin(),dist.end(),greater<D>());
  D ret=0;
  for(int i=0;i<K;i++){
    ret+=dist[i];
  }
  //if(ret<ans) cout<<a<<endl;
  chmin(ans,ret);
  return ret;
}

#define F first
#define S second
using pt=pair<D,P>;

const vector<P> V={{1,0},{0,1},{-1,0},{0,-1}};

void cul(P a,int num,D dis){
  //dis=cost(a);

  //cout<<dis<<endl;
  //dis=dis*dis;
  //chmax(dis,1.0);

  for(int i=0;i<num;i++){
    for(int j=0;j<5;j++){
      pt mi={cost(a),a};
      for(auto &v:V){
        D c=cost(a+v*dis);
        if(c<mi.F){
          mi.F=c;
          mi.S=a+v*dis;
        }
      }
      a=mi.S;
    }
    dis/=2.0;
  }
}

