public class rendering_fsql {
    static TreeMap<Integer, stu> students;
    static ArrayList<Integer> stu_list = new ArrayList<>();
    static String[] qu;
    static FileWriter fw;
    static int qu_num = 0;
    static class stu
    {
        String student_name;
        int student_mark;
    }
    public static void solver(String[] queries) throws IOException {
    for (String s:queries)
    {
        if (s == null)
            continue;
        String sp1[] = s.split("::");
        if (sp1[0].equals("ADDROW"))
        {
            String[] params = sp1[1].split(":");
            addrow(Integer.parseInt(params[0]), params[1], Integer.parseInt(params[2]));
   //         System.out.println("NULL");
            fw.write("NULL");
            fw.write('\n');
        }
        else if (sp1[0].equals("REMOVE"))
        {
            removerow(Integer.parseInt(sp1[1]));
    //       System.out.println("NULL");
            fw.write("NULL");
            fw.write('\n');
        }
        else if (sp1[0].equals("QUERY"))
        {
            query(Integer.parseInt(sp1[1]));
            //       System.out.println("NULL");
        }
        else
        {
            // select
            select();
        }
    }
    }
    public static void addrow(int stu_id, String stu_name, int stu_mark)
    {
        stu s = new stu();
        s.student_name = stu_name;
        s.student_mark = stu_mark;
        // make sure no such id exists
        students.putIfAbsent(stu_id, s);
    }
    public static void removerow (int stu_id)
    {
        students.remove(stu_id);
    }
    public static void select () throws IOException {
        for (int stu_ids:students.keySet())
        {
            stu s = students.get(stu_ids);
       //     System.out.println (stu_ids + "  " + s.student_name + "  " + s.student_mark);
            fw.write(stu_ids + "  " + s.student_name + "  " + s.student_mark);
            fw.write('\n');
        }
    }
    public static void query(int stu_id) throws IOException{
        stu s = students.get(stu_id);
        if (s == null)
        {
            // does not exist
            fw.write(Integer.toString(-1));
        }
        else
        {
            fw.write(stu_id + "  " + s.student_name + "  " + s.student_mark);
        }
        fw.write('\n');
    }
