int ans = 0;

void dfs(vector<vector<int>> &v, vector<int> &z, int i, int j, int n) {
  if (i == n - 1) {
    bool flag = true;
    for (int ii = 0; ii < n; ii++) {
      if (z[ii] != n / 2) flag = false;
    }
    if (flag) ans++;
    return;
  }
  if (v[i][j] != -1) {
    if (j < n - 1) j++;
    else {
      i++;
      j = i + 1;
    }
    dfs(v, z, i, j, n);
  }
  else {
    if (z[i] < n / 2) {
      v[i][j] = 1;
      v[j][i] = 0;
      z[i]++;
      int ii = i, jj = j;
      if (j < n - 1) jj++;
      else {
        ii++;
        jj = ii + 1;
      }
      dfs(v, z, ii, jj, n);
      v[i][j] = -1;
      v[j][i] = -1;
      z[i]--;
    }
    if (z[j] < n / 2) {
      v[i][j] = 0;
      v[j][i] = 1;
      z[j]++;
      int ii = i, jj = j;
      if (j < n - 1) jj++;
      else {
        ii++;
        jj = ii + 1;
      }
      dfs(v, z, ii, jj, n);
      v[i][j] = -1;
      v[j][i] = -1;
      z[j]--;
    }
  }
  return;
}

