const ll Mod = int(1e9) + 7;
ll Pow(ll b, ll e){
	if(e<0) e=(-e)*(Mod-2)%(Mod-1);
	ll ret=1;
	while(e){
		if(e&1) (ret*=b)%=Mod;
		(b*=b)%=Mod; e>>=1;
	}
	return ret;
}

int n, m, k;
ll f[51];

ll tot[51];
void Build(){
	for(int i=1; i<=50; ++i) tot[i]=i;
	for(int i=2; i<=50; ++i){
		if(tot[i] == i) for(int j=i; j<=50; j+=i) tot[j]=tot[j]/i*(i-1);
	}
}
ll necklace(ll color, ll length){
	ll s = 0;
	for(ll d=1; d<=length; ++d) if(length%d == 0){
		(s += tot[d] * Pow(color, length/d)) %= Mod;
	}
	return s*Pow(length, -1) % Mod;
}
ll Comb(ll n, ll r){
	ll ja=1, mo=1;
	for(;r;){
		(mo *= r) %= Mod;
		(ja *= n) %= Mod;
		--n; --r;
	}
	return ja*Pow(mo, -1) % Mod;
}
ll H(ll n, ll r){ return Comb(n+r-1, r); }

vector<int> E[101];
