void DFS(int x, int p){
	par[x]=p;
	ind[x] = low[x] = ++nt;
	for(int ei:E[x]){ int y=el[ei]+er[ei]-x;
		if(!ind[y]){
			DFS(y, x);
			low[x]=min(low[x], low[y]);
		} else if(y != p){
			low[x]=min(low[x], ind[y]);
		}
	}
}

vector<int> pc[101];
int cc;
bool os[101];
void Color(int x, int c){
	vis[x]=1; os[x]=1;
	for(int ei:E[x]){ int y=el[ei]+er[ei]-x;
		if(os[y] && y!=par[x]){
			pc[c].pb(ei);
			continue;
		}
		if(vis[y]) continue;
		if(ind[x] <= low[y]){
			pc[++cc].pb(ei);
			Color(y, cc);
		} else {
			pc[c].pb(ei);
			Color(y, c);
		}
	}
	os[x]=0;
}

