		int a, b; read(a, b);
		el[i] = a; er[i] = b;
		E[a].pb(i); E[b].pb(i);
	}
	
	vector<int> dr;
	for(int i=1; i<=n; ++i) if(!ind[i]) dr.pb(i), DFS(i, -1);
	for(int r:dr) Color(r, cc);
	
	ll ans = 1;
	for(int i=1; i<=cc; ++i){
		set<int> Vs;
		for(int ei:pc[i]){
			int a=el[ei], b=er[ei];
			Vs.insert(a);
			Vs.insert(b);
		}
		int V = Vs.size();
		int E = pc[i].size();
		
		//printf("V %d E %d\n", V,E);
		
		if(E == V-1){
			/// tree, in fact V=2 && E=1
			(ans *= k) %= Mod;
		} else if(V == E){
			(ans *= necklace(k, V)) %= Mod;
		} else {
			(ans *= H(k, E)) %= Mod;
		}
	}
	printf("%lld\n", ans);
	return 0;
}

