#include <stdio.h>
#include <stdlib.h>

#define TRUE 1
#define FALSE 0

/**
 * define the struct of list node
 */
typedef struct Node {
    int data;
    struct Node* next;
} Node;

/**
 * init a link list
 * @return the head pointer of link list's head
 */
Node* initList() {
    Node* L = (Node*)malloc(sizeof(Node));
    L->data = 0;
    L->next = L;
    return L;
}

/**
 * insert item in link list's head
 * @param L the head pointer of link list
 * @param data  the data you want to insert
 */
void headInsert(Node* L, int data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->next = L->next;
    L->next = node;
    L->data++;
}

/**
 * insert item in link list's tail
 * @param L the head pointer of link list
 * @param data the data you want to insert
 */
void tailInsert(Node* L, int data) {
    Node* n = L;
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    while (n->next != L) {
        n = n->next;
    }
    node->next = L;
    n->next = node;
    L->data++;
}

/**
 * delete item in link list
 * @param L the head pointer of link list
 * @param data the data you want to delete
 * @return success flag
 */
int delete (Node* L, int data) {
    Node* preNode = L;
    Node* node = L->next;
    while (node != L) {
        if (node->data == data) {
            preNode->next = node->next;
            free(node);
            L->data--;
            return TRUE;
        }
        preNode = node;
        node = node->next;
    }
    return FALSE;
}

/**
 * print all items in a link list
 * @param L the head pointer of link list
 */
void printList(Node* L) {
    Node* node = L->next;
    while (node != L) {
        printf("%d->", node->data);
        node = node->next;
    }
    printf("NULL\n");
}

/**
 * main function
 * @return null
 */
int main() {
    Node* L = initList();
    headInsert(L, 1);
    headInsert(L, 2);
    headInsert(L, 3);
    headInsert(L, 4);
    headInsert(L, 5);
    tailInsert(L, 6);
    tailInsert(L, 7);
    printList(L);
    delete (L, 4);
    delete (L, 7);
    printList(L);
    return 0;
}

/*
Implement Stack using Queues
URL: https://leetcode.com/problems/implement-stack-using-queues/description/

Implement the following operations of a stack using queues.

push(x) -- Push element x onto stack.
pop() -- Removes the element on top of the stack.
top() -- Get the top element.
empty() -- Return whether the stack is empty.
Example:

MyStack stack = new MyStack();

stack.push(1);
stack.push(2);  
stack.top();   // returns 2
stack.pop();   // returns 2
stack.empty(); // returns false
Notes:

You must use only standard operations of a queue -- which means only push to back, peek/pop from front, size, and is empty operations are valid.
Depending on your language, queue may not be supported natively. You may simulate a queue by using a list or deque (double-ended queue), as long as you use only standard operations of a queue.
You may assume that all operations are valid (for example, no pop or top operations will be called on an empty stack).
*/

class MyStack {
  constructor() {
    this.q1 = [];
    this.q2 = [];
  }

  push(elem) {
    if (this.q1.length > 0) {
      this.q1.push(elem);
    } else {
      this.q2.push(elem);
    }
  }

  pop() {
    if (this.q1.length === 0 && this.q2.length === 0) return null;

    if (this.q1.length > 0) {
      var elem;
      while (this.q1.length > 1) {
        elem = this.q1.shift();
        this.q2.push(elem);
      }
      return this.q1.shift();
    } else {
      while (this.q2.length > 1) {
        elem = this.q2.shift();
        this.q1.push(elem);
      }
      return this.q2.shift();
    }
  }

  top() {
    if (this.q1.length === 0 && this.q2.length === 0) return null;
    var elem;
    if (this.q1.length > 0) {
      elem = this.pop();
      this.q2.push(elem);
      return elem;
    } else {
      elem = this.pop();
      this.q1.push(elem);
      return elem;
    }
  }

  empty() {
    return this.q1.length == 0 && this.q2.length === 0;
  }
}

module.exports.MyStack = MyStack;

