using namespace std;
using ll = long long;
//using P = pair<int,int>;
using VI = vector<int>;
using VVI = vector<VI>;

struct P {
    int i;
    int x;
    int y;
    int yrank;};

ll dist(P a, P b) {return abs(a.x - b.x) + abs(a.y - b.y);}

vector<int> ld, lu, rd, ru;
int n;
vector<P> p;
map<tuple<int, int, int>, ll> memo1, memo2;
ll f2(int i, int L, int R, int yl, int yu);

ll f1(int i, int L, int R, int yl, int yu) {
    if (memo1.count({i, L, R}) > 0) return memo1[{i, L, R}];
    // [L, R] * [yl, yu] is available
    bool ok_l = L-1 >= 0 && p[L-1].yrank == yl - 1, 
         ok_r = R+1 < n && p[R+1].yrank == yu + 1;
    ll ret;
    if (!ok_l && !ok_r) {
        ret = f2(i, L, R, yl, yu);
    } else if (!ok_r) {
        int nl = ld[L-1];
        ret = dist(p[i], p[nl]) - (L - nl) + f2(nl, nl, R, p[nl].yrank, yu);
    } else if (!ok_l) {
        int nr = ru[R+1];
        ret = dist(p[i], p[nr]) - (nr - R) + f2(nr, L, nr, yl, p[nr].yrank);
    } else {
        int nl = ld[L-1];
        int nr = ru[R+1];
        ret = min(dist(p[i], p[nr]) + dist(p[nr], p[nl]) - (L - nl + nr - R) + f2(nl, nl, nr, p[nl].yrank, p[nr].yrank),
                  dist(p[i], p[nl]) + dist(p[nl], p[nr]) - (L - nl + nr - R) + f2(nr, nl, nr, p[nl].yrank, p[nr].yrank));
    }
    return memo1[{i, L, R}] = ret;
}

ll f2(int i, int L, int R, int yl, int yu) {
    if (memo2.count({i, L, R}) > 0) return memo2[{i, L, R}];
    // [L, R] * [yl, yu] is available
    bool ok_l = L-1 >= 0 && p[L-1].yrank == yu + 1, 
         ok_r = R+1 < n && p[R+1].yrank == yl - 1;
    ll ret;
    if (!ok_l && !ok_r) {
        ret = 0;
    } else if (!ok_r) {
        int nl = lu[L-1];
        ret = dist(p[i], p[nl]) - (L - nl) + f1(nl, nl, R, yl, p[nl].yrank);
    } else if (!ok_l) {
        int nr = rd[R+1];
        ret = dist(p[i], p[nr]) - (nr - R) + f1(nr, L, nr, p[nr].yrank, yu);
    } else {
        int nl = lu[L-1];
        int nr = rd[R+1];
        ret = min(dist(p[i], p[nr]) + dist(p[nr], p[nl]) - (L - nl + nr - R) + f1(nl, nl, nr, p[nr].yrank, p[nl].yrank),
                  dist(p[i], p[nl]) + dist(p[nl], p[nr]) - (L - nl + nr - R) + f1(nr, nl, nr, p[nr].yrank, p[nl].yrank));
    }
    return memo2[{i, L, R}] = ret;
}


