#include <stdio.h>
int binarySearch(int arr[], int u, int d, int x)
{
	if (d >= u) {
		int mid = u + (d - u) / 2;
		if (arr[mid] == x)
			return mid;
		if (arr[mid] > x){
		    return binarySearch(arr, u, mid - 1, x);
		}
		return binarySearch(arr, mid + 1, d, x);
	}
	return -1;
}
