		for (int diff = -2; diff <= 2; ++diff) {
			int low = 0, high = 1;
			if (s[i] == '0') high = 0;
			else if (s[i] == '1') low = 1;

			for (int last0 = 0; last0 <= 2; ++last0) {
				if (!dp[i - 1][diff + 2][last0]) continue;
				for (int nxt = low; nxt <= high; ++nxt) {
					int ndiff = diff + (nxt == 0 ? -1 : +1);

					int nlast0;
					if (last0 == 0 || last0 == 1) {
						if (nxt == 0) nlast0 = last0 + 1;
						else nlast0 = 0;
					} else if (last0 == 2) {
						if (nxt == 1) nlast0 = 1;
						else nlast0 = 1, ndiff += 2;
					}

					if (diff == 2) ndiff = 2;

					add(dp[i][ndiff + 2][nlast0], dp[i - 1][diff + 2][last0]);
				}
			}
		}
	}

	int res = 0;
	for (int diff = 1; diff <= 2; ++diff) {
		for (int last0 = 0; last0 <= 2; ++last0) {
			add(res, dp[n][diff + 2][last0]);
		}
	}

