void solve(){
    ll m = 1e16;
    ll height = A[0];
  
    for (int b = 0; b < (1 << N); b++)
    {
        height = A[0];
        ll cost = 0;
        bitset<20> bs(b);
        int cnt = 0;
        vector<int> v;

        for (int i = 0; i < N; i++){
            if(bs.test(i)){
                cnt++;
                v.push_back(i);
            }
        }

        if(cnt == K && bs.test(0)){
            for (int i = 1; i < N; i++){
                if(bs.test(i)){
                    cost += max(height - A[i] + 1, (ll)0);
                    height = max(height + 1, A[i]);
                   
                }
                else{
                    height = max(height, A[i]);
                }

                
            }
            m = min(m, cost);
        }
    }
    
