class Solution {
    public int jump(int[] nums) {
        int start = 0; 
        int end = 0;
        int count = 0;

        while (end < nums.length - 1) {

            int maxReach = 0;
            for (int i = start; i <= end; i++) {
                maxReach = Math.max(maxReach , i + nums[i]) ;
            }

            start = end + 1;
            end = maxReach;
            count++;
        }

        return count;
    }
}

class Solution {
    public int search(int[] nums, int target) {

        int start = 0;
        int end = nums.length-1;

        while (start<=end)
        {
            int mid = start + (end-start)/2;
            if(nums[mid]==target) 
                return mid;

           if(nums[mid]<target) 
             end = mid-1;

           else
             start = mid+1;

        }
       return -1;
    }
}

