using namespace std;

int row, col;

int rowPath[] = {-1, 0, 0, 1};

int colPath[] = {0, -1, 1, 0};

bool isPath(int i, int j) {
    if(i < 0)
        return false;
    if(j < 0)
        return false;
    if(i >= row)
        return false;
    if(j >= col)
        return false;
    return true;
}

void dfs(const vector< vector<int> >& mat, int i, int j, vector< vector<bool> >& visited) {
    visited[i][j] = true;
    for(int k = 0; k < 4; k++) {
        int x = i + rowPath[k];
        int y = j + colPath[k];
        if(isPath(x, y) && mat[x][y] && !visited[x][y]) {
            dfs(mat, i+rowPath[k], j+colPath[k], visited);
        }
    }
}

int main() {
    cout << "\nEnter row: ";
    cin >> row;
    cout << "\nEnter column: ";
    cin >> col;
    vector< vector<int> > mat(row, vector<int> (col, 0));
    vector< vector<bool> > visited(row, vector<bool> (col, false));
    string temp;
    cout << "\nEnter map: ";
    for(int i = 0; i < row; i++) {
        cin >> temp;
        for(int j = 0; j < col; j++) {
            mat[i][j] = temp[j] - '0';
            visited[i][j] = false;
        }
    }
    int count = 0;
    for(int i = 0; i < row; i++) {
        for(int j = 0; j < col; j++) {
            if(!visited[i][j] && mat[i][j]) {
                dfs(mat, i, j, visited);
                count++;   
            }
        }
    }
    cout << "\nThere are " << count << " islands in the map";
    return 0;
}

// A Doubly Linked List (DLL) contains an extra pointer, typically called previous pointer, 
// together with next pointer and data which are there in singly linked list.


// Class for Doubly Linked List 
public class DLL { 
    Node head; // head of list   
    /* Doubly Linked list Node*/
    class Node { 
        int data; 
        Node prev; 
        Node next;   
        // Constructor to create a new node 
        // next and prev is by default initialized as null 
        Node(int d) { data = d; } 
    } 
    // Adding a node at the front of the list 
    public void push(int new_data) { 
        /* 1. allocate node  
        * 2. put in the data */
        Node new_Node = new Node(new_data);   
        /* 3. Make next of new node as head and previous as NULL */
        new_Node.next = head; 
        new_Node.prev = null;   
        /* 4. change prev of head node to new node */
        if (head != null) 
            head.prev = new_Node;   
        /* 5. move the head to point to the new node */
        head = new_Node; 
    } 

    /* Given a node as prev_node, insert a new node after the given node */
    public void InsertAfter(Node prev_Node, int new_data) {  
        /*1. check if the given prev_node is NULL */
        if (prev_Node == null) { 
            System.out.println("The given previous node cannot be NULL "); 
            return; 
        }   
        /* 2. allocate node  
        * 3. put in the data */
        Node new_node = new Node(new_data); 

        /* 4. Make next of new node as next of prev_node */
        new_node.next = prev_Node.next; 

        /* 5. Make the next of prev_node as new_node */
        prev_Node.next = new_node; 

        /* 6. Make prev_node as previous of new_node */
        new_node.prev = prev_Node; 

        /* 7. Change previous of new_node's next node */
        if (new_node.next != null) 
            new_node.next.prev = new_node; 
    } 

    // Add a node at the end of the list 
    void append(int new_data) { 
        /* 1. allocate node  
         * 2. put in the data */
        Node new_node = new Node(new_data); 

        Node last = head; /* used in step 5*/

        /* 3. This new node is going to be the last node, so 
         * make next of it as NULL*/
        new_node.next = null; 

        /* 4. If the Linked List is empty, then make the new 
         * node as head */
        if (head == null) { 
            new_node.prev = null; 
            head = new_node; 
            return; 
        } 

        /* 5. Else traverse till the last node */
        while (last.next != null) 
            last = last.next; 

        /* 6. Change the next of last node */
        last.next = new_node; 

        /* 7. Make last node as previous of new node */
        new_node.prev = last; 
    } 

    public void printlist(Node node) { 
        Node last = null; 
        System.out.println("Traversal in forward Direction"); 
        while (node != null) { 
            System.out.print(node.data + " "); 
            last = node; 
            node = node.next; 
        } 
        System.out.println(); 
        System.out.println("Traversal in reverse direction"); 
        while (last != null) { 
            System.out.print(last.data + " "); 
            last = last.prev; 
        } 
    } 

