/* 
 Title: Counting Nodes in Linked List
 Author: Inam Ul Haq

 Description:
    This program demonstrates how to count the number of nodes in a 
    singly linked list. To count the nodes, we traverse the linked list 
    starting from the head node and increment a counter for each node 
    encountered.

    The program performs the following operations:
    1. Creates a linked list by inserting nodes at the beginning.
    2. Accepts user input to populate the list.
    3. Traverses the list to count the total number of nodes.
    4. Displays the total count of nodes.
    5. Frees the allocated memory to avoid memory leaks.

    The traversal continues until the end of the list is reached 
    (i.e., when the next pointer becomes NULL).
*/

#include <stdio.h>
#include <stdlib.h>

struct Node{
	int data;
	struct Node* next;
};

void initNode(struct Node *newNode,int value){
	newNode->data=value;
	newNode->next=NULL;
}

struct Node* insertAtBeginning(struct Node *head,int value){
	struct Node *newNode=malloc(sizeof(struct Node));
	if(!newNode){
		printf("Memory allocation failed.\n");
		exit(1);
	}
	initNode(newNode,value);
	if(head!=NULL)
	newNode->next=head;
	return newNode;
}

int countNodesRec(struct Node *head){
	if(head!=NULL){
		return countNodesRec(head->next)+1;
	}else{
		return 0;
	}
}

void freeNodes(struct Node *head){
	if(head!=NULL){
		freeNodes(head->next);
		free(head);
	}
}
int main(){
	struct Node *head=NULL;
	printf("Enter data for nodes:\n");
	for(int i=0;i<10;i++){
		int value;
		printf("Enter value: ");
		scanf("%d",&value);
		head=insertAtBeginning(head,value);
	}
	int totalNodes=countNodesRec(head);
	printf("Total Nodes: %d\n",totalNodes);
	
	freeNodes(head);
	return 0;
}

/*
 Time Complexity Analysis (Recursive Node Counting):

 Let T(n) be the time taken by the function countNodesRec()
 where n is the number of nodes in the linked list.

 Case 1: head != NULL
     - One constant-time operation is performed.
     - The function makes a recursive call for the next node.
     - Therefore:
         T(n) = T(n - 1) + 1

 Case 2: head == NULL (Base Case)
     - The function returns immediately.
     - Therefore:
         T(0) = 1

 Solving the recurrence relation:
     T(n) = T(n - 1) + 1
     T(n) = T(n - 2) + 2
     ...
     T(n) = T(0) + n
     T(n) = 1 + n

 Ignoring constant terms:
     Time Complexity = O(n)

 Space Complexity Analysis:
     - The function uses recursion.
     - Each recursive call adds one frame to the call stack.
     - For n nodes, there are n recursive calls.

     Space Complexity = O(n)

 Conclusion:
     The recursive method visits each node exactly once.
     Therefore, the time complexity is linear O(n),
     and the auxiliary space complexity is also O(n).
*/

/* FIFO */
#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    int data;
    struct node *next;
} Node;

typedef struct queue {
    Node *front, *rear;
    int size;
} Queue;

Queue *queue_initialise();
Node *create_node(int);
void enqueue(Queue *, int);
int dequeue(Queue *);
int isEmpty(Queue *);
void display(Queue *);
void queue_destroy(Queue *);

int main(int argc, char const *argv[]) {
    int choice, data;
    Queue *queue = queue_initialise();

    do {
        printf("\n\nMAIN MENU\n\n");
        printf("1. Enqueue\n");
        printf("2. Dequeue\n");
        printf("3. Display\n");
        printf("4. Exit\n");

        printf("\nYour choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1: {
                printf("Enter data: ");
                scanf("%d", &data);
                enqueue(queue, data);
                display(queue);
                break;
            }
            case 2: {
                if(!isEmpty(queue)){
                    data = dequeue(queue);
                    printf("Removed: %d\n", data);
                }
                display(queue);
                break;
            }
            case 3: {
                display(queue);
                break;
            }
            case 4: {
                queue_destroy(queue);
                return 0;
            }
        }
    } while (choice);
    queue_destroy(queue);
    return 0;
}

Node* create_node(int data) {
    Node *new_node = (Node*) malloc(sizeof(Node));
    new_node->next = NULL;
    new_node->data = data;
    return new_node;
}

Queue* queue_initialise() {
    Queue* new_queue = (Queue *) malloc(sizeof(Queue));
    new_queue->front = NULL;
    new_queue->rear = NULL;
    new_queue->size = 0;
    return new_queue;
}

int isEmpty(Queue* queue){
    return (queue == NULL || queue->front==-1);
}

void display(Queue *queue) {
    if(isEmpty(queue)){
        printf("Queue is Empty\n");
        return;
    }
    Node *traverse = queue->front;
    while (traverse != NULL) {
        printf("%d->", traverse->data);
        traverse = traverse->next;
    }
    printf("NULL\n");
}

void enqueue(Queue* q, int data) {
    Node* new_node = create_node(data);
    q->size++;
    if (q->front == NULL) {
        q->front = new_node;
        q->rear = new_node;
        return;
    }
    q->rear->next = new_node;
    q->rear = new_node;
}

int dequeue(Queue* q) {
    Node *to_del = q->front;
    int removed = to_del->data;

    q->front = q->front->next;
    free(to_del);

    q->size--;
    return removed;
}

void queue_destroy(Queue *queue) {
    if (isEmpty(queue)) 
        return;

    Node *traverse = queue->front, *to_del = NULL;
    while (traverse->next != NULL) {
        to_del = traverse;
        traverse = traverse->next;
        free(to_del);
    }
    queue->front = NULL;
    queue->rear = NULL;
    free(queue);
}

