/*Function to bubble sort*/
void bubble()
{
	int temp;
	node *t1,*t2;
	t1=head;
	while(t1->next!=NULL)
	{
		t2=head;
		while(t2->next!=NULL)
		{
			if(t2->data > t2->next->data)
			{
				temp=t2->data; 
				t2->data=t2->next->data;
				t2->next->data=temp;
			}
			t2=t2->next;
		}
		t1=t1->next;
	}
}
