{
	int size, i, arr[10];

	printf("\n Enter the size of array : ");
	scanf("%d", &size);

	printf("\n Enter the array elements : ");
	for(i=0; i<size; i++)
	{
		scanf("%d", &arr[i]);
	}
	quickSort(arr, 0, size-1);

	printf("\n After sorting...");
	for (i=0; i<size; ++i)
	{
		printf(" %d ", arr[i]);
	}
	printf("\n");
}

