			day = 'Monday';
			break;
		case 3:
			day = 'Tuesday';
			break;
		case 4:
			day = 'Wednesday';
			break;
		case 5:
			day = 'Thursday';
			break;
		case 6:
			day = 'Friday';
			break;
	}
	return day;
