function calcPrimeNumbers(){
  var max = 999999;
  var primeNumbers = new Int8Array(max);

  // 除外
  primeNumbers[0] = primeNumbers[1] = 1;
  for(var i = 2, maxI = ~~Math.sqrt(max); i <= maxI; i++){
    if(primeNumbers[i]){
      continue;
    }
    
    for(var j = (i<<1); j <= max; j+=i){
      primeNumbers[j] = 1;
    }
  }

  var primeNums = new Int32Array(max);
  var sum = 0;
  for(var i = 1; i <= max; i++){
    primeNums[i] += sum + (1 - primeNumbers[i]);
    sum = primeNums[i];
  }
  
  return primeNums;
}

