void ReadElements(int A[],int S){
    int i,E;
    while (i != S){
        printf("%dth Element :",i);
        scanf("%d",&E);
        A[i] = E;
        i = i + 1;
    }
}

void DisplayArray(int A[],int S){
    int i;
    printf("{");
    while (i != S){
        if(i == S-1){
            printf("%d",A[i]);
        }
        else{
            printf("%d, ",A[i]);
        }
        i = i + 1;
    }
    printf("}");
}

void SelectionSort(int A[],int S){
    int i = 0,j,k;
    int Min;
    while (i != S){
        Min = A[i];
        j = i + 1;
        k = j;
        while (j != S){
            if (Min > A[j]){
                Min = A[j];
                k = j;
            }
            j = j + 1;
        }
        if (A[i] > A[k]){
            Swap(A+i,A+k);
        }
        i = i + 1;
    }
}

void Swap(int *A,int *B){
    *A = *A + *B;
    *B = *A - *B;
    *A = *A - *B;
}

#include <bits/stdc++.h>
#define int long long
using namespace std;
const int N = 5010, M = 210;
int n,m,d[N],val[N][M],ans;
struct node {
  int tag,mx;
  inline void operator += (const int& x) {
    tag += x;
    mx += x;
  }
} t[N << 2];
void push_down(int x) {
  t[x<<1|1] += t[x].tag;
  t[x<<1] += t[x].tag;
  t[x].tag = 0;
}
void push_up(int x) {
  if (t[x].tag) push_down(x);
  t[x].mx = max(t[x<<1].mx,t[x<<1|1].mx);
}
void modify(int l,int r,int v,int x=1,int lp=1,int rp=n) {
  if (l > rp || r < lp) return;
  if (lp >= l && rp <= r)
    return (void) (t[x] += v);
  if (t[x].tag) push_down(x);
  int mid = (lp + rp) >> 1;
  modify(l,r,v,x<<1,lp,mid);
  modify(l,r,v,x<<1|1,mid+1,rp);
  push_up(x);
}
int query(int l,int r,int x=1,int lp=1,int rp=n) {
  if (l > rp || r < lp) return 0;
  if (lp >= l && rp <= r)
    return t[x].mx;
  if (t[x].tag) push_down(x);
  int mid = (lp + rp) >> 1;
  return max(query(l,r,x<<1,lp,mid), query(l,r,x<<1|1,mid+1,rp));
}
struct data {
  int l,r,v;
  bool operator < (const data& x) const {
    return v < x.v;
  }
} sta[M][N];
int top[M];
void solve() {
  data tmp,tp;
  for (int i = 1 ; i <= n ; ++ i) {
    if (i != 1) modify(1,i-1,-d[i]);
    for (int j = 1 ; j <= m ; ++ j) {
      tmp = (data) {i,i,val[i][j]};
      while (top[j] && sta[j][top[j]] < tmp) {
	tp = sta[j][top[j]];
	modify(tp.l,tp.r,-tp.v);
	tmp.l = sta[j][top[j]--].l;
      }
      sta[j][++top[j]] = tmp;
      modify(tmp.l,tmp.r,tmp.v);
    }
    ans = max(ans,query(1,i));
  }
  printf("%lld\n",ans);
}
signed main() {
  scanf("%lld%lld",&n,&m);
  for (int i = 2 ; i <= n ; ++ i)
    scanf("%lld",&d[i]);
  for (int i = 1 ; i <= n ; ++ i)
    for (int j = 1 ; j <= m ; ++ j)
      scanf("%lld",&val[i][j]);
  solve();
  return 0;
}

