void rightRotate(BST *y)
{
	BST x = (*y)->left;
	BST T2 = x->right;
	
	x->right = (*y);
	(*y)->left = T2;
	
	(*y)->height = max(height((*y)->left), height((*y)->right))+1;
	x->height 	 = max(height(x->left), height(x->right))+1;
	

}

void leftRotate(BST *x)
{
	BST y = (*x)->right;
	BST T2 = y->left;
	
	y->left = (*x);
	(*x)->right = T2;
	
	(*x)->height = max(height((*x)->left), height((*x)->right))+1;
	y->height    = max(height(y->left), height(y->right))+1;
    
}

void insert(BST *B, int x)
{
	if((*B)==NULL){
		(*B) = (BST)malloc(sizeof(nodeType));
		(*B)->elem = x;
		(*B)->left = NULL;
		(*B)->right = NULL;
		(*B)->height = 1;
	} 
	if(x < (*B)->elem){
		insert(&(*B)->left, x);
	}else if(x > (*B)->elem){
		insert(&(*B)->right, x);
	}
	

	(*B)->height = 1+max(height((*B)->left), height((*B)->right));
	
	
	int balance =getBalance((*B)) ;
	printf("BALANCE: %d \n",getBalance((*B)));
	
	if(balance > 1 && x < (*B)->left->elem){
		rightRotate(B);
	}
	
	if(balance < -1 && x > (*B)->right->elem){
		leftRotate(B);
	}
	
	if(balance > 1 && x > (*B)->left->elem){
		leftRotate(&(*B)->left);
		rightRotate(B);
	}
	
	if(balance < -1 && x < (*B)->right->elem){
		rightRotate(&(*B)->right);
		leftRotate(B);
	}
	
}

