#define ALL(V) V.begin(),V.end()
template <typename T> using V = vector<T>;

const char base = 'A';

struct Solver {
    ll N;
    V<char> alp;
    V<string> vs;
    V<char> pre_alp;

    Solver() {}

    bool check(map<char, ll> &c2ll) {
        for(char c : pre_alp) if(c2ll[c] == 0) return false;
        return true;
    }

    template <typename T>
    void sort_and_uniq(V<T> &v) {
        sort(ALL(v));
        auto ite = unique(ALL(v));
        v.erase(ite, v.end());
    }

    bool solve() {
        cin >> N;
        if(!N) return false;
        vs.resize(N);
        V<ll> mul(26);
        for(ll i = 0; i < N; i++) {
            cin >> vs[i];
            if(vs[i].size() > 1) pre_alp.push_back(vs[i][0]);
            reverse(ALL(vs[i]));
            ll pow10 = 1;
            for(char c : vs[i]) {
                alp.push_back(c);
                mul[c - base] += (i < N - 1 ? 1 : -1) * pow10;
                pow10 *= 10;
            }
        }

        sort_and_uniq(alp);
        sort_and_uniq(pre_alp);
        V<ll> nlis(10);
        iota(ALL(nlis), 0);
        V<ll> id(26);
        for(ll i = 0; i < alp.size(); i++)  id[alp[i] - base] = i;

        ll ans = 0;

        do {
            bool ok = true;
            for(char c : pre_alp) {
                if(nlis[id[c - base]] == 0) ok = false;
            }
            if(!ok) continue;
            ll sum = 0;
            for(char c : alp) sum += mul[c - base] * nlis[id[c - base]];
            ans += sum == 0;
        } while(next_permutation(ALL(nlis)));

        for(ll i = 1; i <= 10 - alp.size(); i++) ans /= i;
        cout << ans << endl;
        return true;
    }
};

int main() {
    while(Solver().solve());
    return 0;
}

