ll Dp(int st,int cnt,int sum)
{
    if(dp[st][cnt][sum]!=-1)
        return dp[st][cnt][sum];
    dp[st][cnt][sum]=0;
    if(cnt&&(double)sum/cnt==a)
    {
        dp[st][cnt][sum]++;
    }
    for(int i=st;i<n&&(double)(sum+num[i])/(cnt+1)<=a;i++)
    {
        dp[st][cnt][sum]+=Dp(i+1,cnt+1,sum+num[i]);
    }
    return dp[st][cnt][sum];
}

