long long int power(long long int x, long long int n, long long int M) {
	long long int ret = 1;
	long long int by = x;
	while (n) {
		if (n & 1) {
			ret *= by;
			ret %= M;
		}
		by *= by;
		by %= M;
		n >>= 1;
	}
	return ret;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);


	cin >> N;
	int A, B, C;
	cin >> A >> B >> C;
	if (B & 1) {
		cout << 0 << endl;
		return 0;
	}
	B /= 2;
	vector<long long int>by(N + 1, 1);
	vector<long long int>rev(N + 1, 1);
	for (int i = 1; i <= N; i++) {
		by[i] = by[i - 1] * i;
		by[i] %= MOD;
		rev[i] = power(by[i], MOD - 2, MOD);
	}
	long long int ans = by[A + B] * rev[A];
	ans %= MOD;
	ans *= rev[B];
	ans %= MOD;
	//cout << ans << endl;
	long long int ansby = 0;
	for (int i = 0; i <= C; i += 3) {
		for (int j = 0; j <= A; j++) {
			int box = C - i - j;
			if (box < 0)continue;
			if (!B&&box)continue;
			long long int add = 0;
			add = by[A] * rev[j];
			add %= MOD;
			add *= rev[A - j];
			add %= MOD;
			add *= by[A + B + i / 3];
			add %= MOD;
			add *= rev[A + B];
			add %= MOD;
			add *= rev[i / 3];
			add %= MOD;
			if (box) {
				add *= by[B - 1 + box];
				add %= MOD;
				add *= rev[B - 1];
				add %= MOD;
				add *= rev[box];
				add %= MOD;
			}
			ansby += add;
			ansby %= MOD;
		}
	}
	ans *= ansby;
	ans %= MOD;
	cout << ans << endl;
}

