P at(P O,P dir){
	dir=dir.norm();
	double l=::r,r=20000;
	while(r-l>1e-9){
		double mid=(l+r)/2;
		if(in(O+dir*mid))
			l=mid;
		else r=mid;
	}
	return O+dir*l;
}
double calc(P a,P b,P c){
	
	L l1,l2;
	l1.a=(a+b)/2;
	l1.b=l1.a+(b-a).turn90();
	
	l2.a=(b+c)/2;
	l2.b=l2.a+(b-c).turn90();
	
	
	
	
	if(parallel(l1,l2))
		return dis(a,c);
	
	P O=intersect(l1,l2);
	double r=dis(O,a);
	
	
	double theta;
	theta = acos(((c-O)^(a-O))/r/r);
	
	return r*theta;	
}
double calc(double l,double r){
	
	double p=0.45;

	double m=l+(r-l)*p;
	
	P pl=at(O,P(1,0).rot(l));
	P pm=at(O,P(1,0).rot(m));
	P pr=at(O,P(1,0).rot(r));
	
	return calc(pl,pm,pr);
	
}
double simpl(double l,double r){
	double mid=(l+r)/2;
	
	
	double Sl=calc(l,mid);
	double Sr=calc(mid,r);
	double S=calc(l,r);
	
	if(sgn(S-Sl-Sr)==0)
		return S;
	return simpl(l,mid)+simpl(mid,r);
}

