void bsort(int *arr,int *idx,int n)
{
    for(int i=0;i<n;i++)
    {
        for(int j=0;j<n-i-1;j++)
        {
            if(arr[j] > arr[j+1])
            {
                swap(&arr[j],&arr[j+1]);
                swap(&idx[j],&idx[j+1]);
            }
        }
    }
}

