        task: Task,
        callbacks: Optional[Iterable[Callable]] = None,
        force: bool = False,
        wait: bool = False,
        timeout: Union[float, int, None] = None,
        **properties,
    ) -> Submission:
        raise NotImplementedError

    @classmethod
    @abstractmethod
    def cancel_job(cls, job: Job):
        raise NotImplementedError

