void SubsetSum(struct modifiedArray R[], int M,int Sum,int index,int Size){
    if(index == Size){
        if(Sum == M){
            printSubset(R,Size);
        }
        return;
    }
    else{
        if(Sum < M){
            //Including Current Element
            R[index].s = 1;
            SubsetSum(R, M, Sum + R[index].x, index + 1, Size);

            //Excluding Current Element
            R[index].s = 0;
            SubsetSum(R, M, Sum, index+1, Size);

        } else if(Sum > M){
            return;
        } else{
            printSubset(R,Size);
            return;
        }
    }
}

