    for (int i = 0; i < col; i++)
    {
        for (int j = 0; j < row; j++)
        {
            sum[i] += matrix[j][i];
        }
        average[i] = sum[i] / col;
        printf("Col %d : Sum : %f, Average : %f\n", i, sum[i], average[i]);
