	public Process(int priority, int arrivalTime, Burst[] content, int tau) {
		this.priority = priority;
		this.arrivalTime = arrivalTime;
		this.content = content;
		pID = counter++;
		this.tau = tau;

		for (int i = 0; i < content.length; i++) {
			if (content[i].type)
				overallTime += content[i].timeNeeded;
		}
