int find_set(int x,int *parent){
    if(parent[x] == x)
        return x;
    else{
        parent[x] = find_set(parent[x],parent);
        return (parent[x]);
    }
}


void make_union(int x,int y,int *parent,int *rank,int *size){
    
    int temp1 = find_set(x,parent);
    int temp2 = find_set(y,parent);
    
    if(temp1 ==  temp2)
        return;
    
    if(rank[temp1] > rank[temp2]){
        parent[temp2] = temp1;
        size[temp1] += size[temp2];
    }
    else if(rank[temp1] < rank[temp2]){
        parent[temp1] = temp2;
        size[temp2] += size[temp1];
    }
    else{
        parent[temp1] = temp2;
        rank[temp2]++;
        size[temp2] += size[temp1];
    }
    
}




