void quickSort(aluno *v, int p, int r)
{
    int pivot;
    if (p < r)
    {
        pivot = particao(v, p, r);
        quickSort(v, p, pivot - 1);
        quickSort(v, pivot + 1, r);
    }
}

int particao(aluno *v, int p, int r)
{
    int i = p, j = r;
    aluno pivot = v[p], aux;

    while (1)
    {
        while (strcmp(v[i].nome, pivot.nome) <= 0)
        {
            i++;
            if (i == r)
                break;
        }
        while (strcmp(v[j].nome, pivot.nome) > 0)
        {
            j--;
            if (j == p)
                break;
        }

        if (i >= j)
            break;

        aux = v[i];
        v[i] = v[j];
        v[j] = aux;
    }

    aux = v[p];
    v[p] = v[j];
    v[j] = aux;

    return j;
}

