const long long inf = std::numeric_limits<int>::max();
const int maxv = 100005;

vector<vector<long long>> dp;
long long f(int i, int V, const vector<int> &w, const vector<int> &v) {
  if (i == -1 or V <= 0) {
    return V <= 0 ? 0 : inf;
  }

  if (dp[i][V] == -1) {
    long long a = f(i - 1, V, w, v);
    long long b = w[i] + f(i - 1, V - v[i], w, v);
    dp[i][V] = min(a, b);
  }

  return dp[i][V];
}

