#define arr_len(arr) ((int)(sizeof(arr) / sizeof(*arr)))

typedef int element_t;

typedef struct _double_linked_list_node {
    struct _double_linked_list_node *prev;
    struct _double_linked_list_node *next;
    element_t value;
} node_t;

node_t *
reverse_double_linked_list(node_t *head)
{
    node_t *tail = NULL;

    while (NULL != head) {
        tail = head;
        head = head->next;
        tail->next = tail->prev;
        tail->prev = head;
    }

    return tail;
}

void
init_list(node_t **head, int *nums, int num_len)
{
    int i;
    node_t *node, *tmp;

    *head = (node_t *)malloc(sizeof(node_t));
    (*head)->prev = (*head)->next = NULL;
    (*head)->value = nums[0];
    tmp = *head;

    for (i = 1; i < num_len; ++i) {
        node = (node_t *)malloc(sizeof(node_t));
        node->value = nums[i];
        node->next = NULL;
        node->prev = tmp;
        tmp->next = node;
        tmp = tmp->next;
        node = NULL;
    }
}

void
print_list(node_t *head)
{
    while (NULL != head) {
        printf("%d ", head->value);
        head = head->next;
    }
    printf("\n");
}

int
main()
{
    node_t *head = NULL, *new_head = NULL;
    element_t nums[] = {1, 2, 3, 4, 5, 6};

    init_list(&head, nums, arr_len(nums));
    print_list(head);
    new_head = reverse_double_linked_list(head);
    print_list(new_head);

    return 0;
}

/**
 * Given a binary Tree
 * 		    1
 * 		 /     \
 * 	       2	 3
 * 	     /	 \	/ \
 *  	    4	  5    6   7
 *
 *  Find vertical sums of the tree.
 *  Align the nodes in vertical line.
 *  Here
 *  The tree has 5 vertical lines
 *
 *  Vertical-Line-1 has only one node 4 => vertical sum is 4
 *  Vertical-Line-2: has only one node 2=> vertical sum is 2
 *  Vertical-Line-3: has three nodes: 1,5,6 => vertical sum is 1+5+6 = 12
 *  Vertical-Line-4: has only one node 3 => vertical sum is 3
 *  Vertical-Line-5: has only one node 7 => vertical sum is 7
 *
 *  So expected output is 4, 2, 12, 3 and 7
 *
 */

#include <iostream>
#include <unordered_map>
#include <vector>
#include <algorithm>
#include <map>

struct Node {
	int data;
	Node * left;
	Node * right;
	Node ( int d ) : data{ d }, left{ nullptr }, right{ nullptr } { }
};

void vertical_sum_util( Node * root, int dist, std::unordered_map<int,int> & vmap) {
	if ( root == nullptr )  {
		return ;
	}
	if ( vmap.find(dist) != vmap.end() )  {
		vmap[dist] += root->data;
	} else {
		vmap[dist] = root->data;
	}
	vertical_sum_util( root->left, dist-1, vmap);
	vertical_sum_util( root->right, dist+1, vmap);
}

void vertical_sum( Node * root ) {
	if ( root == nullptr )  {
		return;
	}
	std::unordered_map<int, int> vmap;
	vertical_sum_util( root, 0, vmap );
	std::map<int, int> ordered( vmap.begin(), vmap.end());
	std::cout << "Printing vertical sum values, first column represent the position of vertical column with respect to root(0)\n"
			  << "and second column represent vertical sum for that column\n";
	for ( auto it = ordered.begin(); it != ordered.end(); ++it ) {
		std::cout << it->first << "	" << it->second << std::endl;
	}
}

