            String current = a[i];
            if (current.length() == 1) {
                dest += (current.equals("n") ? -10 : 10);
            } else {
                if (dest % 2 != 0) {
                    if (current.equals("ne"))
                        dest -= 9;
                    else if (current.equals("se"))
                        dest += 1;
                    else if (current.equals("nw"))
                        dest -= 11;
                    else
                        dest -= 1;
