        Map<Integer, Set<Integer>> map = new HashMap<>();
        Queue<Integer> queue = new LinkedList<>();
        queue.add(0);
        visited.add(0);
        Map<Integer, Integer> counts = new HashMap<>();
        Map<Integer, Integer> parent = new HashMap<>();
        counts.put(0, 0);
        parent.put(0, 0);
        while (!queue.isEmpty()) {
            Integer current = queue.remove();
