template <typename T, const int MAX_N>
struct BIT {
  int n;
  T bits[MAX_N + 1];
  BIT() {}

  void init(int _n) {
    n = _n;
    //memset(bits, 0, sizeof(bits));
  }

  T sum(int x) {
    T s = 0;
    while (x > 0) {
      s += bits[x];
      x -= (x & -x);
    }
    return s;
  }

  void add(int x, T v) {
    while (x <= n) {
      bits[x] += v;
      x += (x & -x);
    }
  }
};

/* global variables */

pii as[MAX_N];
BIT<int,MAX_N> bit;

/* subroutines */

/* main */

int main() {
  int n;
  scanf("%d", &n);

  for (int i = 0; i < n; i++)
    scanf("%d", &as[i].first), as[i].second = i + 1;
  sort(as, as + n);

  bit.init(n);
  for (int i = 1; i <= n; i++) bit.add(i, 1);

  ll cnt = 0;
  for (int i = 0, m = n; i < n;) {
    int j = i + 1;
    while (j < n && as[i].first == as[j].first) j++;

    int i0 = i, i1 = j - 1;
    while (i0 < i1) {
      int &k0 = as[i0].second, &k1 = as[i1].second;
      int l = bit.sum(k0) - 1, r = m - bit.sum(k1);
      if (l <= r) {
	cnt += l;
	bit.add(k0, -1);
	i0++;
      }
      else {
	cnt += r;
	bit.add(k1, -1);
	i1--;
      }
      m--;
    }

    int &k0 = as[i0].second;
    int s0 = bit.sum(k0);
    int l = s0 - 1, r = m - s0;
    cnt += min(l, r);
    bit.add(k0, -1);
    m--;

    i = j;
  }

  printf("%lld\n", cnt);
  return 0;
}

