//==================================

template <typename _Ty>
class UnionFind {
private:
    vector<_Ty> par;
    vector<_Ty> sz;

public:
    UnionFind(_Ty N) : par(N), sz(N, 1) {
        for (_Ty i = 0; i < N; ++i) par[i] = i;
    }

    _Ty root(_Ty x) {
        return par[x] == x ? x : par[x] = root(par[x]);
    }

    bool same(_Ty x, _Ty y) {
        return root(x) == root(y);
    }

    void unite(_Ty x, _Ty y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (sz[x] < sz[y]) swap(x, y);
        par[y] = x;
        sz[x] += sz[y];
    }

    _Ty size(_Ty x) {
        return sz[root(x)];
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N, M, K;
    cin >> N >> M >> K;
    UnionFind<ll> uf(N);
    Vl indeg(N);
    for (int i = 0; i < M; i++) {
        int a, b;
        cin >> a >> b;
        --a, --b;
        uf.unite(a, b);
        ++indeg[a], ++indeg[b];
    }
    vector<Vl> blocks(N);
    for (int i = 0; i < K; i++) {
        int a, b;
        cin >> a >> b;
        --a, --b;
        blocks[a].push_back(b);
        blocks[b].push_back(a);
    }
    Vl ans(N);
    for (int i = 0; i < N; i++) {
        ans[i] = uf.size(i) - 1 - indeg[i];
        for (const auto& b : blocks[i]) {
            if (uf.same(i, b)) --ans[i];
        }
    }
    for (int i = 0; i < N - 1; i++) {
        cout << ans[i] << " ";
    }
    cout << ans[N - 1] << endl;

    return 0;
}

