void ShowList(struct Node * head)
{
  while(head != NULL)
  {
    printf("%d ", head->data);
    head = head->next;
  }
  printf("\n");
}

struct Node * mergeData(struct Node *first, struct Node *second)
{
  struct Node *last = NULL;
  if(first->data > second->data){
    third = last = second ;
    second = second->next;
    last->next = NULL;
  }
  else{
    third = last = first;
    first = first->next;
    last->next = NULL;
  }
  while(first && second)
  {
    if(first->data > second->data){
      last->next = second;
      last = second;
      second = second->next;
      last->next = NULL;
    }
    else{
      last->next = first;
      last = first;
      first = first->next;
      last->next = NULL;
    }
  }
  if(first)
    last->next = first;
  else
    last->next = second;
  return third;
}

