int dfs(bool isx, int i, int xi)
{
    if (dp[isx][i][xi] >= 0) {
        return dp[isx][i][xi];
    }
    int ret;
    if (i == N - 1)
        ret = abs(a[xi] - a[N - 1]);
    else {
        if (isx) {
            ret = max(dfs(false, i + 1, i), dfs(true, i + 1, xi));
        }
        else {
            ret = min(dfs(true, i + 1, i), dfs(false, i + 1, xi));
        }
    }
    return dp[isx][i][xi] = ret;
}

