#include <bits/stdc++.h>
using namespace std;

const int M = 310;

typedef struct{
    vector<int> x, y;
}Doc;

string P, Q;
int N;
map<string, int> ntoi;
bool matrix[M][M];

int main(){
    for(int i=0; i<M; i++)
        matrix[i][i] = true;
    
    cin >> P >> Q;
    ntoi[P] = 0;
    ntoi[Q] = 1;
    matrix[ntoi[P]][ntoi[Q]] = true;
    
    cin >> N;
    vector<Doc> docs;
    for(int i=0; i<N; i++){
        auto doc = Doc();
        int m; cin >> m;
        for(int i=0; i<m; i++){
            string x, y; cin >> x >> y;
            if(ntoi.find(x) == ntoi.end())
                ntoi[x] = ntoi.size() + 1;
            if(ntoi.find(y) == ntoi.end())
                ntoi[y] = ntoi.size() + 1;
            doc.x.push_back(ntoi[x]);
            doc.y.push_back(ntoi[y]);
        }
        docs.push_back(doc);
    }
    
    vector<bool> done(N);
    bool updated = true;
    while(updated){
        updated = false;
        for(int i=0; i<N; i++) if(!done[i]){
            auto &doc = docs[i];
            
            bool flag = false;
            for(int j=0; j<doc.x.size(); j++){
                if(matrix[doc.x[j]][doc.y[j]]){
                    flag = true;
                    break;
                }
            }
            if(!flag) continue;
            
            for(int j=0; j<doc.x.size(); j++){
                for(int k=0; k<M; k++){
                    if(matrix[k][doc.x[j]])
                        matrix[k][doc.y[j]] = true;
                    if(matrix[doc.y[j]][k])
                        matrix[doc.x[j]][k] = true;
                }
            }
            done[i] = true;
            updated = true;
        }
    }
    
    bool cycle = false;
    for(int i=0; i<M; i++){
        for(int j=0; j<M; j++) if(i != j){
            cycle |= matrix[i][j] && matrix[j][i];
        }
    }
    
    cout << (cycle? "No": "Yes") << endl;
    
    return 0;
}

