function calc(src) {
    src = src.replace(/([-+*\/()=])/g, ' $1 ').split(' ').filter(function(s) {
        return s.trim() !== '';
    });
    return add();

    function add() {
        var
        ret = mul(src);
        while(src[0] in {'+': 1,'-': 1}) {
            switch(src.shift()) {
            case '+':
                ret += mul(src);
                break;
            case '-':
                ret -= mul(src);
                break;
            }
        }
        return ret;
    }

    function mul() {
        var
        ret = prim(src);
        while(src[0] in {'*': 1,'/': 1}) {
            switch(src.shift()) {
            case '*':
                ret *= prim(src);
                break;
            case '/':
                ret = Math.floor(ret / prim(src));
                break;
            }
        }
        return ret;
    }

    function prim() {
        var
        ret, 
        head = src.shift();
        switch(head) {
        case '+':
           return prim(src);
        case '-':
           return -prim(src);
        case '(':
           ret = add(src);
           src.shift();
           return ret;
        default:
           return parseInt(head, 10);
        }
    }
}

