                data.remove(r);
            });
            data.add(r);
            processName.setText("");
            ArrivalTime.setText("");
            BurstTime.setText("");
            TreeItem<RowRecord> root = new RecursiveTreeItem<>(data, RecursiveTreeObject::getChildren);
            Table.setRoot(root);
            Table.setShowRoot(false);
