                    Output fcfs = FirstComeFirstServe.Calc(change(data));
                    AvgWaitingTimeLabel.setText(fcfs.getAvg_waiting() + "");
                    AvgTurnaroundTimeLabel.setText(fcfs.getAvg_turnaround() + "");
