                        break;
                    }
                    Output rr = RoundRobin.Calc(change(data), q);
                    AvgWaitingTimeLabel.setText(rr.getAvg_waiting() + "");
                    AvgTurnaroundTimeLabel.setText(rr.getAvg_turnaround() + "");
                    break;
                default:
                    System.out.println("ERROR");
                    break;
            }
        }

