int comp(const void *a, const void *b)
{
    return *(int *)a - *(int *)b;
}

/* 读入所有输入结点值，并排序 */
void initInputArr(int *arr, int N)
{
    int i;
    for (i = 0; i < N; ++i)
    {
        scanf("%d", &arr[i]);
    }
    qsort(arr, N, sizeof(int), comp);
}

// 不用额外传入数据长度，数据长度存在tree[0]上
void makeCBST(int *tree, int *arr, int pos, int *i)
{
    // 如果树的位置超出了边界或者输入数据已用完，则返回
    if (pos < 1 || pos > tree[0] || (*i) == tree[0]) return;
    else {  // 中序遍历
        makeCBST(tree, arr, pos * 2, i);
        tree[pos] = arr[(*i)++];
        makeCBST(tree, arr, pos * 2 + 1, i);
    }
}

void printCBST(int *tree)
{
    int i;
    for (i = 1; i <= tree[0]; ++i) {
        if (i != 1) printf(" ");
        printf("%d", tree[i]);
    }
}

int main()
{
    int N, pos, i;
    int *arr, *tree;

    scanf("%d", &N);
    arr = (int *)malloc(N * sizeof(int));   // 用来存放输入结点并排序
    tree = (int *)malloc((N + 1) * sizeof(int));    // 存放完全二叉搜索树的所有结点，第一个位置存放结点个数
    tree[0] = N;
    pos = 1, i = 0;

    initInputArr(arr, N);
    makeCBST(tree, arr, pos, &i);
    printCBST(tree);

    free(arr);
    free(tree);

    return 0;
}

#include <stdio.h>
#include <stdlib.h> 

#define SIZE 5

int items[SIZE];
int n = 0;

void swap(int *x, int *y) {
    int temp = *x;
    *x = *y;
    *y = temp;
}

void insert(int data) {
    if(n == SIZE) {
        printf("\nQueue is full");
        return;
    }
    items[n++] = data;
    int child = n - 1;
    int parent = (child - 1) / 2;
    while(parent >= 0 && items[parent] < items[child]) {
        swap(&items[parent], &items[child]);
        child = parent;
        parent = (child - 1) / 2;
    }
}

int delete() {
    if(n == 0) {
        printf("\nQueue is empty");
        return -1;
    }
    int highestPriority = items[0];
    items[0] = items[--n];
    int parent = 0;
    while(1) {
        int leftChild = 2 * parent + 1;
        int rightChild = 2 * parent + 2;
        int largest = parent;
        if(leftChild < n && items[leftChild] > items[largest])
            largest = leftChild;
        if(rightChild < n && items[rightChild] > items[largest])
            largest = rightChild;
        if(largest != parent) {
            swap(&items[parent], &items[largest]);
            parent = largest;
        } else {
            break;
        }
    }
    return highestPriority;
}

int main() {
    insert(3);
    insert(5);
    insert(1);
    insert(2);
    insert(6);

    for(int i = 0; i < SIZE; i++) {
        printf("%d ", delete());
    }

    return 0;
}

package A_Two_Pointers.C_Find_Duplicate;

import java.util.Arrays;

public class A_UsingTwoPointers {

    public int findDuplicate(int[] nums) {
        int duplicateNumber = -1;

        // sorting will take O(nlogn) time complexity
        Arrays.sort(nums);

        int pointerA = 0;
        int pointerB = pointerA + 1;

        for(int i = 0 ;i<nums.length-1;i++){
            if(nums[pointerA] == nums[pointerB]){
                duplicateNumber = nums[pointerA];
            }

            pointerA++;
            pointerB++;
        }

        return duplicateNumber;

    }
}

// Climbing Stairs

#include <stdio.h>

int climbStairs(int n) {
    if (n == 1) return 1;
    if (n == 2) return 2;

    int dp[n + 1];
    dp[1] = 1;
    dp[2] = 2;

    for (int i = 3; i <= n; i++) {
        dp[i] = dp[i - 1] + dp[i - 2];
    }

    return dp[n];
}

int main() {
    int n1 = 2;
    printf("Number of ways to climb %d steps: %d\n", n1, climbStairs(n1)); // Output: 2

    int n2 = 3;
    printf("Number of ways to climb %d steps: %d\n", n2, climbStairs(n2)); // Output: 3

    int n3 = 5;
    printf("Number of ways to climb %d steps: %d\n", n3, climbStairs(n3)); // Output: 8

    return 0;
}

