//Insertion sort algoritam za sortiranje niza
//Slozenost: O(n^2)

inline void insertionSort()
{
    for (int i=1;i<n;i++)
    {
        int j = i - 1;
        int tmp = niz[i];
        while (j >= 0 && niz[j] > tmp) 
        {
          niz[j+1] = niz[j];
          j--;
        }
        niz[j+1] = tmp;
    }
}

