package fdp;

import java.util.concurrent.Callable;

import javax.vecmath.Vector2d;

import org.jgrapht.Graph;

import fdp.graph.Edge;
import fdp.graph.Vertex;
import parsii.eval.Expression;
import parsii.eval.Parser;
import parsii.eval.Scope;
import parsii.eval.Variable;
import parsii.tokenizer.ParseException;

public class Simulation implements Callable<Integer> {

	private Graph<Vertex, Edge> graph;

	private int frameWidth;
	private int frameHeight;
	private boolean equi;
	private double criterion;
	private double coolingRate;
	private int delay;

	private static final double C = 0.4;

	private int iteration = 0;

	private int area;
	private double k;
	private double t;

	private Scope scope = Scope.create();
	private Variable varD = scope.getVariable("d");
	private Variable varK = scope.getVariable("k");
	private Expression attractiveForceExpr;
	private Expression repulsiveForceExpr;

	private boolean equilibriumReached = false;

	/**
	 * Creates a new Simulation.
	 * 
	 * @param graph
	 * @param p
	 * @throws ParseException
	 */
	public Simulation(Graph<Vertex, Edge> graph, Parameter p) throws ParseException {
		this.graph = graph;
		this.frameWidth = p.getFrameWidth();
		this.frameHeight = p.getFrameHeight();
		this.equi = p.isEquilibriumCriterion();
		this.criterion = p.getCriterion();
		this.coolingRate = p.getCoolingRate();
		this.delay = p.getFrameDelay();

		// parse the force strings into Expressions that can be evaluated multiple times
		attractiveForceExpr = Parser.parse(p.getAttractiveForce(), scope);
		repulsiveForceExpr = Parser.parse(p.getRepulsiveForce(), scope);
	}

	/**
	 * Starts the simulation.
	 * 
	 * @return number of iterations used until criterion is met
	 */
	private int startSimulation() {

		iteration = 0;
		equilibriumReached = false;

		area = Math.min(frameWidth * frameWidth, frameHeight * frameHeight);
		k = C * Math.sqrt(area / graph.vertexSet().size());
		t = frameWidth / 10;

		// assign random initial positions to all vertices
		for (Vertex v : graph.vertexSet()) {
			v.randomPos(frameWidth, frameHeight);
		}

		if (equi) {
			// simulate until mechanical equilibrium
			while (!equilibriumReached && iteration < 1000) {
				simulateStep();
			}
		} else {
			// simulate iterations-steps
			for (int i = 0; i < criterion; i++) {
				simulateStep();
			}
		}
		return iteration;
	}

	/**
	 * Simulates a single step.
	 */
	private void simulateStep() {

		// calculate repulsive forces (from every vertex to every other)
		for (Vertex v : graph.vertexSet()) {
			// reset displacement vector for new calculation
			v.getDisp().set(0, 0);
			for (Vertex u : graph.vertexSet()) {
				if (!v.equals(u)) {
					// normalized difference position vector of v and u
					Vector2d deltaPos = new Vector2d();
					deltaPos.sub(v.getPos(), u.getPos());
					double length = deltaPos.length();
					deltaPos.normalize();

					// displacement depending on repulsive force
					deltaPos.scale(this.forceRepulsive(length, k));
					v.getDisp().add(deltaPos);
				}
			}
		}

		// calculate attractive forces (only between neighbors)
		for (Edge e : graph.edgeSet()) {

			// normalized difference position vector of v and u
			Vector2d deltaPos = new Vector2d();
			deltaPos.sub(e.getV().getPos(), e.getU().getPos());
			double length = deltaPos.length();
			deltaPos.normalize();

			// displacements depending on attractive force
			deltaPos.scale(this.forceAttractive(length, k));

			e.getV().getDisp().sub(deltaPos);
			e.getU().getDisp().add(deltaPos);
		}

		// assume equilibrium
		equilibriumReached = true;

		for (Vertex v : graph.vertexSet()) {

			Vector2d disp = new Vector2d(v.getDisp());
			double length = disp.length();

			// no equilibrium if one vertex has too high net force
			if (length > criterion) {
				equilibriumReached = false;
			}
			// System.out.print((int)length + "; ");
			// limit maximum displacement by temperature t
			disp.normalize();
			disp.scale(Math.min(length, t));
			v.getPos().add(disp);

			// prevent being displaced outside the frame
			v.getPos().x = Math.min(frameWidth, Math.max(0.0, v.getPos().x));
			v.getPos().y = Math.min(frameHeight, Math.max(0.0, v.getPos().y));
		}
		// System.out.println();
		// reduce the temperature as the layout approaches a better
		// configuration but always let vertices move at least 1px
		t = Math.max(t * (1 - coolingRate), 1);

		// System.out.println("t: " + (float) t);

		try {
			Thread.sleep(delay);
		} catch (InterruptedException e1) {
			e1.printStackTrace();
		}
		iteration++;
	}

	/**
	 * Calculates the amount of the attractive force between vertices using the
	 * expression entered by the user.
	 * 
	 * @param d
	 *            the distance between the two vertices
	 * @param k
	 * @return amount of force
	 */
	private double forceAttractive(double d, double k) {
		varD.setValue(d);
		varK.setValue(k);
		return attractiveForceExpr.evaluate();
	}

	/**
	 * Calculates the amount of the repulsive force between vertices using the
	 * expression entered by the user.
	 * 
	 * @param d
	 *            the distance between the two vertices
	 * @param k
	 * @return amount of force
	 */
	private double forceRepulsive(double d, double k) {
		varD.setValue(d);
		varK.setValue(k);
		return repulsiveForceExpr.evaluate();
	}

	@Override
	public Integer call() throws Exception {
		return startSimulation();
	}
}

package it.bigdatalab.algorithm;

import it.bigdatalab.applications.CreateSeeds;
import it.bigdatalab.model.GraphMeasureOpt;
import it.bigdatalab.model.Measure;
import it.bigdatalab.utils.Constants;
import it.bigdatalab.utils.Stats;
import it.unimi.dsi.webgraph.ImmutableGraph;
import it.unimi.dsi.webgraph.NodeIterator;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Implementation of MHSE X (MinHash Signature Estimation X version) algorithm
 *
 * @author Giambattista Amati
 * @author Simone Angelini
 * @author Antonio Cruciani
 * @author Daniele Pasquini
 * @author Paola Vocca
 */
public class MHSEX extends MinHash {
    public static final Logger logger = LoggerFactory.getLogger("it.bigdatalab.algorithm.MHSEX");

    private boolean doCentrality;

    /**
     * Creates a new MHSE X instance with default values
     */
    public MHSEX(final ImmutableGraph g, int numSeeds, double threshold, int[] nodes, boolean centrality) throws SeedsException {
        super(g, numSeeds, threshold, nodes);
        doCentrality = centrality;
    }

    /**
     * Creates a new MHSE X instance with default values
     */
    public MHSEX(final ImmutableGraph g, int numSeeds, double threshold, boolean centrality) throws SeedsException {
        super(g, numSeeds, threshold);
        this.mMinHashNodeIDs = CreateSeeds.genNodes(mNumSeeds, mGraph.numNodes());
        doCentrality = centrality;
    }

    public int lengthBitsArray(int value) {
        return (int) Math.ceil(value / (double) Integer.SIZE);
    }

    @Override
    public Measure runAlgorithm() {
        long startTime = System.currentTimeMillis();
        long totalTime;
        long lastLogTime = startTime;
        long logTime;
        long hopStartTime;

        long[] collisionsVector = new long[1];
        int[] position = new int[mNumSeeds];
        int[] remainder = new int[mNumSeeds];

        int[] trackerMutable = new int[lengthBitsArray(mGraph.numNodes())];
        int[] trackerImmutable = new int[lengthBitsArray(mGraph.numNodes())];

        int[][] signMutable = new int[mGraph.numNodes()][lengthBitsArray(mNumSeeds)];
        int[][] signImmutable = new int[mGraph.numNodes()][lengthBitsArray(mNumSeeds)];

        boolean signatureIsChanged = true;
        int h = 0;

        int nPosition, nRemainder, neighPosition, neighRemainder, neighMask;
        while (signatureIsChanged) {
            hopStartTime = System.currentTimeMillis();

            if (h == 0) {
                for (int s = 0; s < mNumSeeds; s++) {
                    position[s] = s >>> Constants.MASK;
                    remainder[s] = (s << Constants.REMAINDER) >>> Constants.REMAINDER;
                    signMutable[mMinHashNodeIDs[s]][position[s]] |= (Constants.BIT) << remainder[s];
                    trackerMutable[mMinHashNodeIDs[s] >>> Constants.MASK] |= (Constants.BIT) << ((mMinHashNodeIDs[s] << Constants.REMAINDER) >>> Constants.REMAINDER);
                }

                signatureIsChanged = true;
            } else {
                signatureIsChanged = false;
                final NodeIterator nodeIterator = mGraph.nodeIterator();

                // update node signature
                for (int n = 0; n < mGraph.numNodes(); n++) {
                    final int node = nodeIterator.nextInt();

                    final int d = nodeIterator.outdegree();
                    final int[] successors = nodeIterator.successorArray();

                    nPosition = node >>> Constants.MASK;
                    nRemainder = (node << Constants.REMAINDER) >>> Constants.REMAINDER;

                    // for each neigh of the node n
                    for (int l = d; l-- != 0; ) {
                        // check if the neigh has been modified
                        // in the previous hop. If true, it can modify
                        // the node n
                        neighPosition = successors[l] >>> Constants.MASK;
                        neighRemainder = (successors[l] << Constants.REMAINDER) >>> Constants.REMAINDER;
                        neighMask = (Constants.BIT << neighRemainder);

                        if (((neighMask & trackerImmutable[neighPosition]) >>> neighRemainder) == 1) {
                            // for each element of the signature of the node n
                            int sMask;
                            for (int s = 0; s < mNumSeeds; s++) {
                                sMask = (Constants.BIT << remainder[s]);

                                // check if the s-th element of the node n signature
                                // it's 0, else jump to the next s-th element of the signature
                                if (((sMask & signMutable[node][position[s]]) >>> remainder[s]) == 0) {
                                    int bitNeigh;
                                    int value;
                                    // change the s-th element of the node n signature
                                    // only if the s-th element of the neigh signature is 1
                                    if (((sMask & signImmutable[successors[l]][position[s]]) >>> remainder[s]) == 1) {
                                        bitNeigh = (((1 << remainder[s]) & signImmutable[successors[l]][position[s]]) >>> remainder[s]) << remainder[s];
                                        value = bitNeigh | sMask & signImmutable[successors[l]][position[s]];
                                        signatureIsChanged = true; // track the signature changes, to run the next hop
                                        trackerMutable[nPosition] |= (Constants.BIT) << nRemainder;
                                        signMutable[node][position[s]] = signMutable[node][position[s]] | value;
                                    }
                                } // else is already 1
                            }
                        }
                    }
                    logTime = System.currentTimeMillis();
                    if (logTime - lastLogTime >= Constants.LOG_INTERVAL) {
                        logger.info("# nodes analyzed {} / {} for hop {} [elapsed {}, node/s {}]",
                                node, mGraph.numNodes(),
                                node,
                                (logTime - hopStartTime) / (double) 1000,
                                ((node + 1) / ((logTime - hopStartTime) / (double) 1000)));
                        lastLogTime = logTime;
                    }
                }
            }
            if (signatureIsChanged) {
                System.arraycopy(trackerMutable, 0, trackerImmutable, 0, trackerMutable.length);
                trackerMutable = new int[lengthBitsArray(mGraph.numNodes())];

                // count the collisions of the signatures
                long collisions = 0;
                for (int r = 0; r < mGraph.numNodes(); r++) {
                    System.arraycopy(signMutable[r], 0, signImmutable[r], 0, signMutable[r].length);
                    for (int c = 0; c < signMutable[r].length; c++) {
                        collisions += Integer.bitCount(signMutable[r][c]);
                    }
                }

                long[] copy = new long[h + 1];
                System.arraycopy(collisionsVector, 0, copy, 0, collisionsVector.length);
                collisionsVector = copy;

                collisionsVector[h] = collisions;
                h += 1;
            }

            logTime = System.currentTimeMillis();
            logger.info("hop # {} completed. Time elapsed to complete computation {} s.",
                    h - 1,
                    (logTime - hopStartTime) / (double) 1000);
        }

        totalTime = System.currentTimeMillis() - startTime;
        logger.info("Algorithm successfully completed. Time elapsed (in milliseconds) {}", totalTime);

        double[] hopTable = hopTable(collisionsVector);

        GraphMeasureOpt graphMeasure = new GraphMeasureOpt();
        graphMeasure.setNumNodes(mGraph.numNodes());
        //graphMeasure.setNumArcs(mGraph.numArcs());
        graphMeasure.setHopTable(hopTable);
        graphMeasure.setLowerBoundDiameter(collisionsVector.length - 1);
        graphMeasure.setThreshold(mThreshold);
        graphMeasure.setSeedsList(mSeeds);
        graphMeasure.setNumSeeds(mNumSeeds);
        graphMeasure.setTime(totalTime);
        graphMeasure.setMinHashNodeIDs(mMinHashNodeIDs);
        graphMeasure.setAvgDistance(Stats.averageDistance(hopTable));
        graphMeasure.setEffectiveDiameter(Stats.effectiveDiameter(hopTable, mThreshold));
        graphMeasure.setTotalCouples(Stats.totalCouplesReachable(hopTable));
        graphMeasure.setTotalCouplesPercentage(Stats.totalCouplesPercentage(hopTable, mThreshold));

        return graphMeasure;
    }

    /***
     * Compute the hop table for reachable pairs within h hops [(CountAllCum[h]*n) / s]
     * @return hop table
     */
    public double[] hopTable(long[] collisionsVector) {
        double[] hopTable = new double[collisionsVector.length];
        for (int i = 0; i < hopTable.length; i++) {
            hopTable[i] = ((double) collisionsVector[i] * mGraph.numNodes()) / this.mNumSeeds;
        }
        return hopTable;
    }
}

