void deletion_last() {
    struct node *ptr;

    // Case 1: List is empty
    if (head == NULL) {
        printf("\nUNDERFLOW - List is empty.\n");
    }
    // Case 2: Only one node in the list
    else if (head->next == NULL) {
        free(head);      // Free the only node
        head = NULL;     // Set head to NULL
        printf("\nNode deleted (only node in the list).\n");
    }
    // Case 3: More than one node
    else {
        ptr = head;

        // Traverse to the last node
        while (ptr->next != NULL) {
            ptr = ptr->next;
        }

        // Remove the last node
        ptr->prev->next = NULL;
        free(ptr);

        printf("\nNode deleted from the end.\n");
    }
}

/*
Merge sort

Worst complexity: O(n log n)
Average complexity: O(n log n)
Best complexity: O(n log n)
Space complexity: O(n)
*/
#include <stdlib.h>
#include <stdio.h>

void merge(int arr[], int start, int middle, int end)
{
    int start1 = start;
    int start2 = middle + 1;
    int startAux = 0;
    int allocSize = end - start + 1;
    int* arrayAux = (int*)malloc(allocSize * sizeof(int));

    while (start1 <= middle && start2 <= end)
    {
        if (arr[start1] < arr[start2])
        {
            arrayAux[startAux] = arr[start1];
            start1++;
        }
        else
        {
            arrayAux[startAux] = arr[start2];
            start2++;
        }
        startAux++;
    }

    while (start1 <= middle)
    {
        arrayAux[startAux] = arr[start1];
        startAux++;
        start1++;
    }

    while (start2 <= end)
    {
        arrayAux[startAux] = arr[start2];
        startAux++;
        start2++;
    }

    for (startAux = start; startAux <= end; startAux++)
    {
        arr[startAux] = arrayAux[startAux - start];
    }

    free(arrayAux);
}

void mergeSort(int arr[], int start, int end)
{
    if (start < end)
    {
        int middle = (end + start) / 2;
        mergeSort(arr, start, middle);
        mergeSort(arr, (middle + 1), end);
        merge(arr, start, middle, end);
    }
}

