bool solve(string S)
{
    reverse(begin(S), end(S));

    const auto N = int(S.size());
    for (auto i = 0; i < N; )
    {
        const auto c = S[i];
        if (c == 'm')
        {
            if (S.substr(i, 5) != "maerd") return false;
            i += 5;
        }
        else if (c == 'e')
        {
            if (S.substr(i, 5) != "esare") return false;
            i += 5;
        }
        else if (c == 'r')
        {
            if (i+2 >= N) return false;
            const auto d = S[i+2];
            if (d == 'm')
            {
                if (S.substr(i, 7) != "remaerd") return false;
                i += 7;
            }
            else if (d == 's')
            {
                if (S.substr(i, 6) != "resare") return false;
                i += 6;
            }
            else return false;
        }
        else return false;
    }

    return true;
}

