using namespace std;

typedef long long ll;

typedef vector<vector<ll>> Mat;

Mat createMat(int N, int A, int B, int C) {
  Mat mat;

  for (int i=0; i<N; i++) {
    mat.push_back(vector<ll>(N));
    if (0 <= i-1) mat[i][i-1] = A;
    mat[i][i] = B;
    if (i+1 < N) mat[i][i+1] = C;
  }

  return mat;
}

Mat mul(Mat &A, Mat &B, int M) {
  int N = A.size();
  Mat res(N, vector<ll>(N));

  for (int i=0; i<N; i++) {
    for (int j=0; j<N; j++) {
      for (int k=0; k<N; k++) {
        res[i][j] += A[i][k] * B[k][j];
        res[i][j] %= M;
      }
    }
  }

  return res;
}

Mat power(Mat &A, int n, int M) {
  Mat res, p = A;

  int N = A.size();
  for (int i=0; i<N; i++) {
    res.push_back(vector<ll>(N));
    res[i][i] = 1;
  }


  while(n) {
    if (n % 2) {
      res = mul(res, p, M);
    }
    p = mul(p, p, M);
    n /= 2;
  }

  return res;
}

int main() {
  int S[100];

  while(1) {
    int N, M, A, B, C, T;

    scanf("%d%d%d%d%d%d", &N, &M, &A, &B, &C, &T);

    if (N == 0) break;

    Mat mat = createMat(N, A, B, C);

    Mat res = power(mat, T, M);

    for (int i=0; i<N; i++) {
      scanf("%d", S+i);
    }

    for (int i=0; i<N; i++) {
      ll ans = 0;

      for (int j=0; j<N; j++) {
        ans += res[i][j] * S[j] % M;
      }

      printf("%lld%c", ans % M, " \n"[i == N-1]);
    }
  }
}

//Given an array of integers and an integer k, find out whether there are two distinct indices i and 
