            if (dist[d]>dist[u]+F[e]&&W[e]){
                dist[d]=dist[u]+F[e];
                if (!vis[d]){
                    que.push(d);
                    vis[d]=true;
                }
            }
        }
    }
    return dist[t]<INF;
}
int dfs(int u,int flow){
    if (u==t){ 
        vis[t]=true; maxflow+=flow;
        return flow;
    }
    int used=0;
    vis[u]=true;
    for (int e=Head[u];e;e=Next[e]){
        int d=V[e];
        if ((!vis[d]||d==t)&&W[e]&&dist[d]==dist[u]+F[e]){
            int minflow=dfs(d,min(flow-used,W[e]));
            if (minflow!=0) ans+=F[e]*minflow,W[e]-=minflow,W[e^1]+=minflow,used+=minflow;
            if (used==flow) break;
        }
    }
    return used;
}
