	s=k+n+n+k+1; t=s+1;
	for (int i=1;i<=k;i++) Addedge(s,i,1,0),Addedge(k+n+n+i,t,1,0);
	for (int i=1;i<=n;i++) Addedge(k+i,k+n+i,1,-p[i].v);
    for (int i=1;i<=k;i++) lx[i]=0,ly[i]=0,rx[i]=INF,ry[i]=INF;
	for (int i=1;i<=m;i++)
