			case 'U': for (int j=1;j<=k-q[i].b;j++) ry[j]=min(ry[j],q[i].a-1); break;
			case 'D': for (int j=q[i].b+1;j<=k;j++) ly[j]=max(ly[j],q[i].a+1); break;
			case 'L': for (int j=q[i].b+1;j<=k;j++) lx[j]=max(lx[j],q[i].a+1); break;
			case 'R': for (int j=1;j<=k-q[i].b;j++) rx[j]=min(rx[j],q[i].a-1); break;
		}
    for (int i=1;i<=k;i++)
