    rep(i, N) tmp[i] = min(abs(A[i][0]), abs(A[i][1])) * A[i][2];

    auto dfs = [&](auto&& dfs, string s, vl C) -> void {
        if(s.size()==N){
            ll cnt = 0;
            rep(i, N) cnt += (s[i] != '0');
            chmin(ans[cnt], accumulate(all(C), 0ll));
            return;
        }

        dfs(dfs, s + '0', C);

        ll n = s.size();
        vl D = C;
        rep(i, N) chmin(D[i], abs(A[i][0] - A[n][0]) * A[i][2]);
        dfs(dfs, s + '1', D);

        rep(i, N) chmin(C[i], abs(A[i][1] - A[n][1]) * A[i][2]);
        dfs(dfs, s + '2', C);
        return;
    };

    dfs(dfs, "", tmp);

    rep(i, N + 1) cout << ans[i] << endl;
}

