struct Node nodes[400000];
int connecth[9][2] = {{1, 8}, {2, 0}, {3, 1}, {4, 2}, {5, 3}, {6, 4}, {7, 5}, {8, 6}, {0, 7}}; 
int connectv[9][2] = {{6, 3}, {7, 4}, {8, 5}, {0, 6}, {1, 7}, {2, 8}, {3, 0}, {4, 1}, {5, 2}};
map<vector<int>, int> nummap;

void init(){
	vector<int> num(9);
	iota(num.begin(), num.end(), 0);
	int idx = 0;
	do{
		nummap[num] = idx;
		nodes[idx].idx = idx;
		idx++;
	}while(next_permutation(num.begin(), num.end()));

	iota(num.begin(), num.end(), 0);
	idx = 0;
	do{
		nummap[num] = idx;
		int zi = 0;
		for(int i = 0; i < 9; i++) if(num[i] == 0) zi = i;

		for(int i = 0; i < 2; i++){

			swap(num[zi], num[connecth[zi][i]]);
			nodes[idx].h[i] = nummap[num];
			swap(num[zi], num[connecth[zi][i]]);

			swap(num[zi], num[connectv[zi][i]]);
			nodes[idx].v[i] = nummap[num];
			swap(num[zi], num[connectv[zi][i]]);
		}
		idx++;
	}while(next_permutation(num.begin(), num.end()));
}

typedef pair<int, int> P;
int CH, CV;
int dijkstra(int si, int ei){
	vector<int> dist(400000, 1000000000);
	dist[si] = 0;
	priority_queue<P, vector<P>, greater<P> > queue;
	queue.push({0, si});
	while(queue.size()){
		P pp = queue.top();
		queue.pop();
		if(pp.second == ei) return pp.first;

		int vd = pp.first + CV;
		int hd = pp.first + CH; 
		for(int i = 0; i < 2; i++){
			if(dist[nodes[pp.second].h[i]] > hd){
				dist[nodes[pp.second].h[i]] = hd;
				queue.push({hd, nodes[pp.second].h[i]});
			}
			if(dist[nodes[pp.second].v[i]] > vd){
				dist[nodes[pp.second].v[i]] = vd;
				queue.push({vd, nodes[pp.second].v[i]});
			}
		}
	}
	return 1000000000;
}

int main(){
	init();
	while(cin >> CH >> CV, CH != 0 && CV != 0){
		vector<int> start(9), end(9);
		for(int i = 0; i < 9; i++){
			cin >> start[i];
		}
		for(int i = 0; i < 9; i++){
			cin >> end[i];
		}
		int si = nummap[start];
		int ei = nummap[end];
		cout << dijkstra(si, ei) << endl;
	}
}

