#include <stdio.h>
int min(int, int);
void floyds(int mat[10][10], int n)
{
  int i, j, k;
  for (k = 1; k <= n; k++)
    for (i = 1; i <= n; i++)
      for (j = 1; j <= n; j++)
        if (i == j)
          mat[i][j] = 0;
        else
          mat[i][j] = min(mat[i][j], mat[i][k] + mat[k][j]);
}
int min(int a, int b)
{
  if (a < b)
    return (a);
  else
    return (b);
}
