        COMPARISONS_COUNT = 0;
        SWAPS_COUNT = 0;
        LOOP_COUNT = 0;

        for (int reverseIndex = array.length - 1; reverseIndex > 1; reverseIndex--) {
            LOOP_COUNT++;
            ____grey("------\nreverseIndex: " + reverseIndex);

            for (int i = 0; i < reverseIndex; i++) {
                LOOP_COUNT++;
                ____grey("i: " + i);

                COMPARISONS_COUNT++;

                if (array[i] > array[i + 1]) {
                    SWAPS_COUNT++;
                    ____blue("Swapping: " + i + " and " + (i + 1));

                    // Swap code
                    int temp = array[i];

                    array[i] = array[i + 1];
                    array[i + 1] = temp;

                    __red("==> ");
                    __dump(array);
                    System.out.println("");
                }
            }
        }
    }

