it Find(int k,int x,int y,int L){
	int l=x,r=y-1,res=0;
	while(l<=r){
		int t1=f[k][x][mid][L];
		int t2=f[k][mid+1][y][L];
		res=max(res,min(t1,t2));
		if(t1<t2) r=mid-1;
		else l=mid+1;
	}
	return res;
}
