public class CountOfDivisors {
    public int[] solve(int[] A) {
        int max = A[0];

        // Calculate max to initialize divisor array of max length
        for (int i = 1; i < A.length; i++) {
            if (A[i] > max) {
                max = A[i];
            }
        }

        int[] divisor_array = new int[max + 1];
        divisor_array[1] = 1; // Setting number of divisor of 1 as 1

        // Setting initial divisors as 2 as all numbers will have at least 2 divisors
        // i.e. 1 and itself
        for (int j = 2; j < divisor_array.length; j++) {
            divisor_array[j] = 2;
        }

        // incrementing the number of divisors for each multiples of numbers
        for (int k = 2; k < divisor_array.length; k++) {

            for (int l = k + k; l < divisor_array.length; l += k) {
                divisor_array[l] += 1;
            }
        }

        // Fetching the values of numbers in array directly from divisor_array into the
        // output array
        for (int c = 0; c < A.length; c++) {
            A[c] = divisor_array[A[c]];
        }

        return A;

    }
}

#include <bits/stdc++.h>
#define MOD 1000000007
using namespace std;
int main()
{
    int n;
    cin >> n;
    vector<pair<int,int> > v;
    for(int i = 2;i <= n;i++)
    {
        bool flag = true;
        for(int j = 2;j <= sqrt(i);j++)
        {
            if(i % j == 0)
            {
                flag = false;
                break;
            }
        }
        if(flag)
        {
            v.push_back(make_pair(i,0));
        }
    }
    for(int i = 1;i <= n;i++)
    {
        int x = i;
        for(int j = 0;j < v.size();j++)
        {
            while(x % v[j].first == 0)
            {
                v[j].second++;
                x /= v[j].first;
            }
        }
    }
    long long int ans = 1;
    for(int i = 0;i < v.size();i++)
    {
        ans *= (v[i].second + 1);
        ans %= MOD;
    }
    cout << ans;
    
    return 0;
}

/**
 * Given an array containing n distinct numbers taken from 0, 1, 2, ..., n, find the one that is missing from the array.
 *
 * For example,
 * Given nums = [0, 1, 3] return 2.
 */

#include <iostream>
#include <vector>

int missingNumber( std::vector<int>& nums ) {
	int missing_sum = 0;
	for ( auto n : nums ) {
		missing_sum += n;
	}
	int n = nums.size();
	int expected_sum = 0;
	if ( n % 2 == 0 ) {
		expected_sum = (n/2) * (n + 1);
	} else {
		expected_sum = n * ( (n+1)/2 );
	}
	return expected_sum - missing_sum;
}

void printVec( std::vector<int> & vec ) {
	std::cout << "Vec:";
	for ( auto v : vec ) {
		std::cout << v << " ";
	}
	std::cout << std::endl;
}

int main() {
	std::vector<int> vec{ 0, 1, 3 };
	printVec(vec);
	std::cout << "Missing number in above vector is :" << missingNumber(vec) << std::endl;
	return 0;
}

#include <bits/stdc++.h>
#define pb push_back
#define ll long long
using namespace std;
int n , k;
int h[305];
ll dp[305][305][305];
const int INF = 1000 * 1000 * 1000;
int main() {
    cin >> n >> k;
    vector<int> choises;
    choises.pb(0);
    for(int i = 0; i < n; i++)
    {
        cin >> h[i];
        choises.pb(h[i]);
    }
    sort(choises.begin() , choises.end());
    for(int i = 0; i <= n; i++)
        for(int j = 0; j <= n; j++)
            for(int k = 0; k <= n; k++)
                dp[i][j][k] = INF * (ll)INF;
    dp[0][0][0] = 0;
    for(int i = 0; i < n; i++)
    {
        for(int j = 0; j <= i; j++)
        {
            ll mn = INF * (ll)INF;
            for(int next = 0; next <= n; next++)
            {
                mn = min(mn , dp[i][j][next] - choises[next]);
                dp[i + 1][j + (h[i] != choises[next])][next] = min(dp[i + 1][j + (h[i] != choises[next])][next] , mn + choises[next]);     
            }
            mn = INF * (ll)INF;
            for(int next = n; next >= 0; next--)
            {
                mn = min(mn , dp[i][j][next]);
                dp[i + 1][j + (h[i] != choises[next])][next] = min(dp[i + 1][j + (h[i] != choises[next])][next] , mn);     
            }
        }
    }
    ll ans = INF * (ll)INF;
    for(int j = 0; j <= k; j++)
        for(int l = 0; l <= n; l++)
            ans = min(ans , dp[n][j][l]);
    cout << ans;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define rep(i,n) for (int i = 0; i < n; ++i)
using ll = long long;
const ll MOD = 1000000007;//998244353;
// UnionFind
// coding: https://youtu.be/TdR816rqc3s?t=726
// comment: https://youtu.be/TdR816rqc3s?t=6822
struct UnionFind {
  vector<int> d;
  vector<int> mi, ma;
  UnionFind(int n=0): d(n,-1) {
     rep(i,n)mi.push_back(i);
     rep(i,n)ma.push_back(i);
  }
  int find(int x) {
    if (d[x] < 0) return x;
    return d[x] = find(d[x]);
  }
  bool unite(int x, int y) {
    x = find(x); y = find(y);
    if (x == y) return false;
    if (d[x] > d[y]) swap(x,y);
    mi[x] = min(mi[x],mi[y]);
    ma[x] = max(ma[x],ma[y]);
    d[x] += d[y];
    d[y] = x;
    return true;
  }
  bool same(int x, int y) { return find(x) == find(y);}
  int size(int x) { return -d[find(x)];}
  int Min(int x) {return mi[find(x)];}
  int Max(int x) {return ma[find(x)];}
};
int main() {
   ios::sync_with_stdio(false);
   cin.tie(0);
   int t; cin >> t;
   while(t--){
      int n; cin >> n;
      ll ans = 0;
      vector<pair<int,int>> postiv,negtiv;
      rep(i,n){
         int k, l, r; cin >> k >> l >> r;
         ans += r;
         int m = l-r;
         if (m>=0)postiv.push_back({m,k});
         else negtiv.push_back({m,k});
      }
      sort(postiv.begin(),postiv.end());
      reverse(postiv.begin(),postiv.end());
      sort(negtiv.begin(), negtiv.end());
      UnionFind uf(n+2);
      for (auto &&i : postiv){
         i.second = min(i.second, int(postiv.size()));
         if (uf.same(i.second, 0))continue;
         uf.unite(i.second, uf.Min(i.second)-1);
         ans += i.first;
      }
      for (auto &&i : negtiv){
         i.second = max(i.second+1, int(postiv.size()+1));
         if (uf.same(i.second, n+1))ans += i.first;
         else uf.unite(i.second, uf.Max(i.second)+1);
      }
      cout << ans << endl;
   }
}
